local config = {
  ui_story_5070_50700101_1_dialog_content = "Ahh! Ini benar-benar buruk...",
  ui_story_5070_50700101_2_dialog_content = "Kita hampir kehabisan dana cadangan terakhir kita.",
  ui_story_5070_50700101_3_dialog_content = "Saya terlalu sibuk akhir-akhir ini sehingga tidak bisa mengerjakan pekerjaan, dan Soroz baru saja menjalani perawatan...",
  ui_story_5070_50700101_4_dialog_content = "Entah bagaimana, kami hampir menghabiskan semua uang kami.",
  ui_story_5070_50700101_5_dialog_content = "Jika Vice mengetahui, dia akan membuatku makan biskuit dan kopi instan yang hampir kadaluarsa untuk setiap makan lagi—",
  ui_story_5070_50700101_6_dialog_content = "Oh? Apa yang kita miliki di sini?",
  ui_story_5070_50700101_7_dialog_content = "Vice! I-Itu bukan apa-apa, hanya...",
  ui_story_5070_50700101_8_dialog_content = "Hanya saja kita di ambang kebangkrutan, jadi kita harus mengaktifkan kembali protokol penjatahan masa perang kita. Begitu bukan?",
  ui_story_5070_50700101_9_dialog_content = "... Jadi kamu sudah tahu.",
  ui_story_5070_50700101_10_dialog_content = "Lebih aneh lagi kalau aku tidak melakukannya...",
  ui_story_5070_50700101_11_dialog_content = "Sejujurnya, kamu perlu lebih baik dalam mengawasi pengeluaran Colossus. Aku tidak bisa selalu di sini untuk membantu, tahu kan.",
  ui_story_5070_50700101_12_dialog_content = "Namun, sepertinya takdir ada di pihak kita. Lihat ini!",
  ui_story_5070_50700101_13_dialog_content = "Seorang kurir baru saja membawa pesan mendesak dari Lin Guild—",
  ui_story_5070_50700101_14_dialog_content = "\"Sayang PlayerName, masalah berikut ini menyangkut masa depan guild kita. Oleh karena itu, ini adalah keinginan tulus kami...\"",
  ui_story_5070_50700101_15_dialog_content = "\"...sebagai Navigator Colossus dan seorang ahli seni psikis, tolong berikan kami bantuanmu.\"",
  ui_story_5070_50700101_16_dialog_content = "Persekutuan Lin telah banyak membantu kita sebelumnya, tetapi sekarang mereka membutuhkan bantuan kita! Mereka juga menawarkan hadiah yang sangat besar!",
  ui_story_5070_50700101_17_dialog_content = "Kesempatan untuk meningkatkan hubungan kita dengan Lin Family DAN menghasilkan banyak uang?",
  ui_story_5070_50700101_18_dialog_content = "Terdengar bagus! Saya akan menentukan rute ke Umbraton segera!",
  ui_story_5070_50700101_19_dialog_content = "Tunggu, pekerjaan kali ini tidak ada di Umbraton.",
  ui_story_5070_50700101_20_dialog_content = "Ini berada di Twin Pavilions Bay.",
  ui_story_5070_50700101_21_dialog_content = "Tapi jika pekerjaan ini menyangkut masa depan seluruh Lin Guild, mengapa kita tidak pergi ke markas besar mereka terlebih dahulu?",
  ui_story_5070_50700101_22_dialog_content = "Karena menurut mereka, Twin Pavilions Bay sama pentingnya dengan Umbraton... jika tidak lebih penting.",
  ui_story_5070_50700101_23_dialog_content = "Carleen?! Saya kira kamu masih membaca di kamar!",
  ui_story_5070_50700101_24_dialog_content = "Aku masih punya cukup waktu luang untuk menemani kamu kali ini... Lagipula, aku satu-satunya di sini yang tahu Twin Pavilions Bay.",
  ui_story_5070_50700101_25_dialog_content = "Untuk Lumopolis, perdagangan antara Twin Pavilions Bay dan Umbraton sangat penting bagi perekonomian.",
  ui_story_5070_50700101_26_dialog_content = "Negeri yang jauh dari Longzhou membawa berbagai jenis barang ke pantai kita...",
  ui_story_5070_50700101_27_dialog_content = "Termasuk banyak produk berharga dan keterampilan yang tidak bisa kita reproduksi di Astra.",
  ui_story_5070_50700101_28_dialog_content = "Lin Guild juga berasal dari Longzhou.",
  ui_story_5070_50700101_29_dialog_content = "Setelah mengarungi samudra luas untuk sampai ke sini, tempat di mana mereka pertama kali mendarat adalah Twin Pavilions Bay.",
  ui_story_5070_50700101_30_dialog_content = "Hingga saat ini, pelabuhan ini merupakan satu-satunya pelabuhan yang dapat diakses oleh kapal dagang Longzhou di Astra. Dalam beberapa hal, ini adalah pondasi dari operasi komersial Keluarga Lin.",
  ui_story_5070_50700101_31_dialog_content = "Mengingat betapa mendesaknya undangan ini, saya tidak berpikir mereka berlebihan saat mengatakan <color=#FFB400>masa depan Lin Guild</color> sedang dipertaruhkan.",
  ui_story_5070_50700101_32_dialog_content = "Maka kita harus pergi ke sana sesegera mungkin.",
  ui_story_5070_50700101_33_dialog_content = "Tapi di mana tepatnya Twin Pavilions Bay ini?",
  ui_story_5070_50700101_34_dialog_content = "Izinkan saya menunjukkan jalannya kepada Anda.",
  ui_story_5070_50700101_35_dialog_content = "Kita bisa sampai di sana dengan cepat dengan mengikuti Sungai Emas sepanjang jalan hingga ke sumbernya.",
  ui_story_5070_50700101_36_dialog_content = "Luar biasa! Twin Pavilions Bay terlihat tidak seperti tempat lain di Astra!",
  ui_story_5070_50700101_37_dialog_content = "Sepertinya seseorang mengambil tempat dari dunia yang berbeda dan menjatuhkannya di sini.",
  ui_story_5070_50700101_38_dialog_content = "Saya juga hanya pernah membaca tentang itu di buku-buku.",
  ui_story_5070_50700101_39_dialog_content = "Keluarga Lin memimpin pengembangan daerah ini bersama orang-orang yang pertama kali melakukan perjalanan melalui jalur laut yang mereka dirikan.",
  ui_story_5070_50700101_40_dialog_content = "Akibatnya, semakin banyak pengunjung dari Longzhou yang mulai datang ke sini.",
  ui_story_5070_50700101_41_dialog_content = "Ini pada gilirannya menyebabkan pendirian kota bergaya Longzhou di pantai Astra.",
  ui_story_5070_50700101_42_dialog_content = "... Lebih menakjubkan secara langsung daripada deskripsi di buku-buku kami.",
  ui_story_5070_50700101_43_dialog_content = "Roti kukus, baru saja keluar dari kompor! Panas dan penuh dengan daging yang lezat! Mau mencoba roti kukus ini, teman-teman?",
  ui_story_5070_50700101_44_dialog_content = "Para pelancong yang baru tiba, bukan? Maka kalian harus mencoba teh kami!",
  ui_story_5070_50700101_45_dialog_content = "Pre-Rain Longjing, Yunmeng Silver Bud, Infinite Large-Leaf, dan bahkan Danshan Oolong: kami menyediakan berbagai jenis teh terkenal, langsung dari kebun teh Longzhou!",
  ui_story_5070_50700101_46_dialog_content = "Baunya luar biasa di sini!",
  ui_story_5070_50700101_47_dialog_content = "Banyak sekali hal yang belum pernah kulihat sebelumnya! Setelah menyelesaikan pekerjaan kita, kita harus kembali untuk berbelanja.",
  ui_story_5070_50700101_48_dialog_content = "Mengenai pekerjaan itu, apakah suratnya menyebutkan di mana kita bisa menemukan guild?",
  ui_story_5070_50700101_49_dialog_content = "<color=#e8d9bb>Tiba-tiba, angin kencang berhembus lewat.</color>",
  ui_story_5070_50700101_50_dialog_content = "Suratku—!!!",
  ui_story_5070_50700101_51_dialog_content = "H-Hah? Apakah capung emas itu mencengkeram suratku?",
  ui_story_5070_50700101_52_dialog_content = "Tunggu, ini bukan capung biasa... apakah benda ini terbuat dari logam?",
  ui_story_5070_50700101_53_dialog_content = "Kalau aku jadi kamu, aku akan lebih hati-hati memegang barang.",
  ui_story_5070_50700101_54_dialog_content = "Oh, uh... Terima kasih.",
  ui_story_5070_50700101_55_dialog_content = "Bukan masalah!",
  ui_story_5070_50700101_56_dialog_content = "... Apakah itu juga spesialitas Longzhou lainnya?",
  ui_story_5070_50700101_57_dialog_content = "Rupanya kau di sini! Permisi, tapi apakah kamu PlayerName?",
  ui_story_5070_50700101_58_dialog_content = "Ya, itu aku. Aku datang untuk membantu keluarga Lin!",
  ui_story_5070_50700101_59_dialog_content = "Saya adalah perwakilan dari Lin Guild. Kami sangat berterima kasih atas bantuan Anda. Sekarang jika Anda tidak keberatan, saya akan melanjutkan dan membahas detailnya dengan Anda.",
  ui_story_5070_50700101_60_dialog_content = "Saya yakin kalian semua cukup akrab dengan Lin Guild, bukan?",
  ui_story_5070_50700101_61_dialog_content = "Kami mengkhususkan diri dalam pengangkutan dan distribusi barang dan teknologi dari Longzhou yang biasanya tidak ditemukan di Asta.",
  ui_story_5070_50700101_62_dialog_content = "Namun, samudra luas yang memisahkan kedua benua kita ini penuh dengan bahaya.",
  ui_story_5070_50700101_63_dialog_content = "Saat ini, hanya kapal-kapal Keluarga Lin yang dapat melakukan pelayaran musiman di sepanjang rute yang didirikan oleh para leluhur mereka.",
  ui_story_5070_50700101_64_dialog_content = "Namun Shadowind, salah satu kapal dagang terpenting kami, belum terlihat selama lebih dari setengah tahun karena alasan yang masih belum diketahui.",
  ui_story_5070_50700101_65_dialog_content = "Tidak ada kontak selama lebih dari setengah tahun? Apakah ada sesuatu yang terjadi di Longzhou?",
  ui_story_5070_50700101_66_dialog_content = "Kami... juga tidak memiliki cara untuk mengetahui itu.",
  ui_story_5070_50700101_67_dialog_content = "Saat ini, satu-satunya cara untuk informasi berpindah antara kedua daratan kita adalah melalui kapal pedagang keluarga Lin.",
  ui_story_5070_50700101_68_dialog_content = "Bahkan Persekutuan Lin sendiri tidak memiliki cara lain untuk berkomunikasi dengan orang-orang mereka di Longzhou.",
  ui_story_5070_50700101_69_dialog_content = "Sayangnya, Nona Carleen benar.",
  ui_story_5070_50700101_70_dialog_content = "Baik Astra maupun Longzhou belum mengembangkan perangkat komunikasi yang mampu melintasi samudra luas di antara mereka.",
  ui_story_5070_50700101_71_dialog_content = "Namun, dua hari yang lalu, kami menerima sinyal dari perairan - sinyal yang digunakan secara internal oleh keluarga Lin.",
  ui_story_5070_50700101_72_dialog_content = "Kami percaya itu berasal dari salah satu kapal dagang yang tiba musim ini!",
  ui_story_5070_50700101_73_dialog_content = "Tapi sinyal itu tiba-tiba menghilang sebelum kami bisa merespon, dan kami belum pernah menerima sinyal seperti itu lagi sejak saat itu.",
  ui_story_5070_50700101_74_dialog_content = "Begitu ya. Kamu ingin kita menggunakan Colossus untuk mencari kapal yang hilang itu, 'kan?",
  ui_story_5070_50700101_75_dialog_content = "Tepat sekali! Mengingat kondisinya, kamu adalah harapan terbaik kami untuk menemukannya!",
  ui_story_5070_50700101_76_dialog_content = "Baiklah. Kami akan melakukan semua yang kami bisa.",
  ui_story_5070_50700101_77_dialog_content = "(Selama beberapa hari ke depan, kami menyisir lautan dari atas Colossus untuk mencari tanda-tanda kapal pedagang.)",
  ui_story_5070_50700101_78_dialog_content = "Kami telah mencari setiap inci laut di sekitar pelabuhan, tetapi kami belum melihat sepotong kayu apung pun di sini.",
  ui_story_5070_50700101_79_dialog_content = "Setidaknya, kita bisa mengesampingkan kemungkinan kapal menghilang di perairan terdekat. Itu kabar baik, bukan?",
  ui_story_5070_50700101_80_dialog_content = "Ya, tapi sepertinya sekarang pilihan kita hanya mencari lebih jauh lagi.",
  ui_story_5070_50700101_81_dialog_content = "Apakah itu baik-baik saja, PlayerName?",
  ui_story_5070_50700101_82_dialog_content = "Sejujurnya, aku tidak terlalu percaya diri tentang ini...",
  ui_story_5070_50700101_83_dialog_content = "Saat ini, Soroz tidak dilengkapi untuk menghadapi badai yang tak terduga di laut lepas.",
  ui_story_5070_50700101_84_dialog_content = "Saya juga tidak memiliki banyak pengalaman di luar sana. Tempat terjauh yang pernah saya kunjungi dari daratan utama adalah Cloud Island.",
  ui_story_5070_50700101_85_dialog_content = "Jika kapal hilang lebih jauh lagi, menyelamatkan mereka akan menjadi lebih sulit.",
  ui_story_5070_50700101_86_dialog_content = "...",
  ui_story_5070_50700101_87_dialog_content = "Hah? Kenapa kalian berdua menatapku diam-diam seperti itu?",
  ui_story_5070_50700101_88_dialog_content = "Karena yang bicara adalah kamu, dan biasanya...",
  ui_story_5070_50700101_89_dialog_content = "meski tak ada harapan, kamu selalu bisa menemukan solusi, bukan?",
  ui_story_5070_50700101_90_dialog_content = "Saya pikir kalian terlalu melebih-lebihkan ketangguhan saya... Tapi, kalian benar.",
  ui_story_5070_50700101_91_dialog_content = "Kami menerima pekerjaan ini, bagaimanapun. Yang paling sedikit yang bisa kami lakukan adalah mencoba yang terbaik.",
  ui_story_5070_50700101_92_dialog_content = "Aku akan menggunakan seluruh kekuatanku untuk memindai sebanyak mungkin area laut di sekitar kita. Semoga aku berhasil menemukan sesuatu.",
  ui_story_5070_50700101_93_option_content = "Force Boost!",
  ui_story_5070_50700101_94_dialog_content = "Arah angin... Ya! Ada banyak sekali Aurorian di arah sana!",
  ui_story_5070_50700101_95_dialog_content = "Laut yang melimpah memberikan! Sepertinya akhirnya kita memiliki petunjuk sekarang!",
  ui_story_5070_50700101_96_dialog_content = "Tunggu, kalian berdua, lihat ke sana. Langit semakin gelap, tapi laut di belakang kita tetap tenang dan sejuk seperti cermin.",
  ui_story_5070_50700101_97_dialog_content = "Ada badai yang mendekat dari depan!",
  ui_story_5070_50700101_98_dialog_content = "Saya melihat kapal itu! Sungguh sangat besar!",
  ui_story_5070_50700101_99_dialog_content = "Ini adalah kapal pedagang Keluarga Lin.",
  ui_story_5070_50700101_100_dialog_content = "Kita harus menyelamatkan mereka! Tapi saya tidak tahu apakah Colossus bisa–",
  ui_story_5070_50700101_101_dialog_content = "Tunggu, PlayerName.",
  ui_story_5070_50700101_102_dialog_content = "Lihat lebih dekat.",
  ui_story_5070_50700101_103_dialog_content = "Orang-orang di kapal... Saya bisa merasakan mereka sedikit gugup, tetapi mereka sama sekali tidak panik.",
  ui_story_5070_50700101_104_dialog_content = "Penumpang di geladak juga bergerak dengan tujuan yang jelas. Seolah-olah ada seseorang yang mengarahkan tindakan mereka dengan tangan yang mantap.",
  ui_story_5070_50700101_105_dialog_content = "C-Kapten! Sepertinya ada sesuatu yang terbang di atas kepala...",
  ui_story_5070_50700101_106_dialog_content = "Jangan khawatir tentang itu sekarang. Lanjutkan mengencangkan tali kapal, dan jaga kemudi tetap stabil.",
  ui_story_5070_50700101_107_dialog_content = "Perhatikan permukaan air.",
  ui_story_5070_50700101_108_dialog_content = "Kita memaksa menerobos masuk!",
  ui_story_5070_50700101_109_dialog_content = "Aye aye, Kapten!",
  ui_story_5070_50700101_110_dialog_content = "<color=#e8d9bb>Air pasang bergelora saat gelombang raksasa naik dan menerjang dengan suara gemuruh yang memekakkan telinga.</color>",
  ui_story_5070_50700101_111_dialog_content = "<color=#e8d9bb>Tetapi tepat ketika ombak yang menghantam bergabung menjadi pusaran mematikan, kapal berhasil menembus dan mencapai keamanan!</color>",
  ui_story_5070_50700101_112_dialog_content = "Syukurlah mereka berhasil keluar!",
  ui_story_5070_50700101_113_dialog_content = "Fiuh…",
  ui_story_5070_50700101_114_dialog_content = "Itu terlalu dekat! Aku pikir jantungku hampir berhenti!",
  ui_story_5070_50700101_115_dialog_content = "Kapten kapal itu pasti orang yang luar biasa.",
  ui_story_5070_50700101_116_dialog_content = "Lambung kapal ini penuh dengan kerusakan. Pasti sudah menghadapi banyak badai dalam perjalanannya ke sini.",
  ui_story_5070_50700101_117_dialog_content = "Saya terkejut kapal ini masih bisa berlayar dengan begitu mulus.",
  ui_story_5070_50700101_118_dialog_content = "Sisa perjalanan ini seharusnya cukup damai. Saya tidak berpikir mereka akan menghadapi bahaya lagi.",
  ui_story_5070_50700101_119_dialog_content = "Ayo kita kawal dulu sepanjang jalan kembali sebelum mencari tempat untuk mendarat.",
  ui_story_5070_50700101_120_dialog_content = "Ini Shadowind! Akhirnya kembali!",
  ui_story_5070_50700101_121_dialog_content = "Terlihat berbeda dari sebelumnya!",
  ui_story_5070_50700101_122_dialog_content = "Tahukah kamu? Itu karena ini adalah kapal yang benar-benar berbeda dari Shadowind sebelumnya.",
  ui_story_5070_50700101_123_dialog_content = "Beberapa tahun lalu, ada rumor bahwa Ye sedang mengembangkan inti mekanis baru untuk kapal terbesar milik Ji...",
  ui_story_5070_50700101_124_dialog_content = "Ini pasti salah satu kapal baru dan lebih canggih!",
  ui_story_5070_50700101_125_dialog_content = "Lebih kuat, lebih cepat, dan lebih tangguh dari sebelumnya! Iterasi terbaru dari Shadowind adalah satu-satunya dalam jenisnya!",
  ui_story_5070_50700101_126_dialog_content = "B-Begitu banyak orang.",
  ui_story_5070_50700101_127_dialog_content = "Setiap kali ada kapal yang tiba di pelabuhan, orang-orang di kota ini keluar untuk menyambut mereka. Ini semacam upacara kecil bagi mereka.",
  ui_story_5070_50700101_128_dialog_content = "Haha... Tapi dengan seberapa bersemangatnya kerumunan ini, kita hampir tidak bisa melihat kapal itu sendiri.",
  ui_story_5070_50700101_129_dialog_content = "PlayerName! Syukurlah aku berhasil menemukanmu!",
  ui_story_5070_50700101_130_dialog_content = "Hah? Ini milik Lin Guild...",
  ui_story_5070_50700101_131_dialog_content = "Ya, dan seperti yang Anda lihat, Shadowind akhirnya tiba dengan selamat di pelabuhan kita!",
  ui_story_5070_50700101_132_dialog_content = "Kapten juga ingin berbicara dengan Anda. Silakan mengikuti saya.",
  ui_story_5070_50700101_133_dialog_content = "Kapten? Tapi kita sama sekali tidak melakukan apa-apa...",
  ui_story_5070_50700101_134_dialog_content = "Itu hampir tidak benar.",
  ui_story_5070_50700101_135_dialog_content = "Izinkan saya memperkenalkan diri. Saya Mu Yuebai, kapten dari Shadowind.",
  ui_story_5070_50700101_136_dialog_content = "Mungkin itu bukan apa-apa bagi Caelestite legendaris, tetapi kau telah membantu Shadowind lebih dari yang kau tahu.",
  ui_story_5070_50700101_137_dialog_content = "Sebenarnya, kapal kami mengalami masalah serius setengah tahun yang lalu, dan kami kehilangan kontak dengan keluarga Lin.",
  ui_story_5070_50700101_138_dialog_content = "Bola armilari kami, alat yang digunakan oleh Keluarga Lin untuk mengarungi laut berdasarkan posisi bintang, juga hilang akibat insiden tersebut.",
  ui_story_5070_50700101_139_dialog_content = "Akibatnya, kami harus mengandalkan pengalaman dan peta laut saja untuk merencanakan jalur baru yang setengah buta melintasi samudra.",
  ui_story_5070_50700101_140_dialog_content = "Sepanjang perjalanan, kami dihadapkan pada badai ganas dan Eclipsites yang kejam, serta pusaran air yang kami temui sebelumnya juga sama berbahayanya.",
  ui_story_5070_50700101_141_dialog_content = "Kalau bukan karena bimbinganmu, PlayerName...",
  ui_story_5070_50700101_142_dialog_content = "Bahkan jika kita berhasil lolos dari pusaran air, kita akan tersesat di laut selama beberapa hari sebelum menemukan jalan ke sini.",
  ui_story_5070_50700101_143_dialog_content = "Jadi, meskipun kamu merasa tidak melakukan apa-apa untuk kami, saya harus menyampaikan rasa terima kasih yang tulus atas bimbingan dan perlindunganmu.",
  ui_story_5070_50700101_144_dialog_content = "Sesuai dengan tradisi guild, mereka yang membantu Keluarga Lin secara signifikan harus dibalas dua kali lipat dengan diundang ke dalam guild sebagai tamu terhormat.",
  ui_story_5070_50700101_145_dialog_content = "Jika cabang Twin Pavilions Bay tidak dapat menggantikanmu, maka dengan wewenangku sebagai kapten, aku akan membayar kembali kepadamu sendiri.",
  ui_story_5070_50700101_146_dialog_content = "A-Ahem! Jangan terburu-buru sekarang, Kapten Yuebai.",
  ui_story_5070_50700101_147_dialog_content = "Kami sudah mencapai kesepakatan dengan cara Astra. Selain itu, teman terhormat kami tidak sepenuhnya menyatu dengan entitas tertentu...",
  ui_story_5070_50700101_148_dialog_content = "Saya butuh jawabanmu, PlayerName. Maukah kamu bergabung dengan Lin Family?",
  ui_story_5070_50700101_149_dialog_content = "(Huh? Apakah ini hanya khayalan, atau Kapten mencoba untuk mengajakku bergabung secara resmi?!)",
  ui_story_5070_50700101_150_dialog_content = "C-Kapten! Memang benar aku datang ke sini mencari hadiah besar...",
  ui_story_5070_50700101_151_dialog_content = "Aku hanya membantu dalam cara yang paling kecil, itu kenyataannya. Dan aku hanya menjalankan tugas sesuai dengan perjanjian.",
  ui_story_5070_50700101_152_dialog_content = "Berbicara tentang pembayaran, keluarga Lin juga baik padaku. Berlaku untuk kedua belah pihak.",
  ui_story_5070_50700101_153_dialog_content = "Inilah mengapa saya tidak bisa menerima hadiah semacam itu, atau bergabung dengan keluarga Lin dalam hal ini.",
  ui_story_5070_50700101_154_dialog_content = "...",
  ui_story_5070_50700101_155_dialog_content = "Heheh, sudah lama aku tahu tentang cara keras Kapten Yuebai dalam berurusan dengan orang lain. Kebaikannya hanya diimbangi oleh kekuatan yang mengesankan...",
  ui_story_5070_50700101_156_dialog_content = "Bayangkan ditolak, sungguh sangat menghibur.",
  ui_story_5070_50700101_157_dialog_content = "Izinkan saya untuk membela anak muda ini...",
  ui_story_5070_50700101_158_dialog_content = "jadi dia bisa berbicara dengan Anda dalam istilah yang lebih lokal, apakah itu dapat diterima?",
  ui_story_5070_50700101_159_dialog_content = "Yep! Saya tidak mencari aliansi atau perlakuan khusus. Menjadi teman dengan Keluarga Lin sudah cukup bagus bagi saya!",
  ui_story_5070_50700101_160_dialog_content = "Saya tidak keberatan untuk mencoba naik Shadowind suatu hari nanti! Anda juga dipersilakan naik ke Colossus saya, Kapten Yuebai!",
  ui_story_5070_50700101_161_dialog_content = "... Shadowind terlalu rusak untuk dapat menghibur tamu dengan baik saat ini.",
  ui_story_5070_50700101_162_dialog_content = "Karena Lady Dantang telah menyatakan keinginannya dengan jelas, tentu saja saya akan mematuhinya.",
  ui_story_5070_50700101_163_dialog_content = "Maafkan saya jika tadi saya melampaui batas.",
  ui_story_5070_50700101_164_dialog_content = "Jangan khawatir! Kamu juga bisa memanggilku dengan namaku.",
  ui_story_5070_50700101_165_dialog_content = "Shadowind akan berlabuh di sini selama sekitar dua minggu ke depan. Dengan semua perbaikan yang diperlukan, kami mungkin membutuhkan layanan Anda lagi dalam waktu dekat.",
  ui_story_5070_50700101_166_dialog_content = "Tentu saja, Anda akan mendapatkan kompensasi yang murah hati.",
  ui_story_5070_50700101_167_dialog_content = "Terjadi baik! Beberapa teman-temanku masih menungguku, tetapi aku tak sabar ingin bertemu denganmu lagi!",
  ui_story_5070_50700101_168_dialog_content = "Tunggu sebentar, Kapten. Saya tidak diberitahu bahwa Shadowind akan tinggal di pelabuhan untuk waktu yang lama.",
  ui_story_5070_50700101_169_dialog_content = "Apakah ada permintaan lain yang—",
  ui_story_5070_50700101_170_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5070_50700101_171_dialog_content = "<color=#e8d9bb>Suara kayu terbelah terdengar dari kapal di atas kepala saat sepotong kayu besar tiba-tiba patah dan jatuh ke laut.</color>",
  ui_story_5070_50700101_172_dialog_content = "Apakah itu menjawab pertanyaan Anda?",
  ui_story_5070_50700101_173_dialog_content = "M-Mengerti... Shadowind memang sangat membutuhkan perbaikan. Saya akan segera menghubungi Li dan Sun.",
  ui_story_5070_50700101_174_dialog_content = "Tenang saja, mereka adalah ahli. Mereka mengawasi perbaikan yang dilakukan pada setiap kapal yang merapat di Twin Pavilions Bay.",
  ui_story_5070_50700101_175_dialog_content = "Ini sepertinya bukan pekerjaan yang mudah bagi mereka.",
  ui_story_5070_50700101_176_dialog_content = "Mengapa PlayerName belum kembali? Jangan bilang mereka menahannya?!",
  ui_story_5070_50700101_177_dialog_content = "Ugh, aku nggak bisa hanya diam di sini menunggu. Aku harus pergi mencarinya!",
  ui_story_5070_50700101_178_dialog_content = "Jadi ini Twin Pavilions Bay?",
  ui_story_5070_50700101_179_dialog_content = "Gaya arsitektur memang mengingatkan pada Longzhou, tetapi beberapa detail agak dieksoitiskan. Menarik, setidaknya.",
  ui_story_5070_50700101_180_dialog_content = "Ayo berkeliling kota, Jiu.",
  ui_story_5070_50700101_181_dialog_content = "Kebetulan aku tahu bahwa ada seseorang dari Ye yang sudah berada di sini cukup lama...",
  ui_story_5070_50700101_182_dialog_content = "Saya yakin dia bisa menunjukkan banyak pemandangan menarik di sini.",
  ui_story_5070_50700101_183_dialog_content = "Perjalanan ini panjang dan melelahkan, Yang Mulia. Bukankah kita harus mencari tempat untuk Anda beristirahat terlebih dahulu?",
  ui_story_5070_50700101_184_dialog_content = "Wah, wah, sepertinya Anda melewatkan intinya, Nona Jiu.",
  ui_story_5070_50700101_185_dialog_content = "Bagian terbaik dari setiap perjalanan adalah menikmati pemandangan dan menjelajahi jalanan sesuka hati.",
  ui_story_5070_50700101_186_dialog_content = "Izinkan saya menemani kalian berdua. Mungkin saya bisa menemukan tanah yang lebih baik untuk Putri Dantang melangkah?",
  ui_story_5070_50700101_187_dialog_content = "Hmph. Aku lelah.",
  ui_story_5070_50700101_188_dialog_content = "Jiu benar, kita harus kembali ke Yuebai dan istirahat untuk hari ini.",
  ui_story_5070_50700101_189_dialog_content = "Hei... Tunggu saya, Yang Mulia!",
  ui_story_5070_50700101_190_dialog_content = "Aku bisa memiliki berbagai jenis orang bersamaku. Teman, prajurit, bahkan musuh...",
  ui_story_5070_50700101_191_dialog_content = "Tapi penipu tidak memiliki tempat di sisiku.",
  ui_story_5070_50700101_192_dialog_content = "Jangan terlalu kejam, Yang Mulia. Terlebih setelah semua yang telah kita lalui bersama...",
  ui_story_5070_50700101_193_dialog_content = "(Dia sangat cantik... Tunggu, apakah tadi pria itu memanggilnya \"Yang Mulia\"?!)",
  ui_story_5070_50700101_194_dialog_content = "Vice? Vice! Apa yang sedang kamu lihat?",
  ui_story_5070_50700101_195_dialog_content = "Aaah! Akhirnya kamu kembali!",
  ui_story_5070_50700101_196_dialog_content = "Saya hanya berpikir bahwa selain membawa banyak barang...",
  ui_story_5070_50700101_197_dialog_content = "Shadowind juga membawa banyak orang menarik. Beberapa di antaranya bahkan mungkin menjadi teman kita!",
  ui_story_5070_50700101_198_dialog_content = "Agh, ini tidak akan berhasil. Andai saja ini masih Shadowind yang lama.",
  ui_story_5070_50700101_199_dialog_content = "Saya hampir tidak bisa mengenali teknik apa pun yang digunakan pada model baru ini, baik itu tungku, peredam panas, maupun tahan air.",
  ui_story_5070_50700101_200_dialog_content = "Jangan bahkan mulai bicara tentang semua komponen Ye yang mereka campurkan ke dalamnya.",
  ui_story_5070_50700101_201_dialog_content = "Lihat, 'kan?",
  ui_story_5070_50700101_202_dialog_content = "...",
  ui_story_5070_50700101_203_dialog_content = "Maaf... Apa yang tampaknya menjadi masalah, semuanya?",
  ui_story_5070_50700101_204_dialog_content = "Putri Dantang!",
  ui_story_5070_50700101_205_dialog_content = "Saya lebih suka tidak mengganggu Anda dengan detailnya, Yang Mulia. Bagaimanapun, Anda memiliki misi yang harus dijalankan.",
  ui_story_5070_50700101_206_dialog_content = "Masih kesal sama aku karena aku lebih menonjol tadi, Yuebai?",
  ui_story_5070_50700101_207_dialog_content = "Kamu terlalu akrab dengan urusan dan perselisihan antara delapan kerajaan vasal di Longzhou.",
  ui_story_5070_50700101_208_dialog_content = "Meskipun aku di sini sebagai perwakilan dari Ji, bagi mereka, aku akan selalu menjadi sandera Ye.",
  ui_story_5070_50700101_209_dialog_content = "Mendapatkan kepercayaan penuh kerajaan Ji sangat sulit, mengingat identitas saya.",
  ui_story_5070_50700101_210_dialog_content = "Inilah mengapa saya secara sukarela berlayar menyeberangi laut dan datang ke Astra.",
  ui_story_5070_50700101_211_dialog_content = "Semoga tindakanku dapat membuktikan ketulusanku.",
  ui_story_5070_50700101_212_dialog_content = "Semua yang kulakukan, kulakukan demi kedamaian dan kemakmuran bersama kedua kerajaan.",
  ui_story_5070_50700101_213_dialog_content = "Dan karena Shadowind erat kaitannya dengan perdagangan, bukankah saya juga harus peduli dengan kesejahteraannya?",
  ui_story_5070_50700101_214_dialog_content = "Jika begitu, maka secara alami saya harus melakukan segala yang bisa saya lakukan demi kepentingannya.",
  ui_story_5070_50700101_215_dialog_content = "... Ini perbaikan Shadowind.",
  ui_story_5070_50700101_216_dialog_content = "Kapal baru ini dilengkapi dengan teknologi mutakhir yang dikembangkan dengan cermat oleh teknisi terbaik Ye. Ini sangat berbeda dari pendahulunya.",
  ui_story_5070_50700101_217_dialog_content = "Tanpa pengrajin yang mampu menguasai teknologi baru ini, saya khawatir memperbaiki Shadowind akan menjadi proyek yang panjang dan sulit.",
  ui_story_5070_50700101_218_dialog_content = "Twin Pavilions Bay memiliki banyak bahan mentah dan tukang kapal untuk bekerja dengannya, tetapi tidak satupun dari mereka yang siap untuk menangani Shadowind...",
  ui_story_5070_50700101_219_dialog_content = "Fyuh!",
  ui_story_5070_50700101_220_dialog_content = "Putri Dantang?",
  ui_story_5070_50700101_221_dialog_content = "Kalau masalahnya lain, sungguh aku tidak akan bisa membantu sama sekali.",
  ui_story_5070_50700101_222_dialog_content = "Tapi jika Anda membutuhkan seorang pengrajin Ye yang berbakat, saya rasa saya tahu orang yang tepat untuk pekerjaan itu.",
  ui_story_5070_50700101_223_dialog_content = "Berapa lama waktu yang Anda rencanakan untuk memperbaiki Shadowind, Yuebai?",
  ui_story_5070_50700101_224_dialog_content = "Setengah bulan.",
  ui_story_5070_50700101_225_dialog_content = "Maka seharusnya ada cukup waktu.",
  ui_story_5070_50700101_226_dialog_content = "Tenanglah. Seniman terhebat Ye kebetulan ada di sini di Twin Pavilions Bay.",
  ui_story_5070_50700101_227_dialog_content = "Dengan menggunakan burung pemancar yang dia ciptakan ini, seharusnya aku bisa menemukannya segera!",
  ui_story_5070_50700101_228_dialog_content = "Sekarang Shadowind telah berhasil berlabuh dengan aman di pelabuhan, pekerjaan kita di sini seharusnya selesai... Huh...",
  ui_story_5070_50700101_229_dialog_content = "Apakah ada sesuatu yang mengganggumu?",
  ui_story_5070_50700101_230_dialog_content = "Aku tahu apa itu. PlayerName membuat kesepakatan besar dan benar tentang menolak tawaran Kapten Yuebai...",
  ui_story_5070_50700101_231_dialog_content = "Pasti menyesal telah menolak tawaran yang begitu menggiurkan.",
  ui_story_5070_50700101_232_dialog_content = "Kalau kamu tahu ini akan mengganggumu sebanyak ini, seharusnya kamu menerima saja saat itu.",
  ui_story_5070_50700101_233_dialog_content = "Mana mungkin…",
  ui_story_5070_50700101_234_dialog_content = "Meskipun perbaikan Soroz dan pengeluaran sehari-hari membuat keuangan kita menjadi ketat akhir-akhir ini...",
  ui_story_5070_50700101_235_dialog_content = "Meskipun aku tidak tahu di mana aku akan menemukan pekerjaan lain...",
  ui_story_5070_50700101_236_dialog_content = "Aku tidak akan menerima pembayaran untuk sesuatu yang tidak kulakukan.",
  ui_story_5070_50700101_237_dialog_content = "Lagipula, saya masih cukup muda. Saya tidak ingin menghabiskan tahun-tahun terbaik dalam hidup saya bekerja sebagai pegawai untuk Lin Guild atau semacamnya...",
  ui_story_5070_50700101_238_dialog_content = "Saya tidak berpikir bergabung dengan Lin Guild berarti Anda harus menjadi seorang juru tulis.",
  ui_story_5070_50700101_239_dialog_content = "Kurasa kamu mungkin melewatkan intinya di sini, Carleen.",
  ui_story_5070_50700101_240_dialog_content = "Saudara-saudaraku di Twin Pavilions Bay!!!",
  ui_story_5070_50700101_241_dialog_content = "Wow, keras sekali! Darimana suara itu berasal?",
  ui_story_5070_50700101_242_dialog_content = "Apakah mereka memasang sistem pengeras suara militer Illumina di atap atau semacamnya?",
  ui_story_5070_50700101_243_dialog_content = "Setelah perjalanan panjang dan melelahkan dari Longzhou, Shadowind akan berada di pelabuhan selama kurang lebih dua minggu,",
  ui_story_5070_50700101_244_dialog_content = "dan akan menjalani pekerjaan perbaikan yang sangat dibutuhkan!",
  ui_story_5070_50700101_245_dialog_content = "Untuk itu, kami merekrut porter dan pengrajin yang mampu di daerah ini!",
  ui_story_5070_50700101_246_dialog_content = "Semua orang diundang untuk mendaftar! Mereka yang meminjamkan pengetahuan dan tenaga kerja mereka untuk upaya perbaikan kami",
  ui_story_5070_50700101_247_dialog_content = "akan menuai manfaat yang dibawa Shadowind dari seberang laut!",
  ui_story_5070_50700101_248_dialog_content = "(Menghela nafas) B-Bos... Cepat kumpulkan pekerja!",
  ui_story_5070_50700101_249_dialog_content = "Aku harus merekrut staf paruh waktu lebih banyak segera. Aku akan mengerjakan pengumuman sekarang juga.",
  ui_story_5070_50700101_250_dialog_content = "Kurasa kamu tidak perlu! Saya yakin seluruh kota sudah mendengar beritanya!",
  ui_story_5070_50700101_251_dialog_content = "Tapi bagaimana? Saya tidak tahu Twin Pavilions Bay memiliki sistem seperti ini...",
  ui_story_5070_50700101_252_dialog_content = "Apakah ini ada hubungannya dengan apa yang dikatakan Kapten Yuebai sebelumnya...?",
  ui_story_5070_50700101_253_dialog_content = "Waktu yang sempurna! Ayo lihat apakah ada pekerjaan bagus yang tersedia!",
  ui_story_5070_50700101_254_dialog_content = "Kita mungkin bisa menghasilkan cukup banyak uang selama kita di sini!",
  ui_story_5070_50700201_1_dialog_content = "Dan begitu kami menghabiskan dua minggu yang sangat produktif di Twin Pavilions Bay.",
  ui_story_5070_50700201_2_dialog_content = "Selain melakukan berbagai macam pekerjaan aneh untuk Shadowind, saya juga melakukan banyak hal lain...",
  ui_story_5070_50700201_3_dialog_content = "Misalnya, ada suatu hari ketika Carleen dan saya sedang mengawasi perbaikan yang dilakukan pada Shadowind.",
  ui_story_5070_50700201_4_dialog_content = "Seorang peramal aneh yang memegang sekelompok tongkat aneh muncul dan menipu kami untuk mengambil sekelompok tongkat keberuntungan aneh.",
  ui_story_5070_50700201_5_dialog_content = "Saya juga membantu Vice bersiap untuk tarian khusus yang konon membawa berkah dan menghindarkan bencana di laut.",
  ui_story_5070_50700201_6_dialog_content = "Itu juga hari di mana kami secara resmi bertemu dengan Putri Dantang, yang sebelumnya telah menyelamatkan saya dari situasi yang tidak nyaman itu.",
  ui_story_5070_50700201_7_dialog_content = "Awalnya, saya khawatir seorang bangsawan dari negara asing akan sulit untuk diajak bicara, tetapi ternyata dia sangat mudah didekati dan cerdas.",
  ui_story_5070_50700201_8_dialog_content = "Setelah itu, dia dan pelayan berpakaian hitamnya mengajari kami tentang budaya unik Longzhou.",
  ui_story_5070_50700201_9_dialog_content = "Sayangnya, Carleen dan Vice harus kembali ke Lumopolis dan Illumina setelah menerima perintah baru.",
  ui_story_5070_50700201_10_dialog_content = "Tapi itu tidak akan menghentikanku untuk menghasilkan lebih banyak uang untuk kita! Ini adalah kesempatan langka, setelah semua!",
  ui_story_5070_50700201_11_dialog_content = "... PlayerName?",
  ui_story_5070_50700201_12_dialog_content = "Hah? Oh! Maaf, Tuan Putri Dantang, aku terdiam sejenak di sana.",
  ui_story_5070_50700201_13_dialog_content = "Tidak apa-apa, saya baru saja akan sampai ke bagian yang penting.",
  ui_story_5070_50700201_14_dialog_content = "Juga, bukankah aku sudah bilang untuk memanggilku saja Dantang?",
  ui_story_5070_50700201_15_dialog_content = "Ya, maaf Prin—maksudku Dantang.",
  ui_story_5070_50700201_16_dialog_content = "(Hela napas) Aku ke sini bukan untuk mendengar permintaan maaf, tahu.",
  ui_story_5070_50700201_17_dialog_content = "Aku berjanji pada Yuebai bahwa aku akan menemukan pengrajin yang sempurna untuk memperbaiki kapalnya, bukan?",
  ui_story_5070_50700201_18_dialog_content = "Di bawah pengawasannya, perbaikan Shadowind berjalan lancar, dan kapal sudah dalam tahap terakhir perawatan.",
  ui_story_5070_50700201_19_dialog_content = "Untuk alasan itu, kami telah memulai persiapan pesta perayaan untuk memperingati selesainya perbaikan Shadowind.",
  ui_story_5070_50700201_20_dialog_content = "Untuk misi saya sendiri, upaya saya juga terbukti berhasil.",
  ui_story_5070_50700201_21_dialog_content = "Utusan Lumopolis akhirnya kembali dengan jawaban berkat Lady Carleen.",
  ui_story_5070_50700201_22_dialog_content = "Mereka telah setuju untuk menyambut kita sebagai pengunjung dari Longzhou dan membahas baik negosiasi perdagangan maupun langkah-langkah melawan Eclipsite.",
  ui_story_5070_50700201_23_dialog_content = "Utusan juga akan menghadiri pesta tersebut, dan akan bepergian ke Longzhou dengan menaiki Shadowind untuk mengunjungi Ji.",
  ui_story_5070_50700201_24_dialog_content = "Sepertinya misi berhasil, Dantang! Selamat!",
  ui_story_5070_50700201_25_dialog_content = "Heheh, terima kasih, PlayerName.",
  ui_story_5070_50700201_26_dialog_content = "Nah, alasan saya datang ke sini hari ini adalah untuk mengundang Anda juga ke perjamuan tersebut.",
  ui_story_5070_50700201_27_dialog_content = "Maksud kamu aku juga bisa ikut? Aku merasa terhormat!",
  ui_story_5070_50700201_28_dialog_content = "Dan kami akan merasa sangat terhormat jika Anda ada di sana.",
  ui_story_5070_50700201_29_dialog_content = "Sayang sekali Nona Vice dan Lady Carleen tidak bisa datang. Saya benar-benar ingin menyampaikan rasa terima kasih saya atas bantuan mereka secara langsung.",
  ui_story_5070_50700201_30_dialog_content = "Aku akan memastikan untuk memperlakukanmu dengan sangat baik saat mereka tidak ada.",
  ui_story_5070_50700201_31_dialog_content = "Itu terdengar bagus. Aku akan menyelesaikan sisa pekerjaanku sementara itu. Sampai jumpa di jamuan nanti!",
  ui_story_5070_50700201_32_dialog_content = "Begini...",
  ui_story_5070_50700201_33_dialog_content = "Antarkan tagihan ke toko di bagian timur kota, selesai. Kumpulkan dan kembalikan alat-alat pekerja, selesai.",
  ui_story_5070_50700201_34_dialog_content = "Mengirimkan pengiriman barang ke gudang ini di ujung Jalan Chunxi, periksa... tapi tidak benar-benar.",
  ui_story_5070_50700201_35_dialog_content = "*Berdesah*",
  ui_story_5070_50700201_36_dialog_content = "Saya bangun pagi untuk mengantarkan kiriman ini, tetapi belum ada yang datang mengambilnya.",
  ui_story_5070_50700201_37_dialog_content = "Aku bahkan sempat menyelesaikan beberapa hal lain sementara itu. Aku heran kenapa belum ada orang di sini?",
  ui_story_5070_50700201_38_dialog_content = "Hari ini adalah hari pesta Shadowind. Aku akan terlambat jika klien tidak datang.",
  ui_story_5070_50700201_39_dialog_content = "Apa ini dengan kotak-kotak berbentuk aneh ini?",
  ui_story_5070_50700201_40_dialog_content = "Apakah mereka benar-benar membutuhkan barang-barang ini untuk memperbaiki kapal?",
  ui_story_5070_50700201_41_dialog_content = "...Hah?",
  ui_story_5070_50700201_42_dialog_content = "Mengapa rasanya ada yang aneh dengan kotak-kotak ini?",
  ui_story_5070_50700201_43_dialog_content = "<color=#e8d9bb>Kriek—Kriek—</color>",
  ui_story_5070_50700201_44_dialog_content = "...?! Apa yang terjadi?",
  ui_story_5070_50700201_45_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5070_50700201_46_dialog_content = "Apakah itu semacam... monster kepiting? T-Tunggu, mundur!",
  ui_story_5070_50700201_47_dialog_content = "Penjepit itu terlihat mengerikan, tapi untungnya aku cukup cepat untuk menghindarinya...",
  ui_story_5070_50700201_48_dialog_content = "Mendesis-!",
  ui_story_5070_50700201_49_dialog_content = "Wow—Bisa menyemburkan api?!",
  ui_story_5070_50700201_50_dialog_content = "<color=#e8d9bb>Sebuah semburan api yang menyala keluar dari mulut monster.</color>",
  ui_story_5070_50700201_51_dialog_content = "<color=#e8d9bb>Tiba-tiba, sebuah payung besar muncul.</color>",
  ui_story_5070_50700201_52_dialog_content = "<color=#e8d9bb>Berkilau terang saat berputar dengan cepat, payung logam ini dengan sigap menyebar dan memadamkan api yang datang.</color>",
  ui_story_5070_50700201_53_dialog_content = "Cuaca kering membuat benda mudah terbakar, jadi berhati-hatilah!",
  ui_story_5070_50700201_54_dialog_content = "<color=#e8d9bb>Nyala api monster tampaknya tak ada habisnya, namun payung itu berhasil menahannya dengan baik. Hanya panas yang samar dari api yang berhasil menembus.</color>",
  ui_story_5070_50700201_55_dialog_content = "Suara itu terdengar familiar... Hei, aku ingat sekarang! Kamu menggunakan capung itu untuk membantuku menangkap suratku sebelumnya!",
  ui_story_5070_50700201_56_dialog_content = "Tapi apa masalah dengan parasol ini...?",
  ui_story_5070_50700201_57_dialog_content = "Oh, jika aku jadi kamu, aku tidak akan menyentuh itu sekarang. Aku tidak bertanggung jawab atas cedera apa pun yang mungkin kamu alami!",
  ui_story_5070_50700201_58_dialog_content = "Lagi pula, saya masih harus berurusan dengan bajingan-bajingan ini.",
  ui_story_5070_50700202_1_dialog_content = "Me-Menakjubkan!",
  ui_story_5070_50700202_2_dialog_content = "(Meskipun terlihat seperti payung biasa, tetapi lebih tajam daripada pedang legendaris sekalipun!)",
  ui_story_5070_50700202_3_dialog_content = "(Ketika terbuka, tidak ada air atau api yang bisa melewati.)",
  ui_story_5070_50700202_4_dialog_content = "(Ketika tertutup, itu berubah menjadi pedang yang tak terhentikan.)",
  ui_story_5070_50700202_5_dialog_content = "(Mataku bahkan tak bisa mengikuti gerakannya!)",
  ui_story_5070_50700202_6_dialog_content = "(Dengan sekali gerakan pergelangan tangan dan putaran payungnya, dia mengubah monster-monster itu menjadi tumpukan besi tua.)",
  ui_story_5070_50700202_7_dialog_content = "Hiss—",
  ui_story_5070_50700202_8_dialog_content = "(Tunggu, mereka terbuat dari logam? Apakah itu berarti seseorang yang membuat benda-benda ini?)",
  ui_story_5070_50700202_9_dialog_content = "Mengapa di dunia ini ada orang yang ingin membuat kepiting mekanik raksasa se-menakutkan ini...?",
  ui_story_5070_50700202_10_dialog_content = "Kepiting api ini hanyalah salah satu dari banyak Clockwork Beasts yang secara rutin digunakan di bengkel kerajaan Ye.",
  ui_story_5070_50700202_11_dialog_content = "Mereka dirancang untuk membantu dalam pengelasan dan konstruksi sambungan, tidak lebih dari itu.",
  ui_story_5070_50700202_12_dialog_content = "Penjepit mereka dan kemampuan mereka untuk melepaskan api kecil yang terkendali membuat mereka menjadi tambahan yang berguna untuk setiap bengkel!",
  ui_story_5070_50700202_13_dialog_content = "Pengelasan? Konstruksi sambungan? Tunggu, jadi apakah itu berarti mereka menganggap saya sebagai bahan mentah atau semacamnya?",
  ui_story_5070_50700202_14_dialog_content = "Nah... dari kekuatan dan ketahananmu, jelas kamu tidak cocok untuk itu.",
  ui_story_5070_50700202_15_dialog_content = "Secara logika, kepiting api seharusnya tidak membuat kesalahan sepele seperti ini...",
  ui_story_5070_50700202_16_dialog_content = "Aku bingung harus merasa bagaimana tentang itu.",
  ui_story_5070_50700202_17_dialog_content = "Lebih lanjut, Ye memiliki peraturan yang sangat ketat mengenai penyebaran dan penggunaan Binatang Jam.",
  ui_story_5070_50700202_18_dialog_content = "Untuk mereka tidak hanya muncul di tempat ini, bahkan menyerang orang...",
  ui_story_5070_50700202_19_dialog_content = "Ini pasti berarti ada seseorang yang punya maksud buruk.",
  ui_story_5070_50700202_20_dialog_content = "Jadi, kamu mau keluar sendiri atau aku yang harus membuat langkah pertama?",
  ui_story_5070_50700202_21_dialog_content = "(Ada orang lain di sini?!)",
  ui_story_5070_50700202_22_dialog_content = "<color=#e8d9bb>Sosok bayangan tiba-tiba melompat keluar dari bayangan dan berlari kencang menuju pintu.</color>",
  ui_story_5070_50700202_23_dialog_content = "Tunggu!",
  ui_story_5070_50700202_24_dialog_content = "(Dia menghindari serangan... Aku harus memotong jalannya entah bagaimana!)",
  ui_story_5070_50700202_25_dialog_content = "Force Boost!",
  ui_story_5070_50700202_26_dialog_content = "Santai, aku tahu peraturannya. Lagipula, aku sudah melakukan hal seperti ini di Umbraton selama bertahun-tahun.",
  ui_story_5070_50700202_27_dialog_content = "Setelah menerima pembayaran dari klien, sudah sewajarnya kita melakukan sesuai dengan keinginan mereka.",
  ui_story_5070_50700202_28_dialog_content = "Lagipula, mereka hanya meminta saya untuk belajar cara mengoperasikan, uh... Apa namanya kepiting raksasa ini lagi?",
  ui_story_5070_50700202_29_dialog_content = "\"Kepiting yang Ditempa di Tungku\" atau semacamnya, kan?",
  ui_story_5070_50700202_30_dialog_content = "Pasti akan menyakitkan, itu sudah pasti.",
  ui_story_5070_50700202_31_dialog_content = "Tapi rasa sakit ini tak ada artinya jika itu berarti aku bisa membuat Keluarga Lin dan Shadowind menderita.",
  ui_story_5070_50700202_32_dialog_content = "(Dia menargetkan Shadowind? Tapi kenapa...?)",
  ui_story_5070_50700202_33_dialog_content = "Minggir!",
  ui_story_5070_50700202_34_dialog_content = "Ah—",
  ui_story_5070_50700202_35_dialog_content = "Hati-hati.",
  ui_story_5070_50700202_36_dialog_content = "T-Terima kasih sudah menangkapku. Aku pasti akan terluka parah jika kamu tidak melakukannya. Siapa itu—",
  ui_story_5070_50700202_37_dialog_content = "Jangan pedulikan dia. Tidak ada gunanya mengejar mangsa yang terjepit, kecuali jika kamu ingin digigit.",
  ui_story_5070_50700202_38_dialog_content = "Pria itu hanyalah boneka yang tak penting.",
  ui_story_5070_50700202_39_dialog_content = "Untuk orang yang menarik talinya, saya sudah memiliki kecurigaan saya.",
  ui_story_5070_50700202_40_dialog_content = "Saya harus mengandalkan orang-orang di sini di Twin Pavilions Bay untuk membantu saya menemukan ini–",
  ui_story_5070_50700202_41_dialog_content = "T-Tunggu, suara itu!",
  ui_story_5070_50700202_42_dialog_content = "Tak heran suaramu terdengar begitu familiar! Kamulah yang memasang semua pengeras suara itu di menara gerbang kota!",
  ui_story_5070_50700202_43_dialog_content = "Siapa sebenarnya kamu?",
  ui_story_5070_50700202_44_dialog_content = "Hah? Kamu tidak tahu siapa aku?",
  ui_story_5070_50700202_45_dialog_content = "A-apa?",
  ui_story_5070_50700202_46_dialog_content = "Haha, hanya bercanda! Aku tidak begitu sombong sampai menyalahkan seseorang di seberang laut karena tidak tahu siapa aku!",
  ui_story_5070_50700202_47_dialog_content = "Tetap saja, aku terkejut Dantang belum memperkenalkan aku, mengingat betapa banyak yang dia ceritakan tentangmu.",
  ui_story_5070_50700202_48_dialog_content = "Itu sama sekali tidak adil!",
  ui_story_5070_50700202_49_dialog_content = "Omong-omong, izinkan saya memperkenalkan diri.",
  ui_story_5070_50700202_50_dialog_content = "Namaku Xuan Ji. Aku adalah seorang pengrajin.",
  ui_story_5070_50700202_51_dialog_content = "Dan seperti Tuan Putri Dantang, saya juga berasal dari ibukota pengrajin Longzhou: kerajaan bawahan Ye.",
  ui_story_5070_50700202_52_dialog_content = "Saya telah tinggal di Twin Pavilions Bay untuk beberapa waktu sekarang, menghabiskan waktu dengan santai dan melakukan hal-hal seperti mengembalikan barang-barang yang hilang kepada pemilik yang sah.",
  ui_story_5070_50700202_53_dialog_content = "Tapi berkat rekomendasi berat dari Putri Dantang, sekarang saya menjadi kepala teknisi sementara untuk Shadowind.",
  ui_story_5070_50700202_54_dialog_content = "Saya tidak hanya bertanggung jawab atas perbaikan Shadowind, tetapi juga pemeliharaan Burung Jam Mekanik pengirim suara yang saya pinjamkan ke Lin Guild.",
  ui_story_5070_50700202_55_dialog_content = "Burung Mekanik? Jadi begitu cara kalian melakukannya...?",
  ui_story_5070_50700202_56_dialog_content = "Yep! Pada dasarnya, mereka hanyalah loudspeaker terbang yang tidak perlu digantung.",
  ui_story_5070_50700202_57_dialog_content = "Tapi itu tidak menghentikan saya untuk hati-hati menempelkan paruh dan bulu pada mereka!",
  ui_story_5070_50700202_58_dialog_content = "... Jadi kamu adalah pengrajin hebat yang Dantang ceritakan padaku.",
  ui_story_5070_50700202_59_dialog_content = "Kamu memang sesuai dengan namamu!",
  ui_story_5070_50700202_60_dialog_content = "Saya juga harus menyebutkan sesuatu.",
  ui_story_5070_50700202_61_dialog_content = "Kepiting besar dan menakutkan yang berserakan di tanah itu? Aku juga yang mendesainnya.",
  ui_story_5070_50700202_62_dialog_content = "?",
  ui_story_5070_50700301_1_dialog_content = "Tanpa berlama-lama, mari kita sambut Kapten Yuebai yang akan menyampaikan pidato pada pesta malam ini!",
  ui_story_5070_50700301_2_dialog_content = "Perbaikan yang lancar dan cepat pada Shadowind adalah hasil dari kerja keras dan ketekunan semua orang.",
  ui_story_5070_50700301_3_dialog_content = "Perjamuan malam ini adalah untuk menghormati semua yang hadir.",
  ui_story_5070_50700301_4_dialog_content = "Keluarga Lin selalu menghargai kerja keras dan jujur, dan sangat senang untuk memberi penghargaan atas usaha yang baik seperti itu.",
  ui_story_5070_50700301_5_dialog_content = "Jadi, silakan makan, minum, dan nikmati diri sebanyak mungkin malam ini.",
  ui_story_5070_50700301_6_dialog_content = "Wooo!!!",
  ui_story_5070_50700301_7_dialog_content = "Tak pernah terpikir bahwa jamuan yang semeriah ini bisa diadakan di kapal.",
  ui_story_5070_50700301_8_dialog_content = "Pujian Anda sangat kami hargai, Telema dari Lumopolis.",
  ui_story_5070_50700301_9_dialog_content = "Aku penasaran, kejutan apa lagi yang akan Longzhou berikan untukku? Aku tidak sabar untuk mengetahuinya.",
  ui_story_5070_50700301_10_dialog_content = "Itu wajar saja.",
  ui_story_5070_50700301_11_dialog_content = "Longzhou sangat selektif dalam menerima tamu dari jauh. Sebagai utusan dari Lumopolis, kamu akan dianggap sebagai tamu langka dan istimewa.",
  ui_story_5070_50700301_12_dialog_content = "Hanya perawatan terbaik saja yang akan cukup.",
  ui_story_5070_50700301_13_dialog_content = "Kalau kamu bilang begitu, aku jadi semakin bersemangat untuk mengunjungi sisi lain dari laut!",
  ui_story_5070_50700301_14_dialog_content = "Namun Longzhou masih jauh, jadi bolehkah saya terlebih dahulu mempelajari lebih lanjut tentang fitur-fitur Shadowind?",
  ui_story_5070_50700301_15_dialog_content = "Sejak saya tiba di Twin Pavilions Bay, saya mendengar begitu banyak rumor menarik tentang teknologi kapal ini.",
  ui_story_5070_50700301_16_dialog_content = "Dengan komponen yang dirancang dengan teliti dan berbagai fungsi, Shadowind seharusnya tidak kurang dari sebuah karya seni.",
  ui_story_5070_50700301_17_dialog_content = "Dalam hal apapun, ini terlihat jauh lebih menyenangkan daripada teknologi yang besar dan sulit digunakan di Illumina atau di gurun.",
  ui_story_5070_50700301_18_dialog_content = "Setiap tempat memiliki teknologi uniknya masing-masing. Tentu saja, kelebihan dan kekurangan mereka juga sama beragamnya.",
  ui_story_5070_50700301_19_dialog_content = "Izinkan saya menemukan panduan yang cocok untuk memperkenalkan fitur-fiturnya.",
  ui_story_5070_50700301_20_dialog_content = "(Xuan Ji... Kemana kamu pergi?)",
  ui_story_5070_50700301_21_dialog_content = "Ah, Matahari! Waktumu tidak bisa lebih sempurna!",
  ui_story_5070_50700301_22_dialog_content = "Y-Yang Mulia?! B-Bagaimana saya bisa membantu?",
  ui_story_5070_50700301_23_dialog_content = "Maukah Anda berbaik hati untuk menunjukkan beberapa fitur Shadowind kepada teman kita di sini? Utusan Lumopolis sangat penasaran tentang berbagai fungsi kapal ini.",
  ui_story_5070_50700301_24_dialog_content = "Tentu saja!",
  ui_story_5070_50700301_25_dialog_content = "Aku sudah mengutak-atik alat-alat ini selama beberapa dekade terakhir. Kamu tidak akan menemukan pemandu yang lebih baik daripada aku!",
  ui_story_5070_50700301_26_dialog_content = "Kalau begitu, sisanya akan kuserahkan di tanganmu yang cakap.",
  ui_story_5070_50700301_27_dialog_content = "Sampai bertemu lagi, Nona.",
  ui_story_5070_50700301_28_dialog_content = "Fiuh.",
  ui_story_5070_50700301_29_dialog_content = "Apa itu, Yang Mulia? Apakah Anda memerlukan istirahat?",
  ui_story_5070_50700301_30_dialog_content = "Sama sekali tidak. Masih terlalu dini untuk aku mulai merasa lelah.",
  ui_story_5070_50700301_31_dialog_content = "Tapi... Aku ingin tahu di mana PlayerName mungkin berada?",
  ui_story_5070_50700301_32_dialog_content = "Bisakah pekerjaannya membuat kedatangannya tertunda?",
  ui_story_5070_50700301_33_dialog_content = "Aku selalu bisa mencari dia—",
  ui_story_5070_50700301_34_dialog_content = "Tunggu!",
  ui_story_5070_50700301_35_dialog_content = "Apa itu, Jiu?",
  ui_story_5070_50700301_36_dialog_content = "Waspada terhadap sekitar Anda, Yang Mulia.",
  ui_story_5070_50700301_37_dialog_content = "...",
  ui_story_5070_50700301_38_dialog_content = "Sepertinya nanti aku harus mengucapkan kode etik Shadowind untuk penumpang kita di waktu yang lain.",
  ui_story_5070_50700301_39_dialog_content = "Apa ini? Apa yang terjadi?!",
  ui_story_5070_50700301_40_dialog_content = "Oh tidak, apa lagi ini? Sudah cukup sulit untuk mendapatkan tempat duduk di perjamuan malam ini...",
  ui_story_5070_50700301_41_dialog_content = "Awal malam yang kurang baik, harus saya katakan.",
  ui_story_5070_50700301_42_dialog_content = "Tetap waspada, semuanya!",
  ui_story_5070_50700301_43_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5070_50700301_44_dialog_content = "Ah! Kapal ini bergoyang maju mundur!",
  ui_story_5070_50700301_45_dialog_content = "Kapten! Beberapa Clockwork Beast mulai menyerang struktur pendukung Shadowind!",
  ui_story_5070_50700301_46_dialog_content = "Kita sedang ada di tengah pesta, bukan? Demi White Night. Apa yang sebenarnya terjadi di sini?!",
  ui_story_5070_50700301_47_dialog_content = "Saya menuntut untuk tahu apa yang sedang terjadi pada kapal ini sekarang!",
  ui_story_5070_50700301_48_dialog_content = "...",
  ui_story_5070_50700301_49_dialog_content = "Tetaplah di sini, Yang Mulia. Aku akan pergi mengurus segalanya.",
  ui_story_5070_50700301_50_dialog_content = "Sangat baik, tapi hati-hati.",
  ui_story_5070_50700302_1_dialog_content = "Masalah telah terselesaikan, Yang Mulia.",
  ui_story_5070_50700302_2_dialog_content = "Saya senang mendengarnya.",
  ui_story_5070_50700302_3_dialog_content = "Tapi kenapa kau terlihat begitu bingung? Jangan bilang kau terluka saat kekacauan itu—",
  ui_story_5070_50700302_4_dialog_content = "Aku baik-baik saja, Jiu.",
  ui_story_5070_50700302_5_dialog_content = "Karena Binatang Jam tangan kehilangan kendali, Lin Guild kini sedang membahas apakah akan menunda keberangkatan Shadowind atau tidak.",
  ui_story_5070_50700302_6_dialog_content = "Keputusan ini tidak diambil karena ketakutan.",
  ui_story_5070_50700302_7_dialog_content = "Namun, laut penuh dengan bahaya, seperti badai dan Eclipsites...",
  ui_story_5070_50700302_8_dialog_content = "Untuk menambah semua itu, Clockwork Beasts kami telah mulai menyerang kami tanpa alasan yang jelas.",
  ui_story_5070_50700302_9_dialog_content = "Terlalu berbahaya untuk meninggalkan pelabuhan. Kita harus bersabar dan terus mengawasi setiap perubahan.",
  ui_story_5070_50700302_10_dialog_content = "Tapi kita tidak punya waktu untuk hanya menunggu dan melihat saja.",
  ui_story_5070_50700302_11_dialog_content = "Seperti yang banyak dari kalian ketahui, saya telah melakukan perjalanan ke Astra untuk mencapai dua tujuan.",
  ui_story_5070_50700302_12_dialog_content = "Pertama adalah meningkatkan hubungan dengan faksi penguasa di benua ini dan secara resmi mengadakan perjanjian perdagangan.",
  ui_story_5070_50700302_13_dialog_content = "Kedua adalah bertukar pengetahuan teknis dan taktis untuk menghadapi ancaman Eclipsite.",
  ui_story_5070_50700302_14_dialog_content = "Apakah semua orang tahu mengapa kedua tujuan ini diberikan prioritas tinggi?",
  ui_story_5070_50700302_15_dialog_content = "Ini karena pantai Longzhou sering mengalami serangan Eclipsite dalam beberapa tahun terakhir. Akibatnya, kapal-kapal dagang kami dan pelayaran mereka sangat terpengaruh.",
  ui_story_5070_50700302_16_dialog_content = "Ji, salah satu dari delapan kerajaan bawahan yang saya ikuti, didirikan berdasarkan perdagangan. Oleh karena itu, kemakmurannya hampir sepenuhnya bergantung pada jalur air yang aman dan transportasi yang kuat.",
  ui_story_5070_50700302_17_dialog_content = "Banyak guild di Ji telah lama meminta kami untuk memperbaiki masalah ini.",
  ui_story_5070_50700302_18_dialog_content = "Namun istana kerajaan belum menemukan solusi yang langgeng. Tidak peduli berapa kali kita mengusir mereka, gelombang Eclipsites yang lebih banyak menggantikan tempat mereka. Hal ini telah mengusir banyak penduduk kita dari pesisir, membuat daerah-daerah ini rentan terhadap okupasi bajak laut.",
  ui_story_5070_50700302_19_dialog_content = "Pedagang dan pekerja industri pelayaran kita terus-menerus terancam serangan, dan masyarakat kita tidak dapat menjalani kehidupan yang damai.",
  ui_story_5070_50700302_20_dialog_content = "Untuk alasan ini, raja kami memutuskan untuk menunjuk dan mengirim utusan bangsawan ke Astra. Dengan demikian, ia berharap menemukan terobosan dalam perjuangan kita melawan para Eclipsite.",
  ui_story_5070_50700302_21_dialog_content = "Meyakinkan Lumopolis untuk mengizinkan seorang utusan menemani saya kembali ke Longzhou untuk pembicaraan lebih lanjut bukanlah hal yang mudah...",
  ui_story_5070_50700302_22_dialog_content = "Tapi, sekarang...",
  ui_story_5070_50700302_23_dialog_content = "Aku ingin turun dari kapal ini sekarang juga.",
  ui_story_5070_50700302_24_dialog_content = "Kamu berjanji bahwa ini benar-benar aman, bukan? Kita bahkan belum meninggalkan pelabuhan, dan kita sudah diserang!",
  ui_story_5070_50700302_25_dialog_content = "Ini yang kalian sebut aman?!",
  ui_story_5070_50700302_26_dialog_content = "Tak ada yang memberitahuku bahwa monster mekanis itu mampu menyerang kita!",
  ui_story_5070_50700302_27_dialog_content = "Tidak ada siapa-siapa sama sekali!",
  ui_story_5070_50700302_28_dialog_content = "Aku… aku…",
  ui_story_5070_50700302_29_dialog_content = "... Saya hanya bisa membujuk utusan itu untuk sementara.",
  ui_story_5070_50700302_30_dialog_content = "Jika kita tidak bisa memperbaiki kapal dan mengirimkannya dengan cepat, saya khawatir situasi akan berubah menjadi lebih buruk. Jika demikian, maka misi saya...",
  ui_story_5070_50700302_31_dialog_content = "Hmm…",
  ui_story_5070_50700302_32_dialog_content = "Putri membuat poin yang bagus, tetapi kita tidak boleh gegabah terlepas dari situasinya.",
  ui_story_5070_50700302_33_dialog_content = "Kamu juga akan mempertaruhkan hidupmu sendiri.",
  ui_story_5070_50700302_34_dialog_content = "Saya percaya kita harus menunggu, Yang Mulia.",
  ui_story_5070_50700302_35_dialog_content = "Jika utusan tidak mau melakukan perjalanan, saya selalu bisa membujuknya dengan cara lain.",
  ui_story_5070_50700302_36_dialog_content = "Kamu telah berkorban banyak untuk sampai di titik ini. Aku menolak untuk membiarkan semuanya sia-sia.",
  ui_story_5070_50700302_37_dialog_content = "Ahem, maukah berbagi pendapat Anda, Kapten?",
  ui_story_5070_50700302_38_dialog_content = "...",
  ui_story_5070_50700302_39_dialog_content = "Perjalanan ini tidak diragukan lagi sangat penting. Kapal ini membawa lebih dari sekadar putri dan barang dagangan kita.",
  ui_story_5070_50700302_40_dialog_content = "Ini juga membawa masa depan Keluarga Lin.",
  ui_story_5070_50700302_41_dialog_content = "Kami sudah mengalami terlalu banyak kerugian di laut... Saya khawatir kami tidak akan mampu menahan pukulan berat lainnya.",
  ui_story_5070_50700302_42_dialog_content = "Itulah alasan yang lebih membuat kita harus berhati-hati—",
  ui_story_5070_50700302_43_dialog_content = "Jadi, segera mulai perbaikan pada rangka kapal.",
  ui_story_5070_50700302_44_dialog_content = "Kami akan berlayar segera setelah Shadowind dalam kondisi yang baik.",
  ui_story_5070_50700302_45_dialog_content = "E-Ehem!",
  ui_story_5070_50700302_46_dialog_content = "Kapten! B-Bagaimana kamu juga bisa...",
  ui_story_5070_50700302_47_dialog_content = "Hah? Tunggu... Kapten Yuebai!",
  ui_story_5070_50700302_48_dialog_content = "Jujur, kenapa semua anak muda zaman sekarang seperti ini?!",
  ui_story_5070_50700302_49_dialog_content = "Tepat sekali! Anda tahu pepatahnya. \"Tergesa-gesa bisa menimbulkan petaka; perlahan tapi pasti akan memenangkan perlombaan.\"",
  ui_story_5070_50700302_50_dialog_content = "Sayangnya, situasi saat ini sepertinya tidak memberi kita kemewahan waktu. Sungguh situasi yang sulit!",
  ui_story_5070_50700302_51_dialog_content = "Hah? Kamu siapa...?",
  ui_story_5070_50700302_52_dialog_content = "Menarik, sepertinya saya tidak ingat ada penipu yang diundang ke perjamuan ini?",
  ui_story_5070_50700302_53_dialog_content = "Oh, Yang Mulia.",
  ui_story_5070_50700302_54_dialog_content = "Mengingat semua yang terjadi di sini hari ini, saya khawatir sangat sedikit orang yang masih memiliki nafsu makan.",
  ui_story_5070_50700302_55_dialog_content = "Sayang sekali jika makanan lezat ini terbuang sia-sia, bukan? Untungnya, kebetulan malam ini nafsu makan saya sangat baik!",
  ui_story_5070_50700302_56_dialog_content = "Semuanya rasanya luar biasa, meskipun saya merasa melonnya sedikit kurang memuaskan.",
  ui_story_5070_50700302_57_dialog_content = "Dalam kesibukan mereka mempersiapkan pesta, tampaknya para petani memanen semangka ini sebelum benar-benar matang dan manis.",
  ui_story_5070_50700302_58_dialog_content = "A-Aku sudah cukup mendengar ocehanmu...",
  ui_story_5070_50700302_59_dialog_content = "Saya hanya membuat pengamatan, tidak lebih. Pada akhirnya, terserah Anda untuk memutuskan apakah akan menunggu waktu yang tepat atau tidak.",
  ui_story_5070_50700302_60_dialog_content = "Tapi terkadang, lebih baik membiarkan alam mengambil jalannya. Membiarkan semangka matang dan jatuh dari pohon jauh lebih menyenangkan daripada memaksa semua orang untuk mencicipi buah yang pahit dan tidak enak.",
  ui_story_5070_50700302_61_dialog_content = "Setuju, bukan?",
  ui_story_5070_50700401_1_dialog_content = "Hmm, beri aku waktu sebentar untuk memikirkan cara menjelaskan teknologi ini agar kamu bisa mengerti.",
  ui_story_5070_50700401_2_dialog_content = "... Aku mengerti! Saya paham bahwa Astra telah melakukan penelitian ekstensif tentang Keempat Kekuatan...",
  ui_story_5070_50700401_3_dialog_content = "Empat Kekuatan?",
  ui_story_5070_50700401_4_dialog_content = "Empat elemen berbeda dari Lumina.",
  ui_story_5070_50700401_5_dialog_content = "Bidang keahlian teknologi saya berkaitan dengan menggabungkan berbagai material...",
  ui_story_5070_50700401_6_dialog_content = "Dan menciptakan mesin yang mampu memanfaatkan Lumina, sama seperti Aurorian dan binatang roh.",
  ui_story_5070_50700401_7_dialog_content = "Apakah itu menjadi lebih masuk akal untuk kamu?",
  ui_story_5070_50700401_8_dialog_content = "Terkesan mirip dengan teknologi Lumina yang kita miliki di sini, tetapi gayanya benar-benar berbeda.",
  ui_story_5070_50700401_9_dialog_content = "Tentu saja. Tujuan kita adalah satu dan sama; perbedaannya hanya terletak pada pandangan dunia kita.",
  ui_story_5070_50700401_10_dialog_content = "Orang-orang di Longzhou percaya bahwa semua hal di dunia ini mengandung Lumina.",
  ui_story_5070_50700401_11_dialog_content = "Jaringan sirkulasi Lumina yang luas dapat diamati mulai dari rumput terkecil hingga pohon tertinggi, dan dari serangga terkecil hingga binatang paling buas.",
  ui_story_5070_50700401_12_dialog_content = "Teknik kami memungkinkan kami untuk menginfuskan Lumina ke dalam material yang digunakan untuk membuat komponen. Kami kemudian dapat menghasilkan berbagai efek dengan mengatur aliran Lumina tersebut.",
  ui_story_5070_50700401_13_dialog_content = "Dengan bahan yang tepat dan struktur yang presisi, teknologi kita bahkan dapat menciptakan dunia yang sepenuhnya baru!",
  ui_story_5070_50700401_14_dialog_content = "Wow, membahas teknologi kamu itu seperti membahas filosofi penciptaan!",
  ui_story_5070_50700401_15_dialog_content = "Hahaha, yah kamu tidak salah!",
  ui_story_5070_50700401_16_dialog_content = "Kepiting api dari sebelumnya, serta capung tembaga milikku, semuanya merupakan manifestasi dari filosofi yang sama.",
  ui_story_5070_50700401_17_dialog_content = "Parasol Anehku juga tidak terkecuali.",
  ui_story_5070_50700401_18_dialog_content = "Ia memiliki banyak mekanisme, itulah sebabnya ia mampu menyerang dan bertahan.",
  ui_story_5070_50700401_19_dialog_content = "Ketika dipahami dengan benar, prinsip-prinsip teknologi kita dapat diterapkan tidak hanya pada mesin jam mekanik, tetapi juga pada banyak hal lainnya.",
  ui_story_5070_50700401_20_dialog_content = "Saya tidak tahu kalau ini begitu mengesankan... Sepertinya mempelajari mesin tidak semudah yang saya kira.",
  ui_story_5070_50700401_21_dialog_content = "Tentu saja bukan. Lagi pula, teknologi ini adalah dasar dari sebuah kerajaan vasal, serta alasan Keluarga Lin mampu mendirikan kembali rute perdagangan mereka.",
  ui_story_5070_50700401_22_dialog_content = "Di Kerajaan Ye, langit dipenuhi burung mekanik yang membawa pesan sementara lembu kayu mengangkut barang-barang kita di darat.",
  ui_story_5070_50700401_23_dialog_content = "Jika Anda terlalu malas untuk mengenakan pakaian, mencuci muka, atau menyiapkan makanan, ada makhluk mekanik yang siap membantu Anda menyelesaikan tugas apa pun.",
  ui_story_5070_50700401_24_dialog_content = "Jika Anda menemukan waktu untuk berkunjung, saya dengan senang hati akan menunjukkan sejauh mana teknologi kami.",
  ui_story_5070_50700401_25_dialog_content = "Terdengar bagus untukku!",
  ui_story_5070_50700401_26_dialog_content = "Namun…",
  ui_story_5070_50700401_27_dialog_content = "Sebenarnya... kita sedang apa sekarang?",
  ui_story_5070_50700401_28_dialog_content = "Bukankah sudah jelas? Kita mencari gudang yang baru saja digunakan.",
  ui_story_5070_50700401_29_dialog_content = "Saya sangat menyadari hal itu, mengingat kita sudah memeriksa beberapa gudang.",
  ui_story_5070_50700401_30_dialog_content = "(Beberapa di antaranya juga terkunci, tetapi saya tidak cukup cepat untuk menghentikan Xuan Ji dari membuka kuncinya...)",
  ui_story_5070_50700401_31_dialog_content = "Tapi seharusnya kita mengejar musuh sekarang, bukan?",
  ui_story_5070_50700401_32_dialog_content = "Aku seorang pengrajin, ingat? Berurusan dengan mesin adalah keahlianku, jadi serahkan pencarian ini pada informan kecil yang telah kusebar di seluruh kota.",
  ui_story_5070_50700401_33_dialog_content = "Sebuah kelompok preman yang bersembunyi di bayangan berhasil mendapatkan cetak biru saya dari sumber yang tidak diketahui...",
  ui_story_5070_50700401_34_dialog_content = "Mereka mengubah kepiting api saya menjadi alat untuk menyakiti orang, dan menyimpan sejumlah di gudang Shadowind.",
  ui_story_5070_50700401_35_dialog_content = "Penyergapan yang gagal tadi jelas bukan tujuan sebenarnya mereka.",
  ui_story_5070_50700401_36_dialog_content = "Saya yakin mereka memiliki lebih banyak jebakan tersembunyi di sekitar Twin Pavilions Bay.",
  ui_story_5070_50700401_37_dialog_content = "... Aku benar-benar khawatir untuk keselamatan Shadowind.",
  ui_story_5070_50700401_38_dialog_content = "Orang biasa tidak memiliki kesempatan untuk melawan kepiting api itu.",
  ui_story_5070_50700401_39_dialog_content = "Orang kuat jangan menindas yang lemah, orang banyak jangan menindas segelintir orang, dan orang kaya jangan menindas yang miskin...",
  ui_story_5070_50700401_40_dialog_content = "Dengan mesin datang kekuatan besar, dan mereka yang menggunakannya harus tidak pernah menggunakannya untuk menyakiti orang lain.",
  ui_story_5070_50700401_41_dialog_content = "Para pengrajin di negeri saya berkumpul untuk menciptakan kode etik ini, dan kami semua bersumpah untuk menjunjungnya.",
  ui_story_5070_50700401_42_dialog_content = "Untuk alasan itu, jika suatu saat nanti saya berhasil menemukan pencuri yang mencuri cetak biru saya...",
  ui_story_5070_50700401_43_dialog_content = "(Suaranya tiba-tiba berubah dingin seperti es...)",
  ui_story_5070_50700401_44_dialog_content = "Benar sekali!",
  ui_story_5070_50700401_45_dialog_content = "Dari cara kamu mengatakannya, makhluk mekanik ini bisa mensimulasikan aliran Lumina dalam organisme hidup...",
  ui_story_5070_50700401_46_dialog_content = "Ini berarti aku mungkin bisa menggunakan kekuatanku untuk merasakan lokasi kepiting api yang lebih banyak!",
  ui_story_5070_50700401_47_dialog_content = "Apa kesimpulan yang menarik.",
  ui_story_5070_50700401_48_dialog_content = "Ini dia—",
  ui_story_5070_50700401_49_dialog_content = "(Aku hanya perlu membayangkan kepiting api dari sebelumnya, dan jenis Lumina yang sama yang mereka keluarkan... Di sana!)",
  ui_story_5070_50700401_50_dialog_content = "Meskipun samar, setidaknya aku bisa merasakan arah mereka! Di sebelah sini!",
  ui_story_5070_50700401_51_dialog_content = "Tak pernah menyangka akan menemukan gudang kecil ini di lokasi yang tersembunyi seperti ini.",
  ui_story_5070_50700401_52_dialog_content = "Itu adalah prestasi yang sangat mengesankan! Terima kasih atas bantuanmu, PlayerName.",
  ui_story_5070_50700401_53_dialog_content = "<color=#e8d9bb>Di dalam gudang yang sudah lapuk terdapat berbagai macam peti aneh, masing-masing berisi—</color>",
  ui_story_5070_50700401_54_dialog_content = "Kepiting api, elang terapung, bahkan kalajengking panjang... Semuanya terbuat dari bahan berkualitas tinggi.",
  ui_story_5070_50700401_55_dialog_content = "Pemilik gudang-gudang ini pasti memiliki banyak uang untuk dibelanjakan.",
  ui_story_5070_50700401_56_dialog_content = "Apa yang mereka rencanakan untuk dilakukan dengan begitu banyak binatang mekanik?",
  ui_story_5070_50700401_57_dialog_content = "Pikir kamu bisa bantu aku lagi, PlayerName?",
  ui_story_5070_50700401_58_dialog_content = "Kita perlu membuka semua peti ini dan memeriksa binatang mekanik untuk melihat adanya tanda atau simbol.",
  ui_story_5070_50700401_59_dialog_content = "Sekarang setelah kamu menyebutkannya, kamu memang melakukan hal yang sama dengan kepiting api tadi.",
  ui_story_5070_50700401_60_dialog_content = "Tapi aku tidak melihat tanda apapun pada binatang mekanik di kedua gudang ini.",
  ui_story_5070_50700401_61_dialog_content = "Seperti yang saya katakan sebelumnya, Kerajaan Ye sangat mengatur penggunaan penemuan jam mekanik, serta cetak biru dan saluran pengiriman mereka.",
  ui_story_5070_50700401_62_dialog_content = "Apakah mereka diproduksi massal di sebuah bengkel atau dibuat khusus oleh seorang pengrajin tunggal...",
  ui_story_5070_50700401_63_dialog_content = "Setiap mesin jam mekanis harus diukir dengan tanda unik setelah selesai.",
  ui_story_5070_50700401_64_dialog_content = "Dengan cara itu, seseorang selalu bisa bertanggung jawab jika ada masalah yang muncul dengan mesin.",
  ui_story_5070_50700401_65_dialog_content = "Jadi jika kita tidak dapat menemukan tanda apa pun, apakah itu berarti penyelidikan kita mencapai jalan buntu?",
  ui_story_5070_50700401_66_dialog_content = "Tidak.",
  ui_story_5070_50700401_67_dialog_content = "Setidaknya, ini membuktikan bahwa mesin-mesin ini tidak dibuat di bengkel Kerajaan Ye.",
  ui_story_5070_50700401_68_dialog_content = "Komponen mereka telah diselundupkan keluar negeri dan dirakit di sini.",
  ui_story_5070_50700401_69_dialog_content = "Ada juga barang-barang lain yang disimpan di gudang-gudang ini.",
  ui_story_5070_50700401_70_dialog_content = "Ada banyak barang dagangan lain yang bercampur dengan binatang mekanik ini.",
  ui_story_5070_50700401_71_dialog_content = "Tunggu sebentar, tanda-tanda ini... Lin Guild?",
  ui_story_5070_50700401_72_dialog_content = "Tepat sekali.",
  ui_story_5070_50700401_73_dialog_content = "Beberapa hari yang lalu, ketika Shadowind pertama kali tiba di pelabuhan, saya sempat mendengar beberapa penumpang membicarakan hal yang sama.",
  ui_story_5070_50700401_74_dialog_content = "Ada sesuatu tentang Keluarga Lin yang terlibat dalam operasi penyelundupan di Longzhou, dan kepala keluarga ditangkap oleh Kantor Perdagangan Maritim...",
  ui_story_5070_50700401_75_dialog_content = "PlayerName, bisakah saya meminta bantuan lagi?",
  ui_story_5070_50700401_76_dialog_content = "Saya perlu kamu untuk bertanya pada Kapten Yuebai...",
  ui_story_5070_50700401_77_dialog_content = "Jika memang Keluarga Lin terlibat dalam penyelundupan.",
  ui_story_5070_50700401_78_dialog_content = "Sejak diserang kepiting api tadi, aku terus mencari gudang.",
  ui_story_5070_50700401_79_dialog_content = "Saya ingin tahu apakah pesta Shadowind sudah selesai?",
  ui_story_5070_50700401_80_dialog_content = "Hah? Apakah ada sesuatu yang terjadi di atas kapal?",
  ui_story_5070_50700401_81_dialog_content = "Tentu saja Anda sadar akan manfaat bersama yang akan dihasilkan dari kerja sama kita, Telema.",
  ui_story_5070_50700401_82_dialog_content = "Tentu saja aku tahu tentang mereka. Jangan menghina kecerdasanku.",
  ui_story_5070_50700401_83_dialog_content = "Tapi tidak peduli seberapa hebat Longzhou atau seberapa penting misi kita, apa gunanya jika kita tidak bisa mencapai tanah airmu dengan selamat?",
  ui_story_5070_50700401_84_dialog_content = "Aku telah mengambil berbagai langkah pencegahan untuk memastikan keselamatanmu di setiap langkah.",
  ui_story_5070_50700401_85_dialog_content = "Sebagai warga terhormat Lumopolis, aku sungguh ingin percaya padamu.",
  ui_story_5070_50700401_86_dialog_content = "Tapi... dengan segala yang telah terjadi, aku takut aku harus mempertimbangkan kembali.",
  ui_story_5070_50700401_87_dialog_content = "Telema...",
  ui_story_5070_50700401_88_dialog_content = "(Bukankah itu utusan Lumopolis yang Dantang bicarakan? Kenapa tiba-tiba berubah pikiran?)",
  ui_story_5070_50700401_89_dialog_content = "Lokasi mencurigakan terakhir yang tersisa untuk dicari adalah apotek ini.",
  ui_story_5070_50700401_90_dialog_content = "Perasaan ini... Sepertinya ada pengguna kuat Flame Force Arts di dalam.",
  ui_story_5070_50700401_91_dialog_content = "Nah, mari kita lihat siapa yang bersembunyi di balik pintu ini.",
  ui_story_5070_50700401_92_dialog_content = "<size=45>Tok, tok, tok!</color>",
  ui_story_5070_50700401_93_dialog_content = "Ada apa?",
  ui_story_5070_50700401_94_dialog_content = "Maaf mengganggu, tapi ada beberapa pertanyaan yang ingin aku ajukan.",
  ui_story_5070_50700401_95_dialog_content = "Apakah kamu kenal dengan pemilik gudang di seberang sana?",
  ui_story_5070_50700401_96_dialog_content = "Jika tidak, apakah Anda akrab dengan Keluarga Lin?",
  ui_story_5070_50700401_97_dialog_content = "...",
  ui_story_5070_50700401_98_dialog_content = "(Pintunya terbuka? Lebih baik bersiap untuk bertarung! Penuh—)",
  ui_story_5070_50700401_99_dialog_content = "...",
  ui_story_5070_50700401_100_dialog_content = "?",
  ui_story_5070_50700401_101_dialog_content = "Kenapa ada anak kecil yang menjawab pintu? Maaf, tapi bisakah saya berbicara dengan orang dewasa?",
  ui_story_5070_50700401_102_dialog_content = "Siapa bilang aku anak kecil?!",
  ui_story_5070_50700401_103_dialog_content = "Nah, kau jelas-jelas seorang...",
  ui_story_5070_50700401_104_dialog_content = "<color=#e8d9bb>Ding—!</color>",
  ui_story_5070_50700401_105_dialog_content = "Kamu cepat dalam bertindak.",
  ui_story_5070_50700401_106_dialog_content = "Aku tahu seharusnya aku memeriksa almanak sebelum keluar hari ini. Aku yakin itu akan memperingatkan aku tentang datang ke tempat di mana mereka menyambut pengunjung dengan menghunus pedang mereka.",
  ui_story_5070_50700401_107_dialog_content = "<size=45>Graaah—</size>",
  ui_story_5070_50700401_108_dialog_content = "Oh? Wah, ini benar-benar penyambutan yang tak terduga.",
  ui_story_5070_50700402_1_dialog_content = "Orang-orang ini memang tidak tahu kapan harus menyerah, ya?",
  ui_story_5070_50700402_2_dialog_content = "Kita terus membunuh mereka, tapi mereka terus muncul entah dari mana...",
  ui_story_5070_50700402_3_dialog_content = "Hah? Hei! Apakah kamu tidak akan melawannya, Zhong Xu?",
  ui_story_5070_50700402_4_dialog_content = "Payung logam, capung tembaga, dan kreasi jam mekanik yang begitu indah.",
  ui_story_5070_50700402_5_dialog_content = "Apakah mungkin Anda... Menteri Armilla?",
  ui_story_5070_50700402_6_dialog_content = "Tunggu, kamu kenal dia?",
  ui_story_5070_50700402_7_dialog_content = "Kita belum pernah bertemu, tapi aku sudah banyak mendengar tentangnya.",
  ui_story_5070_50700402_8_dialog_content = "Seorang pengrajin jenius dari Kerajaan Ye yang berasal dari sekte Qianyun.",
  ui_story_5070_50700402_9_dialog_content = "Pada usia lima belas tahun, dia mengejutkan seluruh bangsa dengan boneka mekanik yang bisa memainkan musik secara realistis.",
  ui_story_5070_50700402_10_dialog_content = "Tak lama kemudian, dia menjadi penasihat strategis bagi raja Ye.",
  ui_story_5070_50700402_11_dialog_content = "Pemahamanku adalah bahwa gelar yang diberikan oleh Kerajaan Ye didasarkan pada penemuan terkenal. Bagi kamu yang diberi gelar \"Armilla\" berarti kerajaanmu benar-benar mengakui kecerdasanmu.",
  ui_story_5070_50700402_12_dialog_content = "Oh, saya tidak akan sampai sejauh itu. Lagipula, saya sudah pensiun dari dunia politik sejak lama; sekarang saya hanya seorang pengrajin biasa.",
  ui_story_5070_50700402_13_dialog_content = "Tapi kamu? Seorang ahli pedang berambut merah dengan pengetahuan tentang politik Longzhou...",
  ui_story_5070_50700402_14_dialog_content = "Anda pasti Tuan Zhong Xu, rekan terhormat dari Keluarga Lin yang dikenal dan dihormati oleh setiap guild di Kerajaan Ji.",
  ui_story_5070_50700402_15_dialog_content = "Kata-kata Anda lebih baik daripada yang saya layak, Nyonya.",
  ui_story_5070_50700402_16_dialog_content = "Liqing.",
  ui_story_5070_50700402_17_dialog_content = "Wanita muda ini bukan musuh kita.",
  ui_story_5070_50700402_18_dialog_content = "Belum tentu.",
  ui_story_5070_50700402_19_dialog_content = "Hei! Maksudmu apa? Kurang ajar, ya?!",
  ui_story_5070_50700402_20_dialog_content = "Diam, si kecil. Orang dewasa sedang berbicara sekarang.",
  ui_story_5070_50700402_21_dialog_content = "Aku sudah bilang, aku bukan anak kecil!",
  ui_story_5070_50700402_22_dialog_content = "Setengah tahun lalu, Kerajaan Ji sedang melacak pengiriman barang-barang selundupan.",
  ui_story_5070_50700402_23_dialog_content = "Setelah penyelidikan menyeluruh, mereka menemukan bahwa kapal dagang Keluarga Lin adalah satu-satunya yang memiliki akses ke catatan keberangkatan mereka.",
  ui_story_5070_50700402_24_dialog_content = "Lin Guild juga tidak dapat memberikan penjelasan yang valid mengenai masalah tersebut.",
  ui_story_5070_50700402_25_dialog_content = "Jadi apa? Menurutmu kamu bisa menyalahkan mereka hanya berdasarkan kebetulan?",
  ui_story_5070_50700402_26_dialog_content = "Kau benar.",
  ui_story_5070_50700402_27_dialog_content = "Meskipun tersangka utama dalam kasus ini adalah keluarga Lin, banyak orang masih merasa bahwa masalah ini sangat dipertanyakan.",
  ui_story_5070_50700402_28_dialog_content = "Tapi setelah mencari di gudang-gudang sekitar tadi...",
  ui_story_5070_50700402_29_dialog_content = "Aku menemukan sejumlah besar binatang mekanik Kerajaan Ye yang bagian-bagiannya kemungkinan besar diselundupkan keluar negeri juga.",
  ui_story_5070_50700402_30_dialog_content = "Saya juga menemukan cukup banyak kargo dengan tanda Lin Guild bercampur dengan binatang mekanik.",
  ui_story_5070_50700402_31_dialog_content = "Sebagai rekan terhormat dari Keluarga Lin, tentunya Anda pasti tahu sesuatu tentang ini, bukan?",
  ui_story_5070_50700402_32_dialog_content = "Bisakah Anda berbaik hati untuk menjelaskan?",
  ui_story_5070_50700402_33_dialog_content = "...",
  ui_story_5070_50700402_34_dialog_content = "Memang benar. Sebuah kapal dagang Keluarga Lin memang mengangkut barang-barang selundupan.",
  ui_story_5070_50700402_35_dialog_content = "(Bagaimana bisa orang Telema ini begitu keras kepala? Tidak peduli seberapa keras Dantang mencoba, sepertinya dia tidak mencapai kemajuan apa pun.)",
  ui_story_5070_50700402_36_dialog_content = "(Apa yang akan terjadi pada misinya jika ini terus berlanjut?)",
  ui_story_5070_50700402_37_dialog_content = "... Aku mengerti.",
  ui_story_5070_50700402_38_dialog_content = "Aku akan menghormati dan patuh pada keputusanmu, Telema dari Lumopolis.",
  ui_story_5070_50700402_39_dialog_content = "Aku senang akhirnya kau juga sependapat denganku.",
  ui_story_5070_50700402_40_dialog_content = "Aku selalu tahu bahwa seorang wanita cantik dan bangsawan seperti dirimu bisa bersimpati dengan penderitaan orang lain.",
  ui_story_5070_50700402_41_dialog_content = "Demikian juga, saya harus meminta agar kamu juga memahami situasi saya sendiri, Telema.",
  ui_story_5070_50700402_42_dialog_content = "Hah?",
  ui_story_5070_50700402_43_dialog_content = "PlayerName.",
  ui_story_5070_50700402_44_dialog_content = "Maukah kamu menggantikan Telema sebagai utusan Astra dan kembali ke Longzhou bersamaku?",
  ui_story_5070_50700402_45_dialog_content = "... Aku?!?",
  ui_story_5070_50700501_1_dialog_content = "T-Tidak mungkin! Bagaimana saya bisa mungkin menjadi utusan?!",
  ui_story_5070_50700501_2_dialog_content = "Dan kenapa tidak?",
  ui_story_5070_50700501_3_dialog_content = "Nah, untuk permulaan, saya tidak mewakili kekuatan besar seperti Lumopolis atau Federasi Illumina.",
  ui_story_5070_50700501_4_dialog_content = "Ya, tetapi sebagai pihak yang netral, bukankah Anda berada dalam posisi terbaik untuk mewakili kepentingan Astra?",
  ui_story_5070_50700501_5_dialog_content = "Tidak hanya itu, pengalaman Anda di negeri ini sebesar jaringan sekutu yang telah Anda bangun seiring waktu.",
  ui_story_5070_50700501_6_dialog_content = "Kamu lebih dari cukup mengetahui urusan Astra, serta strateginya dalam menghadapi Eclipsites.",
  ui_story_5070_50700501_7_dialog_content = "Bukankah itu sejalan dengan tujuan kita untuk membentuk jembatan komunikasi antara kedua benua kita?",
  ui_story_5070_50700501_8_dialog_content = "Tapi ini...",
  ui_story_5070_50700501_9_dialog_content = "Aku setuju!!",
  ui_story_5070_50700501_10_dialog_content = "PlayerName terkenal di Astra! Saya hanya mendengar pujian tertinggi untuknya, bahkan sebelum kita berkesempatan bertemu!",
  ui_story_5070_50700501_11_dialog_content = "Sebagai perwakilan resmi dari Lumopolis, saya bersedia menempatkan tanggung jawab misi diplomatik ke Longzhou di tangan Anda!",
  ui_story_5070_50700501_12_dialog_content = "T-Tunggu... Aku masih perlu memikirkannya!",
  ui_story_5070_50700501_13_dialog_content = "(Lumopolis, ya... Carleen memang bilang dia selalu mendukung pertukaran ini. Saya yakin dia akan kecewa jika gagal.)",
  ui_story_5070_50700501_14_dialog_content = "(Dantang dan sekutunya juga menghadapi berbagai masalah sejak mereka tiba di Astra.)",
  ui_story_5070_50700501_15_dialog_content = "(Banyak orang yang menaruh harapan pada misi ini, karena ini melibatkan masa depan dua benua. Jika saat ini aku adalah satu-satunya orang yang tepat untuk tugas ini, maka...)",
  ui_story_5070_50700501_16_dialog_content = "Akan kucoba semampuku.",
  ui_story_5070_50700501_17_dialog_content = "PlayerName... Aku sangat senang mendengar itu!!!",
  ui_story_5070_50700501_18_dialog_content = "Kamu yakin akan ini?",
  ui_story_5070_50700501_19_dialog_content = "Kapten Yuebai? Jadi Anda juga mendengar semuanya?",
  ui_story_5070_50700501_20_dialog_content = "Kamu bisa memanggilku Yuebai saja.",
  ui_story_5070_50700501_21_dialog_content = "Karena sudah diputuskan, maka sebagai kapten Shadowind...",
  ui_story_5070_50700501_22_dialog_content = "Dengan ini, aku menyambut PlayerName sebagai utusan dari seluruh Astra.",
  ui_story_5070_50700501_23_dialog_content = "Perjalanan ini akan penuh bahaya, jadi siapkan diri secara fisik dan mental untuk menghadapinya.",
  ui_story_5070_50700501_24_dialog_content = "Aku mengerti.",
  ui_story_5070_50700501_25_dialog_content = "Tunggu, Kapten Yuebai... Maksudku Yuebai. Bolehkah saya mengganggu Anda sebentar?",
  ui_story_5070_50700501_26_dialog_content = "Tahu tidak, seorang teman saya memintaku untuk menanyakan tentang Keluarga Lin kepada kamu.",
  ui_story_5070_50700501_27_dialog_content = "Memang benar. Sebuah kapal dagang Keluarga Lin memang mengangkut barang-barang selundupan.",
  ui_story_5070_50700501_28_dialog_content = "Kenapa kamu memberitahukan semua ini kepadanya, Zhong Xu?!",
  ui_story_5070_50700501_29_dialog_content = "Dia muncul di depan pintu kita dengan sejumlah tuduhan yang setengah matang! Katakan beberapa kata dan suruh dia pergi!",
  ui_story_5070_50700501_30_dialog_content = "Aku dengar itu, loh!",
  ui_story_5070_50700501_31_dialog_content = "Tapi untuk Anda berbicara tentang hal-hal ini begitu terus terang... Jangan bilang Anda berniat untuk melawan saya, Tuan Zhong Xu?",
  ui_story_5070_50700501_32_dialog_content = "Aku tidak berniat melakukan itu.",
  ui_story_5070_50700501_33_dialog_content = "Tapi jika satu kalimat saja sudah cukup membuat Anda goyah, Nyonya Menteri Armilla...",
  ui_story_5070_50700501_34_dialog_content = "Mungkin kamu tidak memiliki kesabaran untuk mendengar sisa kebenaran itu.",
  ui_story_5070_50700501_35_dialog_content = "Oh?",
  ui_story_5070_50700501_36_dialog_content = "Jadi kamu hanya mau berbagi pengetahuan dengan mereka yang mau mendengarkan? Begitu kah?",
  ui_story_5070_50700501_37_dialog_content = "Sama sekali tidak, Nona.",
  ui_story_5070_50700501_38_dialog_content = "Yang saya maksud adalah kondisi kesehatan saya kurang baik dan mudah lelah. Karena itu, saya pikir lebih baik memberi Anda jawaban singkat tadi.",
  ui_story_5070_50700501_39_dialog_content = "Mengerti. Kalau begitu, ceritakan saja versi panjang ceritanya.",
  ui_story_5070_50700501_40_dialog_content = "Lagi pula, akan sangat tidak sopan jika saya tidak mendengarkan saat Anda begitu jujur kepada saya, Tuan Zhong Xu.",
  ui_story_5070_50700501_41_dialog_content = "Heh, jadi kamu bersedia mendengarkan orang lain sesekali.",
  ui_story_5070_50700501_42_dialog_content = "Itu karena aku sudah dewasa, nak kecil.",
  ui_story_5070_50700501_43_dialog_content = "Berhenti memanggilku seperti itu! Masukkan ke dalam kepalamu!",
  ui_story_5070_50700501_44_dialog_content = "Jadi apa sebenarnya yang dihadapi kapal pedagang Keluarga Lin di laut setengah tahun yang lalu?",
  ui_story_5070_50700501_45_dialog_content = "Bajak laut.",
  ui_story_5070_50700501_46_dialog_content = "Seperti biasa, kapal-kapal Keluarga Lin berlayar dari Kerajaan Ji di awal kuartal.",
  ui_story_5070_50700501_47_dialog_content = "Namun saat mereka memasuki perairan Astra, awak kapal menemukan kiriman barang yang tidak berlabel dan tidak terdaftar tersembunyi di ruang kargo.",
  ui_story_5070_50700501_48_dialog_content = "Tak lama kemudian, sejumlah bajak laut ditemukan di antara penumpang kapal tersebut.",
  ui_story_5070_50700501_49_dialog_content = "Jadi, mereka menggunakan kapal Keluarga Lin untuk menyelundupkan barang ilegal?",
  ui_story_5070_50700501_50_dialog_content = "Tepat sekali.",
  ui_story_5070_50700501_51_dialog_content = "Namun, rencana mereka terbongkar di tengah jalan, sehingga para perompak menggunakan kekerasan untuk membajak kapal pedagang tersebut.",
  ui_story_5070_50700501_52_dialog_content = "Pada akhirnya, hanya ada dua orang yang selamat, yaitu Liqing, yang saat itu menjabat sebagai dokter kapal, dan saya sendiri.",
  ui_story_5070_50700501_53_dialog_content = "Zhong Xu juga jatuh ke laut setelah terluka parah. Dia hampir tidak selamat.",
  ui_story_5070_50700501_54_dialog_content = "Menghabiskan semua tenagaku hanya untuk membuatnya tetap hidup, jadi aku tidak bisa menyelamatkan kakinya. Inilah mengapa dia akhirnya seperti ini.",
  ui_story_5070_50700501_55_dialog_content = "Kamu tidak punya alasan untuk menyalahkan dirimu sendiri, Liqing. Aku sudah sangat berterima kasih kepadamu karena telah menyelamatkan hidupku.",
  ui_story_5070_50700501_56_dialog_content = "Jika kamu benar-benar bersyukur, maka sebaiknya kamu mendengarkan saya dan beristirahat lebih banyak.",
  ui_story_5070_50700501_57_dialog_content = "Setiap kali tamu yang tidak diinginkan muncul di depan pintu kita, kamu selalu bergegas melawan mereka tanpa mengkhawatirkan dirimu sendiri—",
  ui_story_5070_50700501_58_dialog_content = "Tamu yang tak diinginkan?",
  ui_story_5070_50700501_59_dialog_content = "Graaah—!",
  ui_story_5070_50700501_60_dialog_content = "Panjang umur, mereka ada lagi di sini!",
  ui_story_5070_50700501_61_dialog_content = "Mereka selalu muncul begitu kita berhenti memperhatikan. Hal itu membuat makan dan tidur menjadi sangat menyusahkan!",
  ui_story_5070_50700501_62_dialog_content = "Penuh—",
  ui_story_5070_50700501_63_dialog_content = "Menjadi Abu!",
  ui_story_5070_50700501_64_dialog_content = "...",
  ui_story_5070_50700501_65_dialog_content = "Apa yang baru saja saya katakan, Zhong Xu?! Inilah mengapa kamu membutuhkan waktu lama untuk pulih!",
  ui_story_5070_50700501_66_dialog_content = "Apa yang tersisa dari hidupku sudah tidak penting lagi.",
  ui_story_5070_50700501_67_dialog_content = "Tapi Lin Guildmaster...",
  ui_story_5070_50700501_68_dialog_content = "Aku pernah berjanji padanya dulu. Bagaimana mungkin aku bisa meninggalkannya mati di penjara saat dia ditangkap secara tidak adil?",
  ui_story_5070_50700501_69_dialog_content = "Itulah sebabnya aku belum bisa mati. Belum saatnya.",
  ui_story_5070_50700501_70_dialog_content = "Aku bersumpah akan kembali ke Longzhou dan membersihkan nama baiknya sebelum aku menghembuskan nafas terakhirku.",
  ui_story_5070_50700501_71_dialog_content = "Tak heran kalian berdua sangat waspada padaku saat aku baru tiba.",
  ui_story_5070_50700501_72_dialog_content = "Apakah kamu telah melawan binatang mekanik ini sejak dulu?",
  ui_story_5070_50700501_73_dialog_content = "Tak kurang juga tentara bayaran Barat yang mengejar kita!",
  ui_story_5070_50700501_74_dialog_content = "Tampaknya para bajak laut itu mendapat dukungan dari kekuatan yang lebih besar di dunia.",
  ui_story_5070_50700501_75_dialog_content = "Dengan begitu banyak pembunuh yang terus-menerus memburu kita, aku khawatir kekuatan-kekuatan ini ingin melihat kita terkubur di tanah asing ini, bersama dengan kebenaran.",
  ui_story_5070_50700501_76_dialog_content = "Jika mereka berhasil, Keluarga Lin tidak akan pernah dibebaskan dari kejahatan palsu ini.",
  ui_story_5070_50700501_77_dialog_content = "Bahkan di saat seperti ini, yang bisa kamu pikirkan hanyalah keluarga Lin... Aku benar-benar tidak tahu apakah itu baik atau buruk, Zhong Xu.",
  ui_story_5070_50700501_78_dialog_content = "Graaah—!",
  ui_story_5070_50700501_79_dialog_content = "Argh! Jangan lagi!",
  ui_story_5070_50700501_80_dialog_content = "Mohon maafkan ketidaksopanan saya tadi, Menteri Armilla. Saya tidak menyadari identitas asli Anda.",
  ui_story_5070_50700501_81_dialog_content = "Saya tidak ingin Anda terlibat dalam masalah kami, jadi tolong kabur selagi Anda bisa.",
  ui_story_5070_50700501_82_dialog_content = "Kamu tak perlu khawatir melibatkan aku.",
  ui_story_5070_50700501_83_dialog_content = "Justru, aku pelakunya di sini.",
  ui_story_5070_50700501_84_dialog_content = "Aku lah yang merancang binatang mekanik ini...",
  ui_story_5070_50700501_85_dialog_content = "Tapi mereka tidak pernah dimaksudkan untuk dieksploitasi dan diubah menjadi senjata oleh penjahat yang bersembunyi di bayangan!",
  ui_story_5070_50700501_86_dialog_content = "Awalnya saya khawatir tidak akan menemukan petunjuk lagi, tetapi orang-orang bodoh itu malah menyerahkan petunjuk langsung ke tangan saya.",
  ui_story_5070_50700501_87_dialog_content = "Sejujurnya, aku seharusnya berterima kasih pada kalian berdua.",
  ui_story_5070_50700501_88_dialog_content = "Anda beruntung, Pak Zhong Xu. Sepertinya kita memiliki musuh yang sama.",
  ui_story_5070_50700501_89_dialog_content = "... Jadi setelah semua itu, ternyata kita bukan musuh sejak awal?!",
  ui_story_5070_50700501_90_dialog_content = "Musuh-musuh kita mungkin tertawa terbahak-bahak, melihat kita berbickering bolak-balik sepanjang hari!",
  ui_story_5070_50700501_91_dialog_content = "Jangan sedih, anak kecil. Setelah kita mengurus penjahat-penjahat ini, aku akan membuatkan kamu berbagai macam mainan seru untuk bermain.",
  ui_story_5070_50700501_92_dialog_content = "Bagaimana dengan bola yang bagus dan berkilau?",
  ui_story_5070_50700501_93_dialog_content = "Saya juga bisa memperbaiki kursi roda Tuan Zhong Xu dan menambahkan beberapa fungsi baru ke dalamnya, jika Anda mau?",
  ui_story_5070_50700501_94_dialog_content = "Kemurahan hati Anda sangat dihargai.",
  ui_story_5070_50700501_95_dialog_content = "Tapi kursi roda ini hanyalah alat transportasi saya. Ini tidak memerlukan modifikasi yang tidak perlu.",
  ui_story_5070_50700501_96_dialog_content = "Hahaha! Anda mungkin bukan pengrajin, Tuan Zhong Xu, tetapi Anda pasti memahami makna sejati dari kerajinan kami.",
  ui_story_5070_50700501_97_dialog_content = "Dan itu membuatmu seratus kali lebih kuat daripada pengecut yang mengendalikan konspirasi seluruh ini.",
  ui_story_5070_50700502_1_dialog_content = "Dan itu... adalah apa yang terjadi pada Keluarga Lin.",
  ui_story_5070_50700502_2_dialog_content = "Saya mendengar rumor tentang keterlibatan Lin Guild dalam insiden penyelundupan enam bulan lalu, serta kerugian yang ditimbulkan pada nama mereka. Namun, ini adalah pertama kalinya saya diberi tahu detail tentang masalah tersebut.",
  ui_story_5070_50700502_3_dialog_content = "Jika apa yang Anda katakan benar, putusan dalam kasus ini tampaknya cukup sewenang-wenang.",
  ui_story_5070_50700502_4_dialog_content = "Tidak ada bukti pasti bahwa Keluarga Lin menyelundupkan barang selundupan, tetapi segala sesuatu yang lain tampaknya mengindikasikan hal tersebut.",
  ui_story_5070_50700502_5_dialog_content = "Ini tentu saja menempatkan Keluarga Lin dalam posisi yang tidak menguntungkan. Yang bisa mereka lakukan hanyalah menanggung rasa malu atas kejahatan ini.",
  ui_story_5070_50700502_6_dialog_content = "Ini juga menjelaskan mengapa Keluarga Lin begitu gigih untuk mengarungi lautan meskipun kehilangan armillary sphere mereka.",
  ui_story_5070_50700502_7_dialog_content = "Mereka sangat membutuhkan kesempatan untuk membangun kembali rute perdagangan mereka dan menghidupkan kembali guild mereka.",
  ui_story_5070_50700502_8_dialog_content = "*Huf* Awak Shadowind menghadapi berbagai masalah sejak awal.",
  ui_story_5070_50700502_9_dialog_content = "Inilah mengapa mereka sangat ingin berlayar dan kembali ke Longzhou.",
  ui_story_5070_50700502_10_dialog_content = "PlayerName.",
  ui_story_5070_50700502_11_dialog_content = "Apa itu, Dantang? Dan kenapa kamu terlihat begitu serius?",
  ui_story_5070_50700502_12_dialog_content = "Laut adalah tempat yang tak terduga. Sejak zaman dahulu, tak terhitung jumlah kapal yang gagal kembali dengan selamat dari pelayaran sepanjang ini.",
  ui_story_5070_50700502_13_dialog_content = "Selain jalur laut yang selalu berubah dan penyergapan musuh, perjalanan ke depan akan penuh dengan bahaya tak terduga lainnya.",
  ui_story_5070_50700502_14_dialog_content = "Jika Anda bersedia menaiki Shadowind, Anda juga harus bersedia untuk menjelajahi yang tidak diketahui.",
  ui_story_5070_50700502_15_dialog_content = "Yuebai memiliki kewajiban untuk memulihkan Lin Guild, dan saya memiliki tanggung jawab saya sendiri, yang tidak bisa saya tinggalkan.",
  ui_story_5070_50700502_16_dialog_content = "Kita semua memiliki alasan untuk menghadapi laut, dan telah menerima konsekuensi dari melakukannya.",
  ui_story_5070_50700502_17_dialog_content = "Tapi kamu berbeda, PlayerName.",
  ui_story_5070_50700502_18_dialog_content = "... Sebagai Putri Zhuohua, menyeretmu ke dalam masalah kami adalah satu-satunya solusi yang bisa kupikirkan saat itu.",
  ui_story_5070_50700502_19_dialog_content = "Tapi sebagai temanmu, Dantang... Aku khawatir tentang keselamatanmu.",
  ui_story_5070_50700502_20_dialog_content = "Aku benar-benar paham jika kamu memutuskan untuk menolak tawaran saya.",
  ui_story_5070_50700502_21_dialog_content = "Sejujurnya, aku tidak tahu apa yang aku harapkan kamu katakan.",
  ui_story_5070_50700502_22_dialog_content = "Hah?",
  ui_story_5070_50700502_23_dialog_content = "Kamu bilang bahwa kamu \"menyeret\" saya ke dalam masalahmu.",
  ui_story_5070_50700502_24_dialog_content = "Tapi apakah aku utusan Astra, atau Caelestite terakhir, atau bahkan hanya diriku yang biasa saja.",
  ui_story_5070_50700502_25_dialog_content = "Saya selalu mempertimbangkan situasi ini dengan hati-hati sebelum membuat keputusan apa pun.",
  ui_story_5070_50700502_26_dialog_content = "Dan sebagai temanmu, tentu saja aku ingin membantumu juga.",
  ui_story_5070_50700502_27_dialog_content = "PlayerName... Jika itu masalahnya, maka aku bersumpah akan melakukan segala yang ada dalam kekuasaanku untuk melindungimu dalam perjalanan ini.",
  ui_story_5070_50700502_28_dialog_content = "Aku hanya berdoa agar kita tidak menghadapi terlalu banyak tantangan di sepanjang perjalanan ini...",
  ui_story_5070_50700502_29_dialog_content = "Oh? Kenapa kapal belum berangkat juga? Dan kenapa semua orang tampak seperti akan menangis?",
  ui_story_5070_50700502_30_dialog_content = "...",
  ui_story_5070_50700502_31_dialog_content = "Santai saja, semua orang! Saya kebetulan menemukan seorang veteran tempur berpengalaman dan dokter legendaris untuk diajak dalam perjalanan ini.",
  ui_story_5070_50700502_32_dialog_content = "Dan jika yang terburuk terjadi, saya juga akan ada di sana!",
  ui_story_5070_50700502_33_dialog_content = "Meskipun aku bukan lagi penasihat raja Ye, tapi aku akan menghadapi gunung pedang dan lautan api jika sang putri memerintahkannya.",
  ui_story_5070_50700502_34_dialog_content = "Yang Mulia, Lady Xuan Ji telah kembali!",
  ui_story_5070_50700502_35_dialog_content = "Ya, aku bisa tahu dari semua kebisingan itu bahwa itu dia.",
  ui_story_5070_50700502_36_dialog_content = "Kata-katamu masih saja eksentrik seperti biasanya, Nyonya Menteri Armilla.",
  ui_story_5070_50700502_37_dialog_content = "Hati-hati, atau mungkin saja aku akan menempatkanmu dalam dilema berbahaya seperti itu.",
  ui_story_5070_50700502_38_dialog_content = "Hahahaha! Baiklah, sudah cukup bercandanya untuk sekarang.",
  ui_story_5070_50700502_39_dialog_content = "Aku dengar Shadowind diserang sebelumnya, jadi aku perlu memeriksa lambung kapalnya sekali lagi.",
  ui_story_5070_50700502_40_dialog_content = "Saya tidak pernah berpikir bahwa kepiting api saya akan digunakan untuk menyerang kapal suatu hari nanti.",
  ui_story_5070_50700502_41_dialog_content = "Sepertinya saya juga harus memperkuat atau memodifikasi sistem pasokan daya dan navigasi.",
  ui_story_5070_50700502_42_dialog_content = "Jangan khawatir, saya akan berusaha sebaik mungkin untuk membuat kapal ini seaman mungkin sebelum kita berlayar ke laut!",
  ui_story_5070_50700601_1_dialog_content = "(Terhormat Vice dan Carleen.)",
  ui_story_5070_50700601_2_dialog_content = "(Maaf atas balasan yang terlambat. Dalam sekejap mata, hari keberangkatan kami akhirnya tiba.)",
  ui_story_5070_50700601_3_dialog_content = "(Kami sedang dalam proses membuat persiapan terakhir untuk pelayaran, jadi semua orang benar-benar sibuk akhir-akhir ini.)",
  ui_story_5070_50700601_4_dialog_content = "Tukang Kapal Li! Suruh tim Anda melapisi bagian kritis lambung kapal dengan pelapis tahan api!",
  ui_story_5070_50700601_5_dialog_content = "Kita harus siap menghadapi kebakaran yang tak terduga serta serangan kepiting api!",
  ui_story_5070_50700601_6_dialog_content = "Aku akan memeriksa kapal untuk mencari tanda-tanda kebocoran.",
  ui_story_5070_50700601_7_dialog_content = "Juga, apakah ada yang tahu di mana kapten berada? Saya perlu meyakinkan dia untuk membeli beberapa perangkat penyimpan energi lagi sebelum kita meninggalkan Astra.",
  ui_story_5070_50700601_8_dialog_content = "Apa saja bisa terjadi di laut, dan memiliki cadangan energi tambahan akan membantu kita tetap siap.",
  ui_story_5070_50700601_9_dialog_content = "Tuan Zhong Xu?",
  ui_story_5070_50700601_10_dialog_content = "Maafkan aku karena tidak berbicara denganmu lebih awal. Beberapa hari terakhir ini sangat sibuk...",
  ui_story_5070_50700601_11_dialog_content = "Terima kasih telah memberi tahu saya kebenaran tentang insiden penyelundupan ini. Dengan informasi ini, nama baik keluarga Lin akhirnya dapat dipulihkan.",
  ui_story_5070_50700601_12_dialog_content = "Saya yakin Guildmaster Lin juga akan semakin diberani oleh kembalinya Anda dengan selamat. Kita seharusnya tidak akan kesulitan mengatasi rintangan ini nantinya.",
  ui_story_5070_50700601_13_dialog_content = "Aku hanya menjalankan tugas ku... Lagipula, aku adalah orang yang gagal melindungi dia.",
  ui_story_5070_50700601_14_dialog_content = "Namun, tidak ada yang tahu kapan para perompak akan menyerang lagi.",
  ui_story_5070_50700601_15_dialog_content = "Selama pertemuan kami enam bulan lalu, saya dapat mengenali secara kasar metode serangan mereka.",
  ui_story_5070_50700601_16_dialog_content = "Kita bisa menggunakan informasi ini untuk menyusun langkah-langkah penanggulangan.",
  ui_story_5070_50700601_17_dialog_content = "Cendana, rumput bubuk, mint, garut...",
  ui_story_5070_50700601_18_dialog_content = "Apakah kamu memiliki ramuan ini di stok? Jika iya, aku akan mengambil semua yang kamu punya!",
  ui_story_5070_50700601_19_dialog_content = "Itu pesanan yang cukup besar, anak muda.",
  ui_story_5070_50700601_20_dialog_content = "Hei, aku tidak memilih untuk bertanggung jawab atas kesehatan seluruh kapal.",
  ui_story_5070_50700601_21_dialog_content = "Saya perlu menimbun segala sesuatu yang dapat digunakan untuk mengobati hal-hal seperti menggigil dan mabuk laut. Semakin banyak, semakin baik!",
  ui_story_5070_50700601_22_dialog_content = "Mereka semua sibuk melakukan entah apa, jadi seseorang harus memastikan kita memiliki cukup persediaan medis untuk perjalanan, kan?",
  ui_story_5070_50700601_23_dialog_content = "Sekarang saya hanya perlu membeli cukup makanan untuk menjaga kesehatan semua orang selama kita di laut!",
  ui_story_5070_50700601_24_dialog_content = "Apakah kamu sudah selesai menulis surat perpisahanmu, Jiu?",
  ui_story_5070_50700601_25_dialog_content = "Ya, Yang Mulia. Sejujurnya, saya tidak perlu berpamitan dengan banyak orang.",
  ui_story_5070_50700601_26_dialog_content = "Tapi apakah kamu benar-benar perlu mengirim surat sebanyak ini?",
  ui_story_5070_50700601_27_dialog_content = "Kami bertemu banyak teman dan orang penting selama di sini, setelah semua.",
  ui_story_5070_50700601_28_dialog_content = "Kita harus menjaga hubungan baik jika ingin bekerja sama di masa depan.",
  ui_story_5070_50700601_29_dialog_content = "Ini mengingatkan saya bahwa saya masih perlu menulis surat untuk Asosiasi Guild Twin Pavilions Bay.",
  ui_story_5070_50700601_30_dialog_content = "Rekan-rekan bajak laut muncul di kota, dan mereka perlu segera ditangkap.",
  ui_story_5070_50700601_31_dialog_content = "(Bahkan saya harus pergi beberapa kali ke Umbraton untuk membantu semua orang membeli barang yang hanya bisa ditemukan di Astra.)",
  ui_story_5070_50700601_32_dialog_content = "(Sejujurnya, itu membuat saya merasa lebih seperti utusan Astra yang sesungguhnya.)",
  ui_story_5070_50700601_33_dialog_content = "(Setelah saya mengirimkan surat ini, Shadowind akan segera berlayar setelahnya.)",
  ui_story_5070_50700601_34_dialog_content = "(Semoga aku bisa memenuhi harapan semua orang dan menyelesaikan misi ini tanpa banyak masalah.)",
  ui_story_5070_50700601_35_dialog_content = "(Ketika saya kembali, pasti akan membawa banyak cerita dari Longzhou untuk semua orang dengar!)",
  ui_story_5070_50700601_36_dialog_content = "Nah, kalau bukan PlayerName!",
  ui_story_5070_50700601_37_dialog_content = "Hei, kau peramal itu dari sebelumnya!",
  ui_story_5070_50700601_38_dialog_content = "Jangan bicara lagi, temanku! Kekuatan ramalanku mengatakan bahwa kamu baru saja mengirimkan surat. Benarkah itu?",
  ui_story_5070_50700601_39_dialog_content = "...",
  ui_story_5070_50700601_40_dialog_content = "Apa yang kamu bicarakan? Kamu jelas-jelas baru saja melihatku keluar dari Serikat Kurir.",
  ui_story_5070_50700601_41_dialog_content = "Heheh, aku hanya bercanda.",
  ui_story_5070_50700601_42_dialog_content = "Sama seperti dirimu, saya juga seorang penumpang di kapal Shadowind.",
  ui_story_5070_50700601_43_dialog_content = "Maukah kamu kembali ke kapal bersamaku?",
  ui_story_5070_50700601_44_dialog_content = "Kurasa tidak. Apakah kamu juga sedang mengirim surat?",
  ui_story_5070_50700601_45_dialog_content = "Lebih baik jika kita tidak membahas itu.",
  ui_story_5070_50700601_46_dialog_content = "Aku ingin menikmati satu makanan terakhir di Astra sebelum pulang, tapi sepertinya hari ini kurang beruntung.",
  ui_story_5070_50700601_47_dialog_content = "Meskipun berkeliling kota setengah hari, saya belum beruntung bertemu dengan orang kaya.",
  ui_story_5070_50700601_48_dialog_content = "Sayang sekali, benar-benar.",
  ui_story_5070_50700601_49_dialog_content = "Apa hubungannya orang kaya dengan kamu makan?",
  ui_story_5070_50700601_50_dialog_content = "Kamu mungkin belum menyadari ini, tapi meskipun penampilanku sederhana...",
  ui_story_5070_50700601_51_dialog_content = "Sebenarnya, aku lebih miskin daripada yang terlihat. Bahkan, aku tidak punya satu Nightium pun atas namaku!",
  ui_story_5070_50700601_52_dialog_content = "Dan kamu... memilih untuk menjelajahi dunia meskipun begitu?",
  ui_story_5070_50700601_53_dialog_content = "Yah, aku cukup berbeda dari penumpang lainnya. Aku tidak memiliki motif khusus untuk diceritakan, begitu saja.",
  ui_story_5070_50700601_54_dialog_content = "Rasa ingin tahu untuk melihat negeri yang jauh mendorong saya untuk bepergian. Bagi saya, perjalananlah yang paling saya nikmati.",
  ui_story_5070_50700601_55_dialog_content = "Tidak ada bedanya jika saya bepergian ke benua lain atau ke sisi lain kolam.",
  ui_story_5070_50700601_56_dialog_content = "... Baiklah.",
  ui_story_5070_50700601_57_dialog_content = "(Meskipun aku hampir tidak mengerti apa yang dia katakan, entah bagaimana itu masuk akal.)",
  ui_story_5070_50700601_58_dialog_content = "Kamu merasa aku agak terlalu banyak bicara, bukan, teman?",
  ui_story_5070_50700601_59_dialog_content = "Lalu kenapa tidak aku berikan ramalan yang jujur dan tulus untukmu?",
  ui_story_5070_50700601_60_dialog_content = "Ramalan Hexagram Surgawi saya mencakup tikus, kerbau, harimau, kelinci, dan semua hewan zodiak lainnya, serta membaginya menjadi yin dan yang.",
  ui_story_5070_50700601_61_dialog_content = "Dengan itu, saya bisa mengetahui rahasia-rahasia langit dan memprediksi masa depan. Saya tidak bisa menjamin Anda akan mendapatkan kesempatan lain seperti ini!",
  ui_story_5070_50700601_62_dialog_content = "Tikus dan sapi? Tapi bukankah itu hanya hewan? Apa yang bisa mereka tunjukkan padamu?",
  ui_story_5070_50700601_63_dialog_content = "Kekayaan pengetahuan, teman saya.",
  ui_story_5070_50700601_64_dialog_content = "Mari kita ambil Shadowind sebagai contoh. Ayo, kita bisa berjalan sambil berbicara.",
  ui_story_5070_50700601_65_dialog_content = "Apakah Anda tahu bahwa kedua belas hewan zodiak ada di kapal?",
  ui_story_5070_50700601_66_dialog_content = "Nah, tikus di kapal memang bukan hal yang baru, tapi saya belum melihat ada sapi di sini.",
  ui_story_5070_50700601_67_dialog_content = "Orang-orang di Longzhou sangat memperhatikan imajeri. Bahkan, beberapa hal dinamai berdasarkan gambar yang mereka mirip.",
  ui_story_5070_50700601_68_dialog_content = "Lihat baji yang digunakan untuk menstabilkan tiang kapal itu? Di negeri kita, itu dikenal sebagai \"jembatan tikus.\"",
  ui_story_5070_50700601_69_dialog_content = "Dan rel pengaman di sepanjang tepi geladak? Itu disebut \"pagar sapi.\"",
  ui_story_5070_50700601_70_dialog_content = "Papan di geladak disebut \"wajah kuda\", sementara rangka kapal disebut \"tulang kerangka naga\". Apakah saya perlu menjelaskan lebih lanjut?",
  ui_story_5070_50700601_71_dialog_content = "Aku tidak menyadari mereka memiliki nama yang begitu imajinatif.",
  ui_story_5070_50700601_72_dialog_content = "Memang, dan seperti kapal ini, hexagram saya mencerminkan seluruh keberadaan, yang memungkinkan saya untuk melihat masa depan.",
  ui_story_5070_50700601_73_dialog_content = "Lalu, bisakah kamu melihat apa yang akan terjadi pada kapal ini selama perjalanan kita?",
  ui_story_5070_50700601_74_dialog_content = "Lagi... Lebih baik jika kamu tidak bertanya. Cukup ketahui bahwa aku juga membuat prediksi saat Shadowind diserang sebelumnya.",
  ui_story_5070_50700601_75_dialog_content = "Hasilnya adalah sapi yin dan kuda yin.",
  ui_story_5070_50700601_X75_dialog_content = "\"Seekor sapi mati tidak bergerak, dan seekor kuda mati tidak mengikik.\" Awalnya, saya mengartikannya bahwa kapal tidak akan bisa meninggalkan pelabuhan...",
  ui_story_5070_50700601_76_dialog_content = "Tapi Shadowind akan segera berangkat!",
  ui_story_5070_50700601_77_dialog_content = "Memang, ini berarti prediksi saya memerlukan interpretasi lebih lanjut. Mungkin saya bisa mendapatkan inspirasi lebih banyak dari wajah kuda dan pagar sapi di atas kapal?",
  ui_story_5070_50700601_78_dialog_content = "Bijaksana untuk tidak mendengarkan ocehan seorang pembohong, PlayerName.",
  ui_story_5070_50700601_79_dialog_content = "Ayo sekarang, Yang Mulia. Seni saya hanyalah cara bagi saya untuk menghidupi diri, tidak lebih.",
  ui_story_5070_50700601_80_dialog_content = "Jangan pedulikan dia, PlayerName. Kebanyakan penumpang sudah ada di kapal, jadi silakan naik.",
  ui_story_5070_50700601_81_dialog_content = "... Izinkan saya untuk mengecek daftar penumpang untuk terakhir kalinya.",
  ui_story_5070_50700601_82_dialog_content = "Tuan Zhong Xu, Dokter Liqing, Tuan Putri Dantang, Nona Jiu, dan PlayerName.",
  ui_story_5070_50700601_83_dialog_content = "Li, Sun, dan Lady Xuan Ji juga akan bergabung dalam perjalanan kita ke Longzhou sebagai teknisi Shadowind.",
  ui_story_5070_50700601_84_dialog_content = "Semua orang kini hadir dan siap.",
  ui_story_5070_50700601_85_dialog_content = "...",
  ui_story_5070_50700601_86_dialog_content = "Sebagai kapten kapal, seharusnya aku adalah orang terakhir yang menambah kekhawatiran para penumpang.",
  ui_story_5070_50700601_87_dialog_content = "Namun, mengingat keadaan khusus dari perjalanan kita, saya merasa harus menjelaskan sesuatu dengan sangat jelas kepada semua orang.",
  ui_story_5070_50700601_88_dialog_content = "Tanpa armillary sphere kita, lokasi Shadowind tidak dapat dipastikan saat berlayar di lautan lepas.",
  ui_story_5070_50700601_89_dialog_content = "Tugas kita untuk menentukan arah perjalanan kapal.",
  ui_story_5070_50700601_90_dialog_content = "Badai mendadak, Eclipsites ganas, dan bahkan musuh yang tak terlihat juga diharapkan di luar sana.",
  ui_story_5070_50700601_91_dialog_content = "Bahaya yang akan kita hadapi nanti jauh lebih besar daripada apa pun yang pernah kita hadapi dalam pelayaran sebelumnya.",
  ui_story_5070_50700601_92_dialog_content = "Jika ada yang ingin meninggalkan kapal, sekarang saatnya melakukannya.",
  ui_story_5070_50700601_93_dialog_content = "(Sesuai dugaan, tidak ada yang bergerak sedikit pun. Mereka semua bertekad untuk melakukan perjalanan kembali.)",
  ui_story_5070_50700601_94_dialog_content = "Karena kalian semua telah memilih untuk mempercayai Shadowind, maka sebagai kapten kapal, saya bersumpah untuk membawa kita semua dengan selamat ke pantai Longzhou.",
  ui_story_5070_50700601_95_dialog_content = "Shadowind mulai berlayar sekarang!",
  ui_story_5070_50700701_1_dialog_content = "<color=#e8d9bb>cipratan... cipratan...</color>",
  ui_story_5070_50700701_2_dialog_content = "(Sudah beberapa hari sejak kita berangkat. Ini adalah pertama kalinya aku meninggalkan Astra dengan kapal.)",
  ui_story_5070_50700701_3_dialog_content = "(Langit biru, ombak bergulung, angin laut yang menyegarkan, dan tujuan yang belum diketahui... Ditambah, sedikit kesendirian.)",
  ui_story_5070_50700701_4_dialog_content = "Kamu begitu fokus. Apa yang sedang kaupikirkan?",
  ui_story_5070_50700701_5_dialog_content = "Oh, Xuan Ji!",
  ui_story_5070_50700701_6_dialog_content = "Aku baru saja berpikir bahwa perasaan menyeberangi samudra dengan kapal benar-benar berbeda dari menaiki Colossus.",
  ui_story_5070_50700701_7_dialog_content = "Oh? Bagaimana keadaan di Colossus?",
  ui_story_5070_50700701_8_dialog_content = "Jarang sekali kamu membahas topik ini. Secara umum, Colossus adalah mesin, bukan?",
  ui_story_5070_50700701_9_dialog_content = "Bukankah itu agak luas?",
  ui_story_5070_50700701_10_dialog_content = "Bukan itu intinya.",
  ui_story_5070_50700701_11_dialog_content = "Intinya, kamu benar-benar bisa mengendalikan raksasa yang lebih besar dari Shadowind itu sendirian?",
  ui_story_5070_50700701_12_dialog_content = "Seberapa cepat? Berapa konsumsi bahan bakarnya? Bagaimana bahan-bahan menangani perubahan musim?",
  ui_story_5070_50700701_13_dialog_content = "Sebagai mesin terbang, selain dorongan, bentuknya juga mempengaruhi aerodinamika dan angkatannya...",
  ui_story_5070_50700701_14_dialog_content = "Kamu belum pernah menjelaskan hal-hal itu kepadaku sebelumnya.",
  ui_story_5070_50700701_15_dialog_content = "T-Tunggu sebentar... Apa aku baru saja membuka masalah baru...?",
  ui_story_5070_50700701_16_dialog_content = "Nah, jika itu rahasia, kita harus menjaganya seperti itu!",
  ui_story_5070_50700701_17_dialog_content = "Bukan rahasia. Hanya saja, bahkan saya sendiri tidak dapat memberikan jawaban yang tepat untuk beberapa pertanyaan.",
  ui_story_5070_50700701_18_dialog_content = "Pikirkanlah! Taffrail, kemudi, tiang Shadowind...",
  ui_story_5070_50700701_19_dialog_content = "Yuebai dan kawan-kawan harus menangani segala sesuatu di kapal secara manual.",
  ui_story_5070_50700701_20_dialog_content = "Jika ada perubahan kecepatan atau arah angin, mereka harus segera memutuskan cara memodifikasi kapal.",
  ui_story_5070_50700701_21_dialog_content = "Namun informasi dalam database-nya memungkinkan Soroz untuk menangani semua jenis hal ini.",
  ui_story_5070_50700701_22_dialog_content = "Hanya pada saat-saat kritis, aku perlu membimbingnya dengan kata-kata atau melodi.",
  ui_story_5070_50700701_23_dialog_content = "Jadi, ini melampaui kontrol sederhana, tetapi membiarkannya menjalankan rutinitas logis dan hanya mengeksekusi perintah.",
  ui_story_5070_50700701_24_dialog_content = "Itu seperti mitos yang menjadi kenyataan.",
  ui_story_5070_50700701_25_dialog_content = "Mitos? Longzhou?",
  ui_story_5070_50700701_26_dialog_content = "Benar. Buku sejarah kuno membahas tentang jin yang cukup besar untuk menutupi matahari.",
  ui_story_5070_50700701_27_dialog_content = "Dioperasikan oleh orang-orang yang disebut \"Pelayan Djinn\" untuk menjelajahi darat dan laut dalam penaklukan.",
  ui_story_5070_50700701_28_dialog_content = "Wah, itu luar biasa... Soroz tidak bisa menghalangi matahari.",
  ui_story_5070_50700701_29_dialog_content = "Namun seberapa tinggi pun kamu terbang, langit dan bulan selalu terasa tak terjangkau...",
  ui_story_5070_50700701_30_dialog_content = "Aku tak yakin.",
  ui_story_5070_50700701_31_dialog_content = "Hah?",
  ui_story_5070_50700701_32_dialog_content = "Aku naik ke geladak untuk mengukur ketinggian matahari.",
  ui_story_5070_50700701_33_dialog_content = "Itu bukan nama untuk sesuatu, bukan? Matahari di atas kita?",
  ui_story_5070_50700701_34_dialog_content = "Ada sekolah astrologi kuno di Longzhou.",
  ui_story_5070_50700701_35_dialog_content = "Yang kamu butuhkan hanyalah sebuah astrolab untuk menghitung jarak antara matahari, bulan, atau bahkan dua bintang.",
  ui_story_5070_50700701_36_dialog_content = "Mengingat kita bisa menghitung ketinggian dan lintasan...",
  ui_story_5070_50700701_37_dialog_content = "Tidak akan sulit untuk mengubah bingkai Colossus-mu agar bisa menahan sinar matahari!",
  ui_story_5070_50700701_38_dialog_content = "Ini jelas hiperbola, tapi karena dari kamu, sama sekali tidak terdengar seperti lelucon...",
  ui_story_5070_50700701_39_dialog_content = "Maka, saya akan berterima kasih atas kepercayaan Anda kepadaku.",
  ui_story_5070_50700701_40_dialog_content = "Tapi aku tahu prinsip perlahan tapi pasti, membangun sebuah alat satu bagian demi satu bagian.",
  ui_story_5070_50700701_41_dialog_content = "Meskipun kita tidak bisa sampai di sana sekarang...",
  ui_story_5070_50700701_42_dialog_content = "Tetapi kita masih bisa melakukan banyak hal dengan mengetahui posisi, sudut, dan data lainnya tentang matahari.",
  ui_story_5070_50700701_43_dialog_content = "Seperti melengkapi peta Lin untuk menentukan koordinat Shadowind saat ini.",
  ui_story_5070_50700701_44_dialog_content = "Selama kamu selalu sadar posisimu, kamu tidak akan pernah tersesat di laut!",
  ui_story_5070_50700701_45_dialog_content = "Lebih mudah diucapkan daripada dilakukan. Laut terlalu tak terduga untuk perkiraan buatan agar tetap konsisten dan akurat.",
  ui_story_5070_50700701_46_dialog_content = "Itulah mengapa bola armilari, yang mampu menampilkan konstelasi dan menunjukkan lokasi dengan tepat, sangat dihargai sebagai harta karun keluarga Lin.",
  ui_story_5070_50700701_47_dialog_content = "Hal ini membuat tidak mungkin untuk sengaja mengarahkan kapal ke jalur yang salah dengan seorang ahli astronomi yang kompeten di atas kapal.",
  ui_story_5070_50700701_48_dialog_content = "Sayang sekali, meskipun...",
  ui_story_5070_50700701_49_dialog_content = "Armillary sphere... Aku ingat itu ada di kapal Keluarga Lin yang dibajak oleh bajak laut, menghilang bersama dengan kapal itu.",
  ui_story_5070_50700701_50_dialog_content = "Ya, itulah mengapa saya mengisi.",
  ui_story_5070_50700701_51_dialog_content = "Semua telah dilakukan oleh perangkat di masa lalu, jadi betapa mengejutkannya bagi seorang pengrajin untuk menggantikan mesin.",
  ui_story_5070_50700701_52_dialog_content = "Tapi dengan cara ini, Xuan Ji juga bisa dianggap sebagai navigator Shadowind.",
  ui_story_5070_50700701_53_dialog_content = "Hanya sementara.",
  ui_story_5070_50700701_54_dialog_content = "Jangan meremehkan dirimu sendiri, Menteri Armilla.",
  ui_story_5070_50700701_55_dialog_content = "Nama Xuan Ji berarti Armilla, yang merupakan nama lain untuk bola armilari.",
  ui_story_5070_50700701_56_dialog_content = "Armilla adalah gelar yang sempurna untuk kamu.",
  ui_story_5070_50700701_57_dialog_content = "Maka sudah sepatutnya, Xuan Ji menggantikan bola tersebut.",
  ui_story_5070_50700701_58_dialog_content = "Apakah saya membayangkan sesuatu? Kenapa sepertinya mengatakan bahwa Xuan Ji sebelumnya tidak melakukan pekerjaan dengan baik?",
  ui_story_5070_50700701_59_dialog_content = "Seorang penasihat kunci meninggalkan posisi penting tanpa izin, hanya meninggalkan sebuah surat.",
  ui_story_5070_50700701_60_dialog_content = "Seorang pengrajin terkenal yang meninggalkan bengkel dan berbagai barang ajaibnya, lebih memilih untuk bepergian sendirian hanya dengan membawa payung di tangan.",
  ui_story_5070_50700701_61_dialog_content = "Bagaimana Anda menjelaskan kelayakan itu, Menteri Armilla?",
  ui_story_5070_50700701_62_dialog_content = "Yang Mulia...",
  ui_story_5070_50700701_63_dialog_content = "Yang Mulia, saya yakin Lady Xuan Ji pasti punya alasan tersendiri.",
  ui_story_5070_50700701_64_dialog_content = "...",
  ui_story_5070_50700701_65_dialog_content = "Ayolah, tidak serumit itu.",
  ui_story_5070_50700701_66_dialog_content = "Sebuah rancangan desain dicuri, dan sekolahku kebetulan memintaku untuk mengambil artefak dari Astra.",
  ui_story_5070_50700701_67_dialog_content = "Terjadi begitu cepat, aku tidak punya waktu untuk mengucapkan selamat tinggal dengan benar.",
  ui_story_5070_50700701_68_dialog_content = "Kamu tidak masih marah karena aku menolak mengajari kamu tentang gadget, kan, Putri?",
  ui_story_5070_50700701_69_dialog_content = "Saya juga masih muda dan bodoh saat itu, jadi mengapa Anda tidak memaafkan saya, Yang Mulia?",
  ui_story_5070_50700701_70_dialog_content = "Apa maksudmu dengan \"saat itu\"? Aku tidak melihat ada perubahan...",
  ui_story_5070_50700701_71_dialog_content = "Pff—Ah, maaf.",
  ui_story_5070_50700701_72_dialog_content = "Jarang sekali melihat Dantang menunjukkan ekspresi seperti ini. Rasanya seperti melihat sisi yang berbeda dari biasanya.",
  ui_story_5070_50700701_73_dialog_content = "Ya ampun, kamu juga...",
  ui_story_5070_50700701_74_dialog_content = "Maafkan saya, mohon maafkan kesalahan saya ini.",
  ui_story_5070_50700701_75_dialog_content = "Ini bukan waktu atau tempat yang tepat untuk saya mengobrol.",
  ui_story_5070_50700701_76_dialog_content = "Menteri Armilla ditugaskan untuk tugas navigasi...",
  ui_story_5070_50700701_77_dialog_content = "Tetapi sebagai tamu, Anda mengambil inisiatif untuk menyurvei permukaan laut, PlayerName.",
  ui_story_5070_50700701_78_dialog_content = "Aku sudah merasa cukup malu dan bersalah, apalagi mengganggu kalian berdua.",
  ui_story_5070_50700701_79_dialog_content = "Jangan khawatir. Toh, aku bisa merasakan kedatangan para Eclipsite, jadi menerima tugas ini...",
  ui_story_5070_50700701_80_dialog_content = "Tunggu!",
  ui_story_5070_50700701_81_dialog_content = "Kamu mungkin tidak ingin mengganggu, Tuan Putri.",
  ui_story_5070_50700701_82_dialog_content = "Tapi beberapa hal di luar sana tidak se-sopan seperti kamu.",
  ui_story_5070_50700701_83_dialog_content = "Mereka sedang datang untuk mengganggu PlayerName saat ini juga.",
  ui_story_5070_50700702_1_dialog_content = "Fiuh, akhirnya selesai! Saya tidak menyangka akan ada begitu banyak Eclipsites yang tiba-tiba muncul.",
  ui_story_5070_50700702_2_dialog_content = "Sebenarnya, itu pertanda baik.",
  ui_story_5070_50700702_3_dialog_content = "Eclipsite aktif adalah kabar baik?!",
  ui_story_5070_50700702_4_dialog_content = "Itu berarti kita cukup dekat dengan Astra di mana Eclipsite berkeliaran.",
  ui_story_5070_50700702_5_dialog_content = "Instrumen tidak berbohong, tetapi tidak demikian dengan mata kita.",
  ui_story_5070_50700702_6_dialog_content = "Berdasarkan perhitungan, kita seharusnya berada di dekat Astra, tetapi sulit untuk memastikannya di lautan yang luas.",
  ui_story_5070_50700702_7_dialog_content = "Mereka yang menyerang kita membuktikan bahwa kita berada di jalur yang benar.",
  ui_story_5070_50700702_8_dialog_content = "Mereka tidak hanya mengorbankan diri, tetapi juga memberikan bukti untukku.",
  ui_story_5070_50700702_9_dialog_content = "Aku membunuh mereka dengan rasa terima kasih yang tulus di pikiran.",
  ui_story_5070_50700702_10_dialog_content = "Aku tidak tahu bagaimana perasaan Eclipsites itu saat mereka mendengar pikiranmu...",
  ui_story_5070_50700702_11_dialog_content = "Karena perhitungannya benar, itu berarti Shadowind berada di jalur yang tepat.",
  ui_story_5070_50700702_12_dialog_content = "Angin mendorong kapal dari sudut yang tepat, sehingga kita bisa menghemat bahan bakar.",
  ui_story_5070_50700702_13_dialog_content = "Ayo bekerja, Sun yang Cakap!",
  ui_story_5070_50700702_14_dialog_content = "... Meskipun itu yang dikatakan oleh Lady Xuan Ji, kita harus tetap waspada karena roh jahat itu tidak akan menyerah begitu saja.",
  ui_story_5070_50700702_15_dialog_content = "Yang Mulia, tolong tetap dekat denganku.",
  ui_story_5070_50700702_16_dialog_content = "Roh jahat jauh lebih umum di sekitar Astra daripada di Longzhou.",
  ui_story_5070_50700702_17_dialog_content = "Roh jahat? Saya pernah mendengar itu sebelumnya, apakah itu istilah Longzhou?",
  ui_story_5070_50700702_18_dialog_content = "Memang. Makhluk yang disebut Eclipsites di Astra disebut roh jahat di Longzhou.",
  ui_story_5070_50700702_19_dialog_content = "Bpk. Zhong Xu...",
  ui_story_5070_50700702_20_dialog_content = "Tidak apa-apa tidak istirahat di kabin? Baru saja saya melihat Liqing berteriak minta kamu membawa obat.",
  ui_story_5070_50700702_21_dialog_content = "Liqing selalu menunjukkan dedikasi dalam mengobati pasiennya.",
  ui_story_5070_50700702_22_dialog_content = "Meskipun aku tidak bisa berjalan lagi, aku masih bisa menggunakan pedangku, jadi aku akan baik-baik saja.",
  ui_story_5070_50700702_23_dialog_content = "...",
  ui_story_5070_50700702_24_dialog_content = "Zhong Xu... Pak.",
  ui_story_5070_50700702_25_dialog_content = "Tuan Putri Dantang, kamu tidak perlu terlalu berhati-hati di sekitar pengembara seperti saya. Kalian semua harus sedikit bersantai.",
  ui_story_5070_50700702_26_dialog_content = "Sobat muda, kau harus istirahat dan serahkan tugas menjaga kepada saya.",
  ui_story_5070_50700702_27_dialog_content = "Eh? Jangan khawatir tentang aku, karena perairan ini sangat berbahaya, selalu baik untuk memiliki lebih banyak orang yang menjaga.",
  ui_story_5070_50700702_28_dialog_content = "Terima kasih atas kewaspadaan Anda. Keadaan akan membaik di sekitar pantai Longzhou.",
  ui_story_5070_50700702_29_dialog_content = "Lagi pula, makhluk-makhluk kegelapan jauh kurang aktif di Longzhou daripada di Astra.",
  ui_story_5070_50700702_30_dialog_content = "Kekaisaran rutin mengadakan ritual besar untuk menekan roh-roh jahat. Kerajaan-kerajaan bawahan juga memiliki cara mereka sendiri untuk menghadapi mereka.",
  ui_story_5070_50700702_31_dialog_content = "Roh-roh jahat biasanya bersembunyi di pegunungan, hanya muncul saat kelangsungan hidup mereka terancam untuk menangkap mereka yang sedang bepergian sendirian.",
  ui_story_5070_50700702_32_dialog_content = "Mungkin kamu tidak menyadari bahwa roh-roh jahat di banyak tempat telah gelisah dalam beberapa bulan terakhir.",
  ui_story_5070_50700702_33_dialog_content = "Serangan terhadap warga sipil semakin sering terjadi. Beberapa monster bahkan berhasil menyusup ke kota dan menimbulkan kekacauan.",
  ui_story_5070_50700702_34_dialog_content = "Pertahanan dari berbagai negara berusaha tanpa henti, namun sia-sia.",
  ui_story_5070_50700702_35_dialog_content = "Kini, orang-orang hidup dalam ketakutan, tidak tahu apakah itu Fiendling atau elemen lainnya...",
  ui_story_5070_50700702_36_dialog_content = "Kamu tidak suka Fiendlings?",
  ui_story_5070_50700702_37_dialog_content = "Apa? Tidak, aku hanya khawatir, itu saja...",
  ui_story_5070_50700702_38_dialog_content = "Tunggu, apa itu Fiendling?",
  ui_story_5070_50700702_39_dialog_content = "Kamu dibesarkan di Astra, jadi namanya tidak familiar bagi kamu. Mereka mirip dengan demi-human di Astra.",
  ui_story_5070_50700702_40_dialog_content = "Satu-satunya perbedaan adalah bahwa demi-human secara alami memiliki karakteristik hewan.",
  ui_story_5070_50700702_41_dialog_content = "Sedangkan Fiendlings mendapatkan bentuk demi-human mereka setelah mempelajari Force Arts.",
  ui_story_5070_50700702_42_dialog_content = "Beberapa orang jijik dengan Fiendlings, tetapi ada juga yang menyukai mereka karena kemampuan dan nilai-nilai yang mereka perjuangkan.",
  ui_story_5070_50700702_43_dialog_content = "Misalnya, orang-orang pelayaran sangat ingin membuka pintu mereka untuk setiap Fiendling berbentuk ikan yang jinak muncul.",
  ui_story_5070_50700702_44_dialog_content = "... Meskipun saya telah mengalami banyak petualangan di laut, saya tidak akrab dengan ikan, jadi saya tidak akan pernah menerima berkah dari mereka.",
  ui_story_5070_50700702_45_dialog_content = "Ikan besar itu berbahaya, jadi semoga kita tidak bertemu dengan mereka.",
  ui_story_5070_50700702_46_dialog_content = "Ah, mengerti.",
  ui_story_5070_50700702_47_dialog_content = "Ini seperti di Astra, di mana beberapa orang percaya bahwa hewan tertentu membawa keberuntungan, sementara yang lain menandakan petaka.",
  ui_story_5070_50700702_48_dialog_content = "Tepat sekali, tetapi klaim bahwa Fiendlings memberikan berkat tidak sepenuhnya tidak berdasar.",
  ui_story_5070_50700702_49_dialog_content = "Di masa lalu, beberapa Fiendling telah secara aktif melindungi perdamaian di beberapa wilayah setelah menyempurnakan bentuk demi-human mereka.",
  ui_story_5070_50700702_50_dialog_content = "Bahkan istana kekaisaran pun bersedia mengakui mereka dengan dekrit kekaisaran dan mengizinkan rakyat untuk membangun kuil untuk menyembah mereka.",
  ui_story_5070_50700702_51_dialog_content = "Wow, aku tidak tahu apakah aku akan punya kesempatan untuk melihat Fiendlings ini.",
  ui_story_5070_50700702_52_dialog_content = "Anda tahu banyak tentang ini, Zhong Xu.",
  ui_story_5070_50700702_53_dialog_content = "Entah mengusir iblis atau melakukan ritual...",
  ui_story_5070_50700702_54_dialog_content = "Tidak ada seorang pun di kapal ini yang bisa menyaingi pengetahuan dan pengalamannya.",
  ui_story_5070_50700702_55_dialog_content = "Anda dapat menanyakan Sir Zhong Xu untuk informasi lebih lanjut yang ingin Anda ketahui, PlayerName.",
  ui_story_5070_50700702_56_dialog_content = "Saya hanya berharap roh jahat di laut bertindak lambat agar memberi kita waktu untuk berkoordinasi.",
  ui_story_5070_50700702_57_dialog_content = "(Sayangnya, Eclipsites tidak begitu pintar, karena kami harus melalui beberapa pertempuran lagi sebelum akhirnya bisa melewati area tersebut.)",
  ui_story_5070_50700702_58_dialog_content = "(Aku belum menyadarinya.)",
  ui_story_5070_50700702_59_dialog_content = "(Tapi Eclipsites bukanlah satu-satunya bahaya di lautan.)",
  ui_story_5070_50700801_1_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5070_50700801_2_dialog_content = "<color=#e8d9bb>Percikan—!</color>",
  ui_story_5070_50700801_3_dialog_content = "PlayerName! PlayerName! Bangunlah!",
  ui_story_5070_50700801_4_dialog_content = "Uh... Xuan Ji?",
  ui_story_5070_50700801_5_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700801_6_dialog_content = "Wah... Ada apa?",
  ui_story_5070_50700801_7_dialog_content = "Api menyebar cepat! Cepat, bawa tas air ke sini!",
  ui_story_5070_50700801_8_dialog_content = "Ugh! Evakuasi belum selesai! Berhenti mendorong! Jangan berdesak-desakan masuk ke kabin!",
  ui_story_5070_50700801_9_dialog_content = "Tutup mulut! Lindungi gudang bahan bakar; jika terbakar di sini, kita akan selesai!",
  ui_story_5070_50700801_10_dialog_content = "Ribut sekali... Apa yang sedang terjadi di kapal?",
  ui_story_5070_50700801_11_dialog_content = "Kami memasuki laut jauh tidak lama yang lalu, di mana cuaca menjadi semakin tidak dapat diprediksi.",
  ui_story_5070_50700801_12_dialog_content = "Keberuntungan juga tidak ada di pihak kita. Kita mendapat nasib paling buruk yang mungkin.",
  ui_story_5070_50700801_13_dialog_content = "—Badai petir.",
  ui_story_5070_50700801_14_dialog_content = "Kami bisa mengatasi badai biasa tanpa masalah, tetapi sebuah petir baru saja menyambar kapal dan menyebabkan ledakan.",
  ui_story_5070_50700801_15_dialog_content = "Sekarang kami sedang melakukan pemadaman kebakaran dan evakuasi.",
  ui_story_5070_50700801_16_dialog_content = "Petir, ledakan?",
  ui_story_5070_50700801_17_dialog_content = "Bukankah kita sudah memeriksa perlindungan petir dan kebakaran sebelum kita pergi? Bagaimana ini bisa terjadi?",
  ui_story_5070_50700801_18_dialog_content = "Mereka hanya efektif melawan kebakaran alami.",
  ui_story_5070_50700801_19_dialog_content = "Masalahnya, mungkin itu bukan satu-satunya masalah yang kita hadapi.",
  ui_story_5070_50700801_20_dialog_content = "Hah?",
  ui_story_5070_50700801_21_dialog_content = "Ini bukan saatnya untuk menjelaskan, bukan karena saya tahu persis apa yang terjadi dengan petir dan api ini.",
  ui_story_5070_50700801_22_dialog_content = "Ada yang bisa saya bantu?",
  ui_story_5070_50700801_23_dialog_content = "Nah, ide awalnya adalah membawamu ke tempat yang aman, tapi sekarang kamu malah jadi tambahan tangan yang membantu.",
  ui_story_5070_50700801_24_dialog_content = "Jadi kami akan menugaskan Anda untuk bekerja.",
  ui_story_5070_50700801_25_dialog_content = "Ikuti aku.",
  ui_story_5070_50700801_26_dialog_content = "Kenapa api ini belum terkendali juga? Apa yang sedang kalian lakukan?!",
  ui_story_5070_50700801_27_dialog_content = "Cobalah sendiri! Kita sudah mempertaruhkan nyawa kita untuk menghentikan penyebaran api ke luar!",
  ui_story_5070_50700801_28_dialog_content = "Sial, kenapa api malah mulai dari bawah? Kabin ini semua kayu; tidak akan kuat!",
  ui_story_5070_50700801_29_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700801_30_dialog_content = "<color=#e8d9bb>Kali ini ledakan keras tepat di depan; pintu kabin depan meledak terbuka, kobaran api menerjang masuk!</color>",
  ui_story_5070_50700801_31_dialog_content = "<color=#e8d9bb>Swus—</color>",
  ui_story_5070_50700801_32_dialog_content = "<color=#e8d9bb>Potongan kayu yang terbakar berhenti beberapa inci sebelum tukang kapal, hancur menjadi beberapa serpihan di udara.</color>",
  ui_story_5070_50700801_33_dialog_content = "Baik api maupun air tak kenal belas kasihan. Hal terakhir yang harus kamu lakukan ketika terjadi sesuatu yang tak terduga adalah panik.",
  ui_story_5070_50700801_34_dialog_content = "Tak apa merasa takut, tetapi jangan biarkan teman-teman Anda membayar harga ketakutan Anda.",
  ui_story_5070_50700801_35_dialog_content = "Tuan Zhong Xu! T-Terima kasih, tuan, telah menyelamatkan kami!",
  ui_story_5070_50700801_36_dialog_content = "Sejujurnya, saya tidak bisa menangani masalah di kapal ini sendirian. Saya membutuhkan dukungan Anda, Pak.",
  ui_story_5070_50700801_37_dialog_content = "Tolong beritahu kami, apa yang harus kita lakukan sekarang?",
  ui_story_5070_50700801_38_dialog_content = "Di kapal ini, kamu harus mengikuti perintah kapten, bukan aku.",
  ui_story_5070_50700801_39_dialog_content = "Tuan Zhong Xu, terima kasih telah membantu kami.",
  ui_story_5070_50700801_40_dialog_content = "Kapten, maaf membuat Anda menangani masalah kami saat mengemudikan kapal...",
  ui_story_5070_50700801_41_dialog_content = "Tidak usah banyak bicara. Seorang kapten yang tidak menanggung tanggung jawab terbesar di kapal bukanlah kapten yang layak.",
  ui_story_5070_50700801_42_dialog_content = "Saya telah memeriksa kondisi kapal. Kita seharusnya bisa menghentikan api ini jika kita bertindak sekarang.",
  ui_story_5070_50700801_43_dialog_content = "Ya!",
  ui_story_5070_50700801_44_dialog_content = "Badai ini masih ganas... Dr. Liqing, tolong bawa para pengungsi lebih jauh lagi!",
  ui_story_5070_50700801_45_dialog_content = "Semua orang lain harus menyiapkan kantong linen dan memutuskan benda-benda yang terbakar dengan kait api.",
  ui_story_5070_50700801_46_dialog_content = "Bala bantuan akan datang nanti.",
  ui_story_5070_50700801_47_dialog_content = "*Batuk* Udara di sini semakin panas. Kita tidak akan bisa tinggal di sini lebih lama lagi.",
  ui_story_5070_50700801_48_dialog_content = "Aku membawa beberapa barang lain, Xuan Ji. Apakah ada yang bisa kita gunakan?",
  ui_story_5070_50700801_49_dialog_content = "Kayu yang digunakan untuk membuat kabin tidak akan cukup kuat, mengingat tekanan air...",
  ui_story_5070_50700801_50_dialog_content = "Xuan Ji?",
  ui_story_5070_50700801_51_dialog_content = "Kembali dengan barang-barangnya begitu cepat, PlayerName?",
  ui_story_5070_50700801_52_dialog_content = "Sebenarnya sudah cukup lama, tapi kamu begitu fokus sehingga tidak menyadarinya.",
  ui_story_5070_50700801_53_dialog_content = "Sementara kamu memang memintaku untuk mencari material yang berguna...",
  ui_story_5070_50700801_54_dialog_content = "Yang bisa saya temukan di sekitar sini hanyalah kotak-kotak kosong dan bagian-bagian yang terbuang.",
  ui_story_5070_50700801_55_dialog_content = "Kamu benar-benar berpikir kita bisa membuat sesuatu untuk memadamkan api hanya dengan barang-barang ini?",
  ui_story_5070_50700801_56_dialog_content = "Kita harus melakukannya. Api telah menyegel jalan ke ruang kargo, jadi improvisasi menjadi satu-satunya pilihan kita.",
  ui_story_5070_50700801_57_dialog_content = "Namun untuk pengrajin, tidak perlu menggunakan komponen yang telah ditentukan atau terbaik.",
  ui_story_5070_50700801_58_dialog_content = "Kita bisa membuat kayu lebih keras dengan pelapisan, menggantikan paku yang hilang dengan sambungan mortir dan pasak, serta memodifikasi struktur untuk membuat keseluruhan lebih kuat.",
  ui_story_5070_50700801_59_dialog_content = "Gabungkan semua yang telah kita lihat dan pelajari untuk membuat apapun yang Anda butuhkan.",
  ui_story_5070_50700801_60_dialog_content = "Adaptasi fleksibel adalah inti sejati dari perkakas gadget.",
  ui_story_5070_50700801_61_dialog_content = "Selesai! Kita bisa pergi membantu sekarang.",
  ui_story_5070_50700801_62_dialog_content = "Kapten! Api di atas akhirnya terkendali, tapi di dalam kabin...",
  ui_story_5070_50700801_63_dialog_content = "Tidak apa-apa.",
  ui_story_5070_50700801_64_dialog_content = "Maaf membuatmu menunggu—",
  ui_story_5070_50700801_65_dialog_content = "Memerlukan waktu untuk merangkai secara sementara, tapi kepuasan dijamin!",
  ui_story_5070_50700801_66_dialog_content = "Lady Xuan Ji, apa ini... benda?",
  ui_story_5070_50700801_67_dialog_content = "Anda bisa mengaktifkan itu sekarang, PlayerName.",
  ui_story_5070_50700801_68_dialog_content = "Baiklah!",
  ui_story_5070_50700801_69_dialog_content = "<color=#e8d9bb>Jepret, jepret.</color>",
  ui_story_5070_50700801_70_dialog_content = "<color=#e8d9bb>Papan kayu dan pelat logam yang dulu berserakan dan longgar, kini secara spontan berputar, bergabung, dan saling menyatu.</color>",
  ui_story_5070_50700801_71_dialog_content = "<color=#e8d9bb>Dengan satu ujung tergantung ke dalam air laut dari sisi kapal dan ujung lainnya berdiri di atas geladak, ini menyerupai naga mekanik yang bangga muncul dari laut.</color>",
  ui_story_5070_50700801_72_dialog_content = "Meskipun terbuat dari pita kotak dan bagian-bagian bekas, tetap cukup untuk memadamkan api.",
  ui_story_5070_50700801_73_dialog_content = "Kita sebut saja itu Naga Air!",
  ui_story_5070_50700801_74_dialog_content = "<color=#e8d9bb>Semprotan air yang kuat dari mulut naga dan asap putih bergulung-gulung di kabin, memadamkan kobaran api yang dahulu ganas di area yang luas.</color>",
  ui_story_5070_50700801_75_dialog_content = "Jangan hanya berdiri di sana. Ayo bergerak sekarang.",
  ui_story_5070_50700801_76_dialog_content = "Xuan Ji, kamu yang bertanggung jawab di sini.",
  ui_story_5070_50700801_77_dialog_content = "Aku tidak akan mengecewakanmu!",
  ui_story_5070_50700801_78_dialog_content = "Terlebih dengan PlayerName di sini juga... PlayerName?",
  ui_story_5070_50700801_79_dialog_content = "Merasa perasaan lucu.",
  ui_story_5070_50700801_80_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700801_81_dialog_content = "<color=#e8d9bb>Api yang sebelumnya mereda kembali membesar.</color>",
  ui_story_5070_50700801_82_dialog_content = "Tidak, ini tidak akan pernah berakhir.",
  ui_story_5070_50700801_83_dialog_content = "Saya akan menggunakan kemampuan psikis saya untuk menemukan sumber ledakan. Mungkin saya juga bisa menemukan solusinya.",
  ui_story_5070_50700801_84_dialog_content = "Force Boost!",
  ui_story_5070_50700801_85_dialog_content = "(Bukan di sini. Harus terus turun.)",
  ui_story_5070_50700801_86_dialog_content = "(Sumbernya adalah... Genggaman? Ada apa di sana...?)",
  ui_story_5070_50700801_87_dialog_content = "Woah!",
  ui_story_5070_50700801_88_dialog_content = "<size=45>Graaah!!</size>",
  ui_story_5070_50700801_89_dialog_content = "<color=#e8d9bb>Geladak di bawahnya terkena pukulan dari binatang mekanik, terbelah dan menunjukkan lautan api di bawahnya.</color>",
  ui_story_5070_50700801_90_dialog_content = "PlayerName!",
  ui_story_5070_50700801_91_dialog_content = "(Jatuh—!)",
  ui_story_5070_50700801_92_dialog_content = "Menjadi Abu!",
  ui_story_5070_50700801_93_dialog_content = "!",
  ui_story_5070_50700801_94_dialog_content = "Aduh... Punggungku benar-benar sakit. Tapi...",
  ui_story_5070_50700801_95_dialog_content = "Aku jelas jatuh tepat di tempat api bermula, tapi kenapa nyala apinya tidak sedikit pun panas?",
  ui_story_5070_50700801_96_dialog_content = "Teman muda, bagaimana cederamu?",
  ui_story_5070_50700801_97_dialog_content = "Zhong Xu?! Kenapa kamu mengikutiku ke sini?! Ini terlalu berbahaya. Apakah kamu baik-baik saja...?",
  ui_story_5070_50700801_98_dialog_content = "Untungnya, Ministress Armilla memodifikasi kursi roda saya. Masih baik-baik saja setelah mengalami benturan itu.",
  ui_story_5070_50700801_99_dialog_content = "Bukan itu pertanyaannya...",
  ui_story_5070_50700801_100_dialog_content = "Saya juga cukup ahli dalam Flame Force Arts dan dapat mengendalikan kebakaran liar di kapal ini.",
  ui_story_5070_50700801_101_dialog_content = "Kamu sama sekali tidak akan terbakar oleh api itu.",
  ui_story_5070_50700801_102_dialog_content = "Luar biasa! Bukankah ini berarti kamu bisa bergerak bebas di dalam api?",
  ui_story_5070_50700801_103_dialog_content = "Ngomong-ngomong, tempat ini dekat dengan gudang. Dengan kemampuan Zhong Xu, kita bahkan mungkin bisa langsung menangani sumber api ini!",
  ui_story_5070_50700801_104_dialog_content = "Tunggu dulu.",
  ui_story_5070_50700801_105_dialog_content = "Kamu punya kekuatan khusus, tapi kebugaran fisikmu kurang. Kamu harus pergi ke tempat yang aman dulu.",
  ui_story_5070_50700801_106_dialog_content = "Bagaimana bisa kesempatan yang begitu acak ini dilewatkan?",
  ui_story_5070_50700801_107_dialog_content = "Itu bukan tanggung jawabmu.",
  ui_story_5070_50700801_108_dialog_content = "Sebagai utusan dari negeri lain, Anda sangat penting dan harus mengutamakan keselamatan Anda sendiri. Tidak ada yang akan mengkritik Anda dengan keras karena melakukan itu.",
  ui_story_5070_50700801_109_dialog_content = "Tidak perlu menempatkan diri Anda dalam bahaya.",
  ui_story_5070_50700801_110_dialog_content = "Aku tahu kamu hanya khawatir untukku, tapi jika kamu selalu mengkhawatirkan hal-hal yang bahkan belum terjadi...",
  ui_story_5070_50700801_111_dialog_content = "Apakah kamu akan bisa menyelesaikan sesuatu nantinya?",
  ui_story_5070_50700801_112_dialog_content = "Juga, Zhong Xu yang baru saja melompat turun bersama saya mengatakan ini... Bukankah itu sedikit tidak meyakinkan?",
  ui_story_5070_50700801_113_dialog_content = "Zhong Xu tidak bertanggung jawab untuk menyelamatkan saya, bukan?",
  ui_story_5070_50700801_114_dialog_content = "...",
  ui_story_5070_50700801_115_dialog_content = "Hahaha, Anda membuat poin yang bagus.",
  ui_story_5070_50700801_116_dialog_content = "Saya tidak pernah menyangka bahwa saya akan mengingatkan orang lain untuk berhati-hati.",
  ui_story_5070_50700801_117_dialog_content = "Kamu sungguh orang yang luar biasa.",
  ui_story_5070_50700801_118_dialog_content = "Ayo pergi bersama.",
  ui_story_5070_50700801_119_dialog_content = "Aku akan mengonfirmasi lokasi sumber api itu.",
  ui_story_5070_50700801_120_dialog_content = "Force Boost!",
  ui_story_5070_50700801_121_dialog_content = "Tunggu, ada sesuatu yang aneh tentang sumber api ini. Dan...",
  ui_story_5070_50700801_122_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700801_123_dialog_content = "<size=45>Awas!</size>",
  ui_story_5070_50700801_124_dialog_content = "<color=#e8d9bb>Letusan api tiba-tiba melalap segalanya.</color>",
  ui_story_5070_50700802_1_dialog_content = "*Uhuk* *uhuk*... Asap di mana-mana.",
  ui_story_5070_50700802_2_dialog_content = "Aku hampir tidak bisa bernapas dan sulit untuk fokus... tapi aku yakin tadi aku merasakan ada seseorang di sini...",
  ui_story_5070_50700802_3_dialog_content = "...",
  ui_story_5070_50700802_4_dialog_content = "*Batuk* Siapa kamu...?",
  ui_story_5070_50700802_5_dialog_content = "<color=#e8d9bb>Sebuah cahaya putih aneh berkedip di tengah asap.</color>",
  ui_story_5070_50700802_6_dialog_content = "Teman muda!",
  ui_story_5070_50700802_7_dialog_content = "Zhong Xu... *batuk*...",
  ui_story_5070_50700802_8_dialog_content = "Ulurkan tanganmu!",
  ui_story_5070_50700802_9_dialog_content = "Tunggu, di sana...",
  ui_story_5070_50700802_10_dialog_content = "<color=#e8d9bb>Bola api meledak di depan.</color>",
  ui_story_5070_50700802_11_dialog_content = "Ayo keluar dulu dari sini.",
  ui_story_5070_50700802_12_dialog_content = "Bagaimana kabar PlayerName, Pak Zhong Xu? Apakah dia baik-baik saja?",
  ui_story_5070_50700802_13_dialog_content = "Hoi! Minggir! Semua kalian!",
  ui_story_5070_50700802_14_dialog_content = "Biarkan dokter lewat!",
  ui_story_5070_50700901_1_dialog_content = "Aduh...",
  ui_story_5070_50700901_2_dialog_content = "Meong!",
  ui_story_5070_50700901_3_dialog_content = "... Kenapa ada kucing di ranjangku?",
  ui_story_5070_50700901_4_dialog_content = "A-Apakah kamu kucing yang selalu ada di sekitar Dokter Liqing... Tinytail, 'kan?",
  ui_story_5070_50700901_5_dialog_content = "Meong!",
  ui_story_5070_50700901_6_dialog_content = "Sedang apa kau di sini?",
  ui_story_5070_50700901_7_dialog_content = "Oh ya, aku harus menanyakan tentang kebakaran kemarin... Apakah semua orang baik-baik saja?!",
  ui_story_5070_50700901_8_dialog_content = "Meong! Meong!",
  ui_story_5070_50700901_9_dialog_content = "Hei... Minggir, Tinytail. Itu berbahaya.",
  ui_story_5070_50700901_10_dialog_content = "Oh, aku baru saja pergi mengambil beberapa jamu dan kau sudah bangun?",
  ui_story_5070_50700901_11_dialog_content = "Berbaring sekarang juga.",
  ui_story_5070_50700901_12_dialog_content = "Meong...",
  ui_story_5070_50700901_13_dialog_content = "Bagus sekali, Tinytail!",
  ui_story_5070_50700901_14_dialog_content = "Aku tahu PlayerName akan menjadi pasien yang sulit seperti Zhong Xu.",
  ui_story_5070_50700901_15_dialog_content = "Apakah benar kamu yang menyuruh Tinytail menghalangi jalanku?",
  ui_story_5070_50700901_16_dialog_content = "Tentu saja, jangan meremehkan asap yang membuatmu tersedak itu.",
  ui_story_5070_50700901_17_dialog_content = "Kamu akan berada dalam masalah besar jika asap beracun masuk ke paru-parumu.",
  ui_story_5070_50700901_18_dialog_content = "Berbaring dan tunggu.",
  ui_story_5070_50700901_19_dialog_content = "4,5g fritillaria, 3g trichosanthes, dan masing-masing 2,4g serbuk sari, wolfiporia, jeruk mandarin, dan platycodon.",
  ui_story_5070_50700901_20_dialog_content = "Apa ini?",
  ui_story_5070_50700901_21_dialog_content = "Ini resep anti-inflamasi yang akan mendetoksifikasi paru-parumu.",
  ui_story_5070_50700901_22_dialog_content = "Jangan lupa tingkatkan asupan air, istirahat lebih banyak, dan hirup lebih banyak udara segar. Untuk makanan, makanlah yang ringan.",
  ui_story_5070_50700901_23_dialog_content = "Segera temui saya jika kamu mengalami batuk, dahak, atau dada sesak. Mengerti?",
  ui_story_5070_50700901_24_dialog_content = "Kenapa kau menatapku seperti itu?",
  ui_story_5070_50700901_25_dialog_content = "Liqing sepertinya cukup dapat diandalkan saat ini.",
  ui_story_5070_50700901_26_dialog_content = "Pada dasarnya, itu seperti... Bagaimana kalimatnya dalam bahasa Longzhou? Gaya dokter hebat!",
  ui_story_5070_50700901_27_dialog_content = "Serius?! Ehem... Maksudku, bukankah itu sudah diperkirakan?",
  ui_story_5070_50700901_28_dialog_content = "Baiklah, ini obatmu. Minumlah selagi masih panas.",
  ui_story_5070_50700901_29_dialog_content = "Tss... R-rasa yang cukup kompleks.",
  ui_story_5070_50700901_30_dialog_content = "Guru Bu berkata, \"Obat yang baik itu pahit. Itulah harga yang harus dibayar untuk kesembuhan.\"",
  ui_story_5070_50700901_31_dialog_content = "... Apakah benar-benar seburuk itu?",
  ui_story_5070_50700901_32_dialog_content = "Bukan tidak enak, ini hanya pertama kalinya aku mencicipi sesuatu yang memiliki lapisan rasa seperti ini...",
  ui_story_5070_50700901_33_dialog_content = "Aku tidak benar-benar terbiasa dengannya",
  ui_story_5070_50700901_34_dialog_content = "Apa yang harus aku lakukan dengan kalian anak-anak muda?",
  ui_story_5070_50700901_35_dialog_content = "Nih, ambil buah kering ini. Ini akan membantu setelah kamu minum obat.",
  ui_story_5070_50700901_36_dialog_content = "Tapi kamu hanya akan mendapatkan yang ini. Saya hanya berhasil menyembunyikan satu tas saat naik ke kapal.",
  ui_story_5070_50700901_37_dialog_content = "Terima kasih, Liqing. Itu sangat perhatian dari Anda.",
  ui_story_5070_50700901_38_dialog_content = "Tidak bisa dihindari, saya memang seorang dokter hebat!",
  ui_story_5070_50700901_39_dialog_content = "Selamat beristirahat. Saya harus menemui yang lainnya.",
  ui_story_5070_50700901_40_dialog_content = "Ada orang lain yang terluka?",
  ui_story_5070_50700901_41_dialog_content = "Tetap istirahat. Kondisimu kemarin paling parah, jadi lupakan dulu tentang orang lain!",
  ui_story_5070_50700901_42_dialog_content = "Jangan khawatir, itu akan baik-baik saja.",
  ui_story_5070_50700901_43_dialog_content = "Aku harus memberikan obat pendingin dan detoksifikasi kepada semua orang sebagai langkah pencegahan.",
  ui_story_5070_50700901_44_dialog_content = "Membahas tentang yang lain...",
  ui_story_5070_50700901_45_dialog_content = "Banyak yang datang berkunjung saat kamu tidur. Sekarang kamu sudah bangun, aku bisa memanggil mereka semua ke sini.",
  ui_story_5070_50700901_46_dialog_content = "Tidak, tidak, tidak. Aku tahu semua orang baik-baik saja, jadi tidak perlu khawatir...",
  ui_story_5070_50700901_47_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5070_50700901_48_dialog_content = "Tidak perlu formalitas!",
  ui_story_5070_50700901_49_dialog_content = "*Kaget*",
  ui_story_5070_50700901_50_dialog_content = "Dantang?",
  ui_story_5070_50700901_51_dialog_content = "Lady Xuan Ji, tolong jangan mendorong Yang Mulia seperti itu.",
  ui_story_5070_50700901_52_dialog_content = "Apakah kamu terlalu pelindung, Jiu? Tenang saja, Yang Mulia itu berharga, tapi tidak rapuh juga.",
  ui_story_5070_50700901_53_dialog_content = "Xuan Ji? Jiu? Kenapa kalian semua di sini?",
  ui_story_5070_50700901_54_dialog_content = "Untuk melihat pahlawan kemarin, tentu saja.",
  ui_story_5070_50700901_55_dialog_content = "Senang rasanya kamu tidak terluka parah, kalau tidak aku tidak tahu bagaimana cara menebusnya.",
  ui_story_5070_50700901_56_dialog_content = "Tidak ada alasan bagi kamu untuk meminta maaf. Tidak ada yang akan menyangka aku akan salah pada saat itu.",
  ui_story_5070_50700901_57_dialog_content = "Dan semuanya baik-baik saja, yang membuktikan bahwa alat ciptaanmu berhasil memadamkan api...",
  ui_story_5070_50700901_58_dialog_content = "Nah, kamu cukup sehat untuk bicara panjang lebar, jadi pasti baik-baik saja.",
  ui_story_5070_50700901_59_dialog_content = "Jadi, bagaimana rasanya melihat PlayerName yang sedang pulih dengan mata kepala sendiri, Tuan Putri Dantang?",
  ui_story_5070_50700901_60_dialog_content = "Jauh lebih baik daripada mengintip, bukan?",
  ui_story_5070_50700901_61_dialog_content = "Kamu pasti salah mengira orang lain sebagai saya, Menteri Armilla.",
  ui_story_5070_50700901_62_dialog_content = "Menjadi tugas saya untuk peduli tentang kesehatan utusan penting seperti PlayerName.",
  ui_story_5070_50700901_63_dialog_content = "Saya tidak perlu, seperti yang Anda katakan, mengintip.",
  ui_story_5070_50700901_64_dialog_content = "Ya, ya, aku percaya asap dari kemarin masih mengganggu mataku.",
  ui_story_5070_50700901_65_dialog_content = "Baiklah, Tuan Putri Dantang, aku akan meninggalkanmu untuk menjalankan tugas. Teruslah perhatikan PlayerName!",
  ui_story_5070_50700901_66_dialog_content = "Aku…",
  ui_story_5070_50700901_67_dialog_content = "Tidak apa-apa, Dantang. Aku dalam kondisi sehat sekarang, dan tidak ada yang perlu dikhawatirkan.",
  ui_story_5070_50700901_68_dialog_content = "Tidak ada yang menggangguku juga, um... Kecuali bau obat itu. Sungguh luar biasa...",
  ui_story_5070_50700901_69_dialog_content = "Obat? Aku punya solusi untuk itu.",
  ui_story_5070_50700901_70_dialog_content = "Ketika Anda sudah keluar dari bahaya yang segera, penyembuhan melalui makanan adalah pilihan yang lebih unggul.",
  ui_story_5070_50700901_71_dialog_content = "Mengingat Liqing juga ada, saya ingin menyiapkan hidangan obat yang lezat untuk semua orang. Bagaimana menurut Anda tentang ide ini?",
  ui_story_5070_50700901_72_dialog_content = "Membuatnya lezat?! Tidak masalah!",
  ui_story_5070_50700901_73_dialog_content = "Saya tahu resep untuk banyak tonik, dan bahkan saya sengaja membeli bahan-bahan khusus untuk pelayaran ini.",
  ui_story_5070_50700901_74_dialog_content = "Akar teratai mendukung kesehatan, melon dingin menutrisi kulit, wolfiporia merawat pikiran...",
  ui_story_5070_50700901_75_dialog_content = "Aku bisa membuat banyak hal!",
  ui_story_5070_50700901_76_dialog_content = "...",
  ui_story_5070_50700901_77_dialog_content = "Xuan Ji tidak datang untuk makan sesuatu...? Xuan Ji?",
  ui_story_5070_50700901_78_dialog_content = "Ya? Ada yang bisa saya bantu?",
  ui_story_5070_50700901_79_dialog_content = "Tidak. Kamu tampak sedikit terganggu dan tidak mengatakan apa-apa cukup lama.",
  ui_story_5070_50700901_80_dialog_content = "Apakah itu begitu jelas?",
  ui_story_5070_50700901_81_dialog_content = "Kurasa aku masih harus berlatih menjaga ketenangan. Catatan untuk diri sendiri: Buatlah topeng yang dapat membantu menjaga ekspresi wajah yang diinginkan.",
  ui_story_5070_50700901_82_dialog_content = "Sebenarnya, aku sedang memikirkan tentang semalam.",
  ui_story_5070_50700901_83_dialog_content = "Ketika Pak Zhong Xu mengeluarkan Anda dari asap...",
  ui_story_5070_50700901_84_dialog_content = "Kamu terus menggumamkan tentang kebakaran dan angka-angka.",
  ui_story_5070_50700901_85_dialog_content = "Apa yang tadi kaulihat?",
  ui_story_5070_50700901_86_dialog_content = "Bukan benar-benar melihat, lebih seperti merasakan.",
  ui_story_5070_50700901_87_dialog_content = "Sepertinya ada sesuatu yang sangat aneh di ruang penyimpanan, seperti api, tetapi saya tidak merasakan panas yang seharusnya diberikan oleh nyala api.",
  ui_story_5070_50700901_88_dialog_content = "Tidak ada panas, tetapi tetap terlihat lebih besar daripada semua nyala api di sekitarnya.",
  ui_story_5070_50700901_89_dialog_content = "Rasanya seperti... Sebuah matahari mini.",
  ui_story_5070_50700901_90_dialog_content = "... Aku tahu deskripsiku sedikit aneh.",
  ui_story_5070_50700901_91_dialog_content = "Bagaimanapun, saya menduga bahwa sambaran petir hanyalah katalis, dan benda ini adalah penyebab sebenarnya dari kebakaran itu.",
  ui_story_5070_50700901_92_dialog_content = "Mengenai sosok itu, saya tidak melihatnya dengan cukup jelas, tapi ia tetap berada di dekat ruang penyimpanan sepanjang waktu...",
  ui_story_5070_50700901_93_dialog_content = "Semuanya sedikit aneh.",
  ui_story_5070_50700901_94_dialog_content = "Aku paham.",
  ui_story_5070_50700901_95_dialog_content = "Tapi mari kendalikan keinginan itu untuk lain kali, PlayerName.",
  ui_story_5070_50700901_96_dialog_content = "Berhenti memindai pikiran apa pun yang tidak biasa yang kamu temukan...",
  ui_story_5070_50700901_97_dialog_content = "Aku tidak bisa selalu menolongmu dari bahaya meskipun aku ingin melakukannya.",
  ui_story_5070_50700901_98_dialog_content = "Maaf... Aku akan memperhatikan.",
  ui_story_5070_50700901_99_dialog_content = "Yah, harus lari sekarang.",
  ui_story_5070_50700901_100_dialog_content = "Tunggu.",
  ui_story_5070_50700901_101_dialog_content = "Apakah ada hal buruk lain yang terjadi saat aku tidur?",
  ui_story_5070_50700901_102_dialog_content = "...",
  ui_story_5070_50700901_103_dialog_content = "Yah, kurasa aku benar-benar harus menjadikan topeng ekspresi ini sebagai agenda.",
  ui_story_5070_50700901_104_dialog_content = "Mengasumsikan saya berhasil kembali ke bengkel saya di Longzhou.",
  ui_story_5070_50700901_105_dialog_content = "Ada yang salah dengan pelayaran ini?",
  ui_story_5070_50700901_106_dialog_content = "Ada pepatah dalam pelayaran:",
  ui_story_5070_50700901_X106_dialog_content = "\"Berlayar dengan bintang di malam hari, matahari di siang hari, kegelapan dengan kompas, dan segera tinggalkan area tersebut jika semuanya tidak berhasil.\"",
  ui_story_5070_50700901_107_dialog_content = "Mengamati bintang dan matahari? Apakah Anda maksud menentukan arah kapal dengan bintang, seperti sebelum Xuan Ji?",
  ui_story_5070_50700901_108_dialog_content = "Benar. Jika tidak ada bintang atau bulan, Anda masih memiliki kompas untuk menentukan arah.",
  ui_story_5070_50700901_109_dialog_content = "Tapi jika bahkan instrumen pun gagal, kamu tidak akan tahu ke mana kamu akan pergi.",
  ui_story_5070_50700901_110_dialog_content = "Jika kamu tidak segera keluar, kamu akan tersesat di laut.",
  ui_story_5070_50700901_111_dialog_content = "Mengikuti keributan tadi malam, saya mencoba segala cara untuk menentukan arah kita di tengah badai.",
  ui_story_5070_50700901_112_dialog_content = "...Tidak ada yang efektif?",
  ui_story_5070_50700901_113_dialog_content = "<color=#e8d9bb>Xuan Ji mengangguk sedikit.</color>",
  ui_story_5070_50700901_114_dialog_content = "Tak ada yang berhasil, bahkan hingga sekarang.",
  ui_story_5070_50700901_115_dialog_content = "Hal itu tidak akan terjadi pada Shadowind dalam pelayaran normal.",
  ui_story_5070_50700901_116_dialog_content = "Tapi kita berada sangat jauh dan tanpa bagan yang lengkap, sehingga kita bahkan tidak bisa mengandalkan matahari meskipun ia muncul.",
  ui_story_5070_50700901_117_dialog_content = "Jadi, aku cukup yakin pada saat ini...",
  ui_story_5070_50700901_118_dialog_content = "Shadowind keluar dari jalur.",
  ui_story_5070_50700902_1_dialog_content = "Kita tersesat dan masih harus berurusan dengan Eclipsites... Perjalanan ini sangat penuh kejadian.",
  ui_story_5070_50700902_2_dialog_content = "Kita harus segera menentukan arah kita.",
  ui_story_5070_50700902_3_dialog_content = "Aku mengerti alasannya, tapi apa hubungannya dengan memindahkan Perangkap Naga Air?",
  ui_story_5070_50700902_4_dialog_content = "Kami memberikan tujuan untuk setiap perangkat yang kami buat, tetapi itu tidak berarti itu adalah satu-satunya hal yang mereka bisa lakukan.",
  ui_story_5070_50700902_5_dialog_content = "<color=#e8d9bb>Dengan gemuruh yang keras, air laut dipompa ke dalam tong kayu yang telah disiapkan melalui pipa-pipa kuningan.</color>",
  ui_story_5070_50700902_6_dialog_content = "Lihat, selain air laut, kita juga menangkap banyak ikan dan udang.",
  ui_story_5070_50700902_7_dialog_content = "Laut mungkin luas, tetapi memiliki berbagai makhluk yang hidup di bagian yang berbeda.",
  ui_story_5070_50700902_8_dialog_content = "Jadi jika kita bisa menangkap beberapa kehidupan laut yang ikonik di daerah itu...",
  ui_story_5070_50700902_9_dialog_content = "Kita harus mendapatkan petunjuk yang didasarkan pada pengetahuan untuk mengetahui secara kasar di mana kita berada dengan membandingkannya dengan gambar-gambar dalam buku panduan.",
  ui_story_5070_50700902_10_dialog_content = "Jadi, sudut ini pun bisa dipertimbangkan.",
  ui_story_5070_50700902_11_dialog_content = "Dapat ikan spesial?",
  ui_story_5070_50700902_12_dialog_content = "Sayangnya, makhluk-makhluk biasa itu hanya cocok untuk dijadikan bahan makanan obat yang diinginkan sang putri.",
  ui_story_5070_50700902_13_dialog_content = "Namun, perlu dicatat bahwa ada risiko yang terlibat dalam hal ini.",
  ui_story_5070_50700902_14_dialog_content = "Para pelaut menangkap ikan untuk kita setiap hari, jadi apa risikonya?",
  ui_story_5070_50700902_15_dialog_content = "Sebenarnya, saya hanya menyebutkan setengahnya saja.",
  ui_story_5070_50700902_16_dialog_content = "Meskipun gadget dapat diadaptasi untuk banyak hal, mereka tidak dirancang untuk itu.",
  ui_story_5070_50700902_17_dialog_content = "Jadi, ada kemungkinan sesuatu yang tak terduga bisa terjadi...",
  ui_story_5070_50700902_18_dialog_content = "Ambil contoh Fire Crab, sangat bagus untuk pengelasan.",
  ui_story_5070_50700902_19_dialog_content = "Tapi sangat buruk untuk memanggang daging.",
  ui_story_5070_50700902_20_dialog_content = "Apa kamu tahu betapa tidak enaknya rasa daging yang terbakar arang?",
  ui_story_5070_50700902_21_dialog_content = "Lebih baik aku tidak tahu. Selamanya.",
  ui_story_5070_50700902_22_dialog_content = "Dan kapan tepatnya Anda akan menggunakan kepiting api untuk memasak?",
  ui_story_5070_50700902_23_dialog_content = "Sangat mirip dengan menggunakan pompa untuk menangkap ikan saat ini.",
  ui_story_5070_50700902_24_dialog_content = "Ini adalah darurat yang sangat kritis.",
  ui_story_5070_50700902_25_dialog_content = "Meskipun saya tidak terlalu familiar dengan pepatah Longzhou.",
  ui_story_5070_50700902_26_dialog_content = "Tapi ada perasaan bahwa memanggang dengan kepiting api tidak cocok dengan kata-kata itu.",
  ui_story_5070_50700902_27_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_28_dialog_content = "Apa yang kapal itu pukul?",
  ui_story_5070_50700902_29_dialog_content = "Matikan Naga Air.",
  ui_story_5070_50700902_30_dialog_content = "Aksi pemompaan ini begitu intens, mungkin telah menarik sesuatu yang sangat besar di lautan.",
  ui_story_5070_50700902_31_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_32_dialog_content = "Kapal ini miring! Semuanya, pegang sesuatu dan berpegangan erat!",
  ui_story_5070_50700902_33_dialog_content = "Aku... Aku berhasil.",
  ui_story_5070_50700902_34_dialog_content = "Akhirnya aku datang ke geladak untuk menghirup udara segar, dan aku harus menabrak sesuatu seperti ini!",
  ui_story_5070_50700902_35_dialog_content = "Terima kasih Tuhan saya tidak menyimpang dari pagar sapi. Jangan bilang bahwa ramalan itu benar-benar... Aduh!",
  ui_story_5070_50700902_36_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_37_dialog_content = "Kemiringan semakin parah. Kita tidak bisa melakukan apa-apa seperti ini.",
  ui_story_5070_50700902_38_dialog_content = "Semuanya, pindah ke sisi lain! Kita harus menyeimbangkan kapal!",
  ui_story_5070_50700902_39_dialog_content = "Aku akan menggunakan Kepiting Api untuk mendorong pembakar Shadowind. Tahan saja dan kita akan segera meningkat kecepatannya.",
  ui_story_5070_50700902_40_dialog_content = "Sukses! Bayangan di laut telah ditinggalkan.",
  ui_story_5070_50700902_41_dialog_content = "Saya sering diserang oleh kepiting api, jadi aneh rasanya diselamatkan oleh mereka kali ini.",
  ui_story_5070_50700902_42_dialog_content = "Apa yang sudah kukatakan? Sebuah gadget sebaik atau sejahat orang yang mengoperasikannya.",
  ui_story_5070_50700902_43_dialog_content = "Terserah pengguna untuk menggunakannya untuk menyelamatkan nyawa atau mengakhirinya.",
  ui_story_5070_50700902_44_dialog_content = "Mungkin aku harus mengubah pikiran tentang \"kepiting besar yang menakutkan\" itu...",
  ui_story_5070_50700902_45_dialog_content = "Ini adalah pertama kalinya Shadowind bergerak dengan kecepatan seperti ini. Apakah bisa bertahan?",
  ui_story_5070_50700902_46_dialog_content = "Hanya dalam mimpimu.",
  ui_story_5070_50700902_47_dialog_content = "Kita mendapatkan kekuatan yang kita miliki sekarang semua karena Flame Force di dalam Kepiting Api.",
  ui_story_5070_50700902_48_dialog_content = "Ini akan cepat habis jika kita tidak segera mengisinya, jadi...",
  ui_story_5070_50700902_49_dialog_content = "Lady Xuan Ji! Orang di dekat ketel itu bilang bahwa semua kepiting api tidak bergerak lagi!",
  ui_story_5070_50700902_50_dialog_content = "Seperti barusan?",
  ui_story_5070_50700902_51_dialog_content = "Yah, dia mati lebih cepat dari yang saya perkirakan.",
  ui_story_5070_50700902_52_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_53_dialog_content = "Force Boost!",
  ui_story_5070_50700902_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_55_dialog_content = "Berhasil, tidak?",
  ui_story_5070_50700902_56_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_57_dialog_content = "Tolong, berhenti. Kami bukan makanan, dan bukan mainan!",
  ui_story_5070_50700902_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_59_dialog_content = "Tidak. Aku hanya bisa menghentikannya untuk sementara waktu. Kita masih akan dikejar kecuali jika Shadowind meningkatkan jaraknya.",
  ui_story_5070_50700902_60_dialog_content = "Dan yang kurasakan dari tubuhnya di bawah air jauh lebih besar daripada bayangan di permukaan...",
  ui_story_5070_50700902_61_dialog_content = "Tepatnya, seberapa lebih besar itu?",
  ui_story_5070_50700902_62_dialog_content = "Apa?",
  ui_story_5070_50700902_63_dialog_content = "Kita bisa mengukur siluet di dalam air.",
  ui_story_5070_50700902_X63_dialog_content = "Kemudian hitung ukurannya berdasarkan Mindlink-mu, PlayerName.",
  ui_story_5070_50700902_64_dialog_content = "Akhirnya, tentukan jangkauan ancamannya berdasarkan berat Shadowind dan sudut kemiringan dari dampak...",
  ui_story_5070_50700902_65_dialog_content = "Aku tahu apa yang ada di bawah air!",
  ui_story_5070_50700902_66_dialog_content = "Bisakah kamu menahannya sebentar, PlayerName? Aku harus mengambil sesuatu dari kabin yang mungkin bisa mengalihkan perhatiannya.",
  ui_story_5070_50700902_67_dialog_content = "Oke. Serahkan padaku.",
  ui_story_5070_50700902_68_dialog_content = "Force Boost!",
  ui_story_5070_50700902_69_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_70_dialog_content = "Force Boost!",
  ui_story_5070_50700902_71_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_72_dialog_content = "(Tss... Berapa kali sih?? Ini pasti bercanda. Dan bukankah Xuan Ji lebih baik?)",
  ui_story_5070_50700902_73_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50700902_74_dialog_content = "Dorong Paksa...!",
  ui_story_5070_50700902_75_dialog_content = "Saya kembali, PlayerName!",
  ui_story_5070_50700902_76_dialog_content = "Brilian—",
  ui_story_5070_50700902_77_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5070_50700902_78_dialog_content = "(Terjadi benturan paling keras sejauh ini, dan tubuh saya terlempar ke udara.)",
  ui_story_5070_50700902_79_dialog_content = "Ambilkan payung besarku!",
  ui_story_5070_50700902_80_dialog_content = "(Tidak! Aku tidak akan bisa mengalihkan perhatian monster laut sekarang...!)",
  ui_story_5070_50700902_81_dialog_content = "Xuan Ji! Berikan aku yang sedang kamu pegang!",
  ui_story_5070_50700902_82_dialog_content = "?!",
  ui_story_5070_50700902_83_dialog_content = "Apa jenis pemberani yang kamu miliki... Baiklah, ini dia!",
  ui_story_5070_50700902_84_dialog_content = "(Satu keuntungan berada di udara adalah kamu bisa melempar lebih jauh!)",
  ui_story_5070_50700902_85_dialog_content = "Berhenti mengejar! Ini adalah mainan yang lebih cocok untukmu!",
  ui_story_5070_50700902_86_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5070_50700902_87_dialog_content = "<color=#e8d9bb>Batu yang diambil dari Xuan Ji jatuh ke laut.</color>",
  ui_story_5070_50700902_88_dialog_content = "(Saya merasakan monster laut berbalik, dan melihat Xuan Ji membuka payung untuk mencoba menangkap saya.)",
  ui_story_5070_50700902_89_dialog_content = "(Tidak ada waktu, tapi tidak masalah karena... Orang itu masih di bawah sana!)",
  ui_story_5070_50700902_90_dialog_content = "Menjadi Abu!",
  ui_story_5070_50700902_91_dialog_content = "<color=#e8d9bb>Dengan kobaran api merah menyala ke langit dan mesin bergema dengan dengungan kecepatan penuh, Shadowind kembali mengakselerasi.</color>",
  ui_story_5070_50700902_92_dialog_content = "(Aku terjatuh ke dalam nyala api yang tenang dan damai.)",
  ui_story_5070_50700902_93_dialog_content = "Fiuh, kali ini, kita berhasil kehilangan monster laut untuk selamanya. Akhirnya selesai juga...",
  ui_story_5070_50700902_94_dialog_content = "Teman muda.",
  ui_story_5070_50700902_95_dialog_content = "Sungguh kagum dengan keberanianmu yang luar biasa.",
  ui_story_5070_50700902_96_dialog_content = "Tapi, tidakkah kamu pikir itu terlalu ceroboh untuk membahayakan diri sendiri seperti itu?",
  ui_story_5070_50700902_97_dialog_content = "(A-Apa nada yang serius!)",
  ui_story_5070_50700902_98_dialog_content = "Aku... Maaf membuat semua orang khawatir. Namun, sebenarnya aku cukup yakin.",
  ui_story_5070_50700902_99_dialog_content = "Karena aku melihat Zhong Xu di sini.",
  ui_story_5070_50700902_100_dialog_content = "Terima kasih banyak.",
  ui_story_5070_50700902_101_dialog_content = "... Tidak apa-apa. Anda seharusnya berterima kasih pada Menteri Armilla daripada saya.",
  ui_story_5070_50700902_102_dialog_content = "Tanpa modifikasi yang dia lakukan pada kursi roda saya, saya tidak akan bisa bergerak dengan bebas di kapal yang tidak stabil ini.",
  ui_story_5070_50700902_103_dialog_content = "PlayerName!",
  ui_story_5070_50700902_104_dialog_content = "Aku tahu kamu beruntung! Kamu bisa mencapai apa saja asalkan kamu mencoba.",
  ui_story_5070_50700902_105_dialog_content = "Haha, terima kasih sudah percaya padaku. Tapi, bagaimana mungkin seonggok batu bisa memikat monster laut?",
  ui_story_5070_50700902_106_dialog_content = "Karena itu bukan batu biasa, melainkan batu bersinar, semakin gelap di sekitarnya, semakin terang batu itu.",
  ui_story_5070_50700902_107_dialog_content = "Tidak banyak yang ditulis tentang monster itu, kecuali bahwa mereka tinggal di laut dalam.",
  ui_story_5070_50700902_108_dialog_content = "Dan makhluk seperti itu selalu tertarik pada cahaya.",
  ui_story_5070_50700902_109_dialog_content = "Jadi, saya pikir itu akan menjadi umpan yang sangat baik.",
  ui_story_5070_50700902_110_dialog_content = "Untungnya, itu berhasil.",
  ui_story_5070_50700902_111_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5070_50700902_112_dialog_content = "Kami baik-baik saja, selain hampir jadi santapan monster beberapa detik lagi.",
  ui_story_5070_50700902_113_dialog_content = "Berlayar di lautan sangatlah sulit...",
  ui_story_5070_50700902_114_dialog_content = "Beruntung hal-hal seperti ini tidak ada di langit, jika tidak Soroz dan saya juga akan dalam bahaya.",
  ui_story_5070_50700902_115_dialog_content = "Yah, setelah pertemuan mengerikan itu, kita seharusnya aman untuk sementara waktu.",
  ui_story_5070_50700902_116_dialog_content = "Lagi pula, sangat jarang menemui raksasa seperti itu di laut.",
  ui_story_5070_50700902_117_dialog_content = "Setidaknya, kita tak perlu khawatir akan serangan lain hingga kita meninggalkan wilayahnya.",
  ui_story_5070_50700902_118_dialog_content = "Jadi, apakah kamu mengatakan bahwa kita sekarang bisa menggunakan sebanyak mungkin Jebakan Naga Air yang kita inginkan?",
  ui_story_5070_50700902_119_dialog_content = "Sampai maksimal, bahkan.",
  ui_story_5070_50700902_120_dialog_content = "Panggil semua orang yang tidak sibuk ke sini. Mari kita manfaatkan kesempatan ini untuk bekerja sama sebaik mungkin dan menangkap lebih banyak ikan.",
  ui_story_5070_50700902_121_dialog_content = "Kami telah berlayar cukup lama, dan saatnya untuk mengisi kembali persediaan makanan di Shadowind.",
  ui_story_5070_50700902_122_dialog_content = "Oke... oke, segera datang.",
  ui_story_5070_50700902_123_dialog_content = "Ups.",
  ui_story_5070_50700902_124_dialog_content = "Maaf, aku tidak bermaksud menabrakmu...",
  ui_story_5070_50700902_125_dialog_content = "Sun yang Cakap? Tak apa-apa, aku juga tidak melihatmu tiba.",
  ui_story_5070_50700902_126_dialog_content = "Apa yang kamu pegang? Baunya enak.",
  ui_story_5070_50700902_127_dialog_content = "Ini umpan. Kapten menyuruh kita menangkap ikan.",
  ui_story_5070_50700902_128_dialog_content = "Dengan aroma yang lezat seperti itu, pasti mudah untuk menangkap ikan besar.",
  ui_story_5070_50700902_129_dialog_content = "... Di mana dia?",
  ui_story_5070_50700902_130_dialog_content = "Kapten! Ayo lihat apa yang berhasil kita tangkap!",
  ui_story_5070_50700902_131_dialog_content = "Kamu sedang apa, PlayerName?",
  ui_story_5070_50700902_132_dialog_content = "Baru saja... Sun yang Terampil?",
  ui_story_5070_50700902_133_dialog_content = "...",
  ui_story_5070_50700902_134_dialog_content = "Tidak apa-apa, lupakan saja.",
  ui_story_5070_50700902_135_dialog_content = "<size=25>Selama umpan masih ada, ikan akan datang ke atas tidak peduli seberapa dalam ia berenang.</size>",
  ui_story_5070_50700902_136_dialog_content = "Apa katamu?",
  ui_story_5070_50700902_137_dialog_content = "Tidak ada apa-apa! Ayo, kita lihat pesta di sana.",
  ui_story_5070_50700902_138_dialog_content = "Baiklah... Eh? Bagaimana bisa kamu mengumpulkan begitu banyak kayu?",
  ui_story_5070_50700902_139_dialog_content = "Ini adalah puing-puing kapal yang tenggelam.",
  ui_story_5070_50700902_140_dialog_content = "Namun, jenis kayu, cat, dan tingkat korosi semuanya berbeda. Jelas bahwa mereka berasal dari kapal yang berbeda.",
  ui_story_5070_50700902_141_dialog_content = "Aku khawatir ada konsentrasi kapal karam di sekitar sini.",
  ui_story_5070_50700902_142_dialog_content = "Ini bahkan bisa jadi kuburan kapal.",
  ui_story_5070_50701001_1_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5070_50701001_2_dialog_content = "Yuebai?!",
  ui_story_5070_50701001_3_dialog_content = "Yuebai baru saja melompat langsung ke laut dengan kepala terlebih dahulu?!",
  ui_story_5070_50701001_4_dialog_content = "Jangan khawatir. Yuebai lebih kuat berenang daripada semua orang di kapal ini digabungkan.",
  ui_story_5070_50701001_5_dialog_content = "Kita sebagai penumpang, harus percaya pada kapten, jadi tunggu dan lihat saja.",
  ui_story_5070_50701001_6_dialog_content = "(Ada banyak jenis bahaya di laut. Batu, pusaran air, binatang laut buas...)",
  ui_story_5070_50701001_7_dialog_content = "(Tetapi mereka semua memiliki satu kesamaan. Mereka semua bertanggung jawab atas penghancuran banyak kapal di berbagai perairan.)",
  ui_story_5070_50701001_8_dialog_content = "(Setelah sebuah kapal tenggelam, reruntuhannya akan didorong oleh arus laut dan berakhir di tempat yang sama di bawah air, membentuk kuburan kapal.)",
  ui_story_5070_50701001_9_dialog_content = "(Ini tempatnya?)",
  ui_story_5070_50701001_10_dialog_content = "(Saya tidak pernah berpikir bahwa suatu hari nanti saya akan mengemudikan kapal ke kuburan seperti ini.)",
  ui_story_5070_50701001_11_dialog_content = "(Rangka kapal yang rusak bertumpuk dalam tumpukan, perlahan-lahan tertutup karang dan rumput laut, terkikis, dan membusuk.",
  ui_story_5070_50701001_12_dialog_content = "(Seolah-olah laut mengadakan upacara pemakaman untuk mengantar kapal-kapal ini.)",
  ui_story_5070_50701001_13_dialog_content = "(... Kapal itu!)",
  ui_story_5070_50701001_14_dialog_content = "Sebentar lagi, Ministress Armilla, teman muda, bisakah kamu menyelamatkan lebih banyak fragmen kapal ini untukku?",
  ui_story_5070_50701001_15_dialog_content = "Fragmen-fragmen ini terlihat sedikit familiar bagi saya.",
  ui_story_5070_50701001_16_dialog_content = "Sejauh yang bisa saya lihat, tidak ada perbedaan sama sekali antara potongan kayu ini.",
  ui_story_5070_50701001_17_dialog_content = "Apapun bisa memberi tahu Anda sesuatu jika Anda melihatnya cukup dekat.",
  ui_story_5070_50701001_18_dialog_content = "Mungkin aku tidak sehebat Zhong Xu, tapi aku masih bisa mendapatkan banyak hal darinya.",
  ui_story_5070_50701001_19_dialog_content = "Lihat, potongan ini memiliki nama kapalnya di atasnya.",
  ui_story_5070_50701001_20_dialog_content = "Dan yang ini memiliki Lubang Keberuntungan.",
  ui_story_5070_50701001_21_dialog_content = "Ini bukan hanya celah yang rusak?",
  ui_story_5070_50701001_22_dialog_content = "Tidak, ini dibor secara sengaja.",
  ui_story_5070_50701001_23_dialog_content = "Untuk menyimpan jimat keberuntungan seperti koin atau cermin di dalamnya.",
  ui_story_5070_50701001_24_dialog_content = "Ini dimaksudkan untuk memastikan pelayaran yang lancar.",
  ui_story_5070_50701001_25_dialog_content = "Namun karena ditemukan dalam kapal karam, kemungkinan besar kru dan penumpang sudah tiada... Begitu tak menentu nasibnya.",
  ui_story_5070_50701001_26_dialog_content = "Semakin banyak puing yang diangkat, semakin aku merasa tempat ini benar-benar berbahaya...",
  ui_story_5070_50701001_27_dialog_content = "Untuk apa ekspresi itu, Zhong Xu...? Apa yang kamu lihat?",
  ui_story_5070_50701001_28_dialog_content = "Salah satu kapal ini milik bajak laut.",
  ui_story_5070_50701001_29_dialog_content = "Bajak laut?!",
  ui_story_5070_50701001_30_dialog_content = "Saya pernah banyak berurusan dengan mereka, jadi saya percaya saya benar.",
  ui_story_5070_50701001_31_dialog_content = "Namun, bajak laut berkeliaran di laut sepanjang tahun dan jauh lebih waspada terhadap perairan berbahaya daripada orang biasa.",
  ui_story_5070_50701001_32_dialog_content = "Saya ingin tahu apakah mereka terbawa ke sini oleh angin atau dikejar oleh sesuatu.",
  ui_story_5070_50701001_33_dialog_content = "Itu terdengar agak menakutkan... Kami sudah merasakan tekanan dari Eclipsites, badai, dan monster laut!",
  ui_story_5070_50701001_34_dialog_content = "Dan sekarang kita perlu khawatir tentang apa yang menghancurkan kapal bajak laut itu, dan apakah itu ancaman bagi kita?!",
  ui_story_5070_50701001_35_dialog_content = "<color=#e8d9bb>Byur...</color>",
  ui_story_5070_50701001_36_dialog_content = "Ini Yuebai! Dia muncul!",
  ui_story_5070_50701001_37_dialog_content = "Aku tahu di mana ini.",
  ui_story_5070_50701001_38_dialog_content = "Di bawah kita adalah kapal nelayan laut yang karam beberapa tahun yang lalu.",
  ui_story_5070_50701001_39_dialog_content = "Berdasarkan rute yang seharusnya diambil, ini seharusnya merupakan persimpangan antara perairan laut dan Longzhou.",
  ui_story_5070_50701001_40_dialog_content = "Jadi, bukankah itu berarti...",
  ui_story_5070_50701001_41_dialog_content = "Ya, itu berarti kita tidak jauh dari Longzhou.",
  ui_story_5070_50701001_42_dialog_content = "Baiklah!",
  ui_story_5070_50701001_43_dialog_content = "Terlalu dini untuk bersantai.",
  ui_story_5070_50701001_44_dialog_content = "Tempat ini terkenal sebagai tempat maut di laut. Tidak ada peta laut yang sesuai untuk perairan ini, dan bukan merupakan bagian dari rute yang telah ditetapkan oleh Shadowind.",
  ui_story_5070_50701001_45_dialog_content = "Bahkan jika kita tahu lokasi perkiraannya, kita tidak akan bisa menentukan arah mana yang harus kita layari.",
  ui_story_5070_50701001_46_dialog_content = "Kita juga hampir kehabisan makanan, jadi kita tidak bisa buang-buang waktu.",
  ui_story_5070_50701001_47_dialog_content = "Bisakah kamu minta Zhong Xu dan Xuan Ji untuk mengatur mesin agar berjalan dengan kecepatan penuh, dan kita bisa keluar dari sini?",
  ui_story_5070_50701001_48_dialog_content = "Tidak. Ada banyak pusaran air di sekitar sini. Satu kesalahan dan kita bisa berakhir beristirahat di kuburan kapal di dasar laut.",
  ui_story_5070_50701001_49_dialog_content = "Meskipun mereka ada di sini, situasi kita tetap akan sangat buruk. Kecuali...",
  ui_story_5070_50701001_50_dialog_content = "Kecuali...?",
  ui_story_5070_50701001_51_dialog_content = "Kecuali jika ada yang menyadari bahwa Shadowind telah menyimpang dari jalur beberapa waktu lalu dan sudah merencanakan langkah pengendalian.",
  ui_story_5070_50701001_52_dialog_content = "Orang pertama yang menyadari menguap... Xuan Ji?",
  ui_story_5070_50701001_53_dialog_content = "...",
  ui_story_5070_50701001_54_dialog_content = "Hei, jangan menatapku seperti itu.",
  ui_story_5070_50701001_55_dialog_content = "Aku memang punya ide, tapi...",
  ui_story_5070_50701001_56_dialog_content = "Ini soal hidup-mati.",
  ui_story_5070_50701001_57_dialog_content = "Meskipun kita dalam kesulitan, kita masih bisa maju perlahan di Shadowind.",
  ui_story_5070_50701001_58_dialog_content = "Tapi jika kita mencoba ini dan gagal, seluruh kapal akan terbakar habis.",
  ui_story_5070_50701001_59_dialog_content = "Dan kita menjadi makanan ikan.",
  ui_story_5070_50701001_60_dialog_content = "Terlalu berisiko kecuali jika ini adalah pilihan terakhir.",
  ui_story_5070_50701001_61_dialog_content = "Kapten! Kapten! Kabar buruk, kabut di depan!",
  ui_story_5070_50701001_62_dialog_content = "Tidak bisa melihat banyak di sekitar kita sekarang; apa yang harus kita lakukan?",
  ui_story_5070_50701001_63_dialog_content = "Mencoba berlayar dalam kabut sepekat ini seperti berjalan menuju kematian yang pasti dengan mata tertutup.",
  ui_story_5070_50701001_64_dialog_content = "Tapi kita tak punya pilihan lagi.",
  ui_story_5070_50701001_65_dialog_content = "Ya sudah.",
  ui_story_5070_50701001_66_dialog_content = "Saya menyimpan sesuatu yang spesial di ruang kargo ketika saya naik ke kapal.",
  ui_story_5070_50701001_67_dialog_content = "Ini bisa menghidupkan semua jenis gadget.",
  ui_story_5070_50701001_68_dialog_content = "Kepiting Api, Naga Air, bahkan pembakar yang menggerakkan Shadowind...",
  ui_story_5070_50701001_69_dialog_content = "Semua dapat berkinerja seperti belum pernah terjadi sebelumnya di bawah kekuatannya.",
  ui_story_5070_50701001_70_dialog_content = "Tapi ini tidak stabil dan sangat menantang untuk dikendalikan.",
  ui_story_5070_50701001_71_dialog_content = "Telah dicatat bahwa dalam beberapa tes, hasilnya sangat berlebihan...",
  ui_story_5070_50701001_72_dialog_content = "Target tidak cukup tahan lama dan hancur sendiri.",
  ui_story_5070_50701001_73_dialog_content = "Jadi, meskipun kita memutuskan untuk menggunakannya, saya harus mengujinya di bawah air terlebih dahulu.",
  ui_story_5070_50701001_74_dialog_content = "Shadowind juga harus menjalani modifikasi agar setidaknya dapat menahan dampak operasional.",
  ui_story_5070_50701001_75_dialog_content = "Kalau tidak, ini bukan harapan terakhir kita, tapi malah kematian bagi kita semua.",
  ui_story_5070_50701001_76_dialog_content = "Nanti aku akan berikan daftar material tentang Shadowind. Lakukan saja apa yang perlu kamu lakukan.",
  ui_story_5070_50701001_77_dialog_content = "Aku juga akan memberi tahu tukang kapal bahwa mereka harus mengikuti perintahmu.",
  ui_story_5070_50701001_78_dialog_content = "Mungkin Flame Force Arts milikku juga akan berguna.",
  ui_story_5070_50701001_79_dialog_content = "Mengapa aku tidak menangani ikan yang baru saja kita tangkap, lalu menyiapkannya dengan cara yang menurutmu baru dan menarik?",
  ui_story_5070_50701001_80_dialog_content = "Tapi aku... Apa yang bisa kulakukan?",
  ui_story_5070_50701001_81_dialog_content = "Aku harus mencari barang di ruang penyimpanan, PlayerName.",
  ui_story_5070_50701001_82_dialog_content = "Bisakah Anda mencari si kecil dan mendapatkan beberapa obat untuk melawan asap beracun?",
  ui_story_5070_50701001_83_dialog_content = "Apakah kamu bilang Xuan Ji membawa Sprite Api ke kapal ini?!",
  ui_story_5070_50701001_84_dialog_content = "Aku bertanya-tanya kenapa aku terus mencium baunya di kapal! Hampir saja aku pikir ada yang salah dengan hidungku!",
  ui_story_5070_50701001_85_dialog_content = "Jadi dia di balik itu semua. Sungguh hal yang berbahaya untuk dilakukan...",
  ui_story_5070_50701001_86_dialog_content = "Menurut Master Bu, makhluk purba yang memiliki kesadaran seperti itu bisa mengendalikan Yin dan Yang, serta mengubah siang menjadi malam!",
  ui_story_5070_50701001_87_dialog_content = "Mendesah, ini pasti akan jadi menyakitkan.",
  ui_story_5070_50701001_88_dialog_content = "Ambil obat ini dan beritahu dia untuk tidak meledakkan kapal ini.",
  ui_story_5070_50701001_89_dialog_content = "Saya sudah mendapatkan obatnya, Xuan Ji.",
  ui_story_5070_50701001_90_dialog_content = "Tapi apa sebenarnya yang kamu bicarakan?",
  ui_story_5070_50701001_91_dialog_content = "Saya baru saja mengulangi deskripsi Anda, dan Liqing langsung membuat keributan.",
  ui_story_5070_50701001_92_dialog_content = "Sepertinya semua orang mengerti. Apakah hanya aku yang merasa benar-benar bingung?",
  ui_story_5070_50701001_93_dialog_content = "Yah, itu bukan untuk kamu katakan, PlayerName.",
  ui_story_5070_50701001_94_dialog_content = "Saya tidak yakin apakah saya tahu lebih banyak tentang kapal ini daripada Anda.",
  ui_story_5070_50701001_95_dialog_content = "Aku?",
  ui_story_5070_50701001_96_dialog_content = "Kamu akan tahu begitu aku mengeluarkannya.",
  ui_story_5070_50701001_97_dialog_content = "Mengambilnya? Dari mana?",
  ui_story_5070_50701001_98_dialog_content = "Ngomong-ngomong, aku ingin bertanya sejak lama... Kenapa ada begitu banyak sapi kayu di ruang kargo?",
  ui_story_5070_50701001_99_dialog_content = "Mereka adalah lembu kayu, alat yang paling umum di Longzhou dan telah ada selama beberapa generasi.",
  ui_story_5070_50701001_100_dialog_content = "Mereka terutama digunakan untuk mengangkut barang, meskipun juga cocok untuk membawa bagasi.",
  ui_story_5070_50701001_101_dialog_content = "Buka saja seperti ini dan kamu bisa mengeluarkan barangnya.",
  ui_story_5070_50701001_102_dialog_content = "Di dalamnya cukup luas. Kamu mungkin bisa memasukkan seseorang di sana.",
  ui_story_5070_50701001_103_dialog_content = "Mau coba ini?",
  ui_story_5070_50701001_104_dialog_content = "Tidak mungkin! Aku tidak tertarik untuk menjadi komoditas.",
  ui_story_5070_50701001_105_dialog_content = "Itu juga yang kupikirkan.",
  ui_story_5070_50701001_106_dialog_content = "Mari kita lihat bintang acara hari ini.",
  ui_story_5070_50701001_107_dialog_content = "Kotak kecil ini?",
  ui_story_5070_50701001_108_dialog_content = "Jangan meremehkan ini.",
  ui_story_5070_50701001_109_dialog_content = "Qianyun, sekolahku, adalah pembuat gadget terbaik di Ye, bahkan di seluruh Longzhou.",
  ui_story_5070_50701001_110_dialog_content = "Ini membanggakan warisan teknik rahasia dan artefak selama berabad-abad.",
  ui_story_5070_50701001_111_dialog_content = "Tapi, kamu bisa menggabungkan semua itu dan mungkin saja masih belum bisa dibandingkan dengan ini.",
  ui_story_5070_50701001_112_dialog_content = "Salah satu alasan terbesar saya untuk mengunjungi Astra adalah...",
  ui_story_5070_50701001_113_dialog_content = "Untuk menemukan harta tak ternilai yang hilang di luar negeri bertahun-tahun yang lalu...",
  ui_story_5070_50701001_114_dialog_content = "Api Zhuyin.",
  ui_story_5070_50701001_115_dialog_content = "Dari perspektif Astra, ini juga merupakan relik kuno yang sangat berharga.",
  ui_story_5070_50701001_116_dialog_content = "Relik kuno?!",
  ui_story_5070_50701001_117_dialog_content = "Mau lihat seberapa kuatnya?",
  ui_story_5070_50701001_118_dialog_content = "Ada sedikit risiko di Shadowind. Mari kita uji coba di perahu kecil yang jauh.",
  ui_story_5070_50701001_119_dialog_content = "Lihatlah mahakarya sejati dari masa lalu yang menggerakkan segalanya.",
  ui_story_5070_50701002_1_dialog_content = "Ini memang cocok sebagai benda kuno. Bahkan lebih kuat dari yang saya duga.",
  ui_story_5070_50701002_2_dialog_content = "Kamu juga merasakannya dengan kekuatan psikis kamu, kan, PlayerName? Rasanya gimana?",
  ui_story_5070_50701002_3_dialog_content = "Cukup keren.",
  ui_story_5070_50701002_4_dialog_content = "Tidak hanya dapat menggerakkan terus-menerus Clockwork Beasts yang sudah kehabisan tenaga, tetapi juga bisa...",
  ui_story_5070_50701002_5_dialog_content = "Ini juga menguapkan semua kelembapan di sekitarnya, menciptakan vakum.",
  ui_story_5070_50701002_6_dialog_content = "Sebagai tanggapan, sepertinya lebih besar dari semua api lainnya, bahkan seperti...",
  ui_story_5070_50701002_7_dialog_content = "Matahari mini?",
  ui_story_5070_50701002_8_dialog_content = "Total... Tunggu, bukankah itu deskripsi tentang diriku sendiri?",
  ui_story_5070_50701002_9_dialog_content = "Api Zhuyin... Itu bisa menyebabkan ledakan di kapal pada hari itu!",
  ui_story_5070_50701002_10_dialog_content = "Ups, ketahuan.",
  ui_story_5070_50701002_11_dialog_content = "Bukankah kamu setuju agar aku melihatnya dengan menggunakan kemampuanku? Aku hanya menurut saja!",
  ui_story_5070_50701002_12_dialog_content = "Melihat adalah percaya, bagaimanapun juga. Hal itu memberi tahu kamu lebih banyak daripada yang bisa saya jelaskan!",
  ui_story_5070_50701002_13_dialog_content = "Tidak heran Liqing memiliki reaksi yang sangat kuat.",
  ui_story_5070_50701002_14_dialog_content = "Siapa yang bisa menyangka akan ada sesuatu yang sangat berbahaya di atas kapal?",
  ui_story_5070_50701002_15_dialog_content = "Saya menyegelnya dengan hati-hati sebelum membawanya ke kapal agar aman.",
  ui_story_5070_50701002_16_dialog_content = "Tapi seseorang sengaja membukanya pada hari kebakaran itu.",
  ui_story_5070_50701002_17_dialog_content = "Aku membawanya ke kapal secara diam-diam.",
  ui_story_5070_50701002_18_dialog_content = "Bahkan Yuebai tidak tahu apa itu, padahal aku sudah memberi tahu dia terlebih dahulu.",
  ui_story_5070_50701002_19_dialog_content = "Tapi ada seseorang yang tahu tentang itu dan mencoba untuk mendekat.",
  ui_story_5070_50701002_20_dialog_content = "Mungkinkah sosok yang saya lihat tadi itu...?!",
  ui_story_5070_50701002_21_dialog_content = "Aku takut begitu.",
  ui_story_5070_50701002_22_dialog_content = "Untuk hal seperti ini... Kita harus segera memberi tahu yang lainnya.",
  ui_story_5070_50701002_23_dialog_content = "Kebetulan saja, uji coba Api Zhuyin berhasil, jadi Shadowind bisa segera keluar dari sini.",
  ui_story_5070_50701002_24_dialog_content = "Manfaatkan momen untuk menangkap pria jahat itu—",
  ui_story_5070_50701002_25_dialog_content = "Saya tidak ingat menyatakan bahwa tes tersebut berhasil.",
  ui_story_5070_50701002_26_dialog_content = "Apa? Bukankah semua Binatang Jam ini sudah aktif dengan lancar?",
  ui_story_5070_50701002_27_dialog_content = "Tidak ada keraguan bahwa Zhuyin Flame adalah sumber energi, tetapi bukankah kamu melihat apa yang terjadi pada binatang mekanik?",
  ui_story_5070_50701002_28_dialog_content = "... Hancur berkeping-keping dan jatuh ke laut.",
  ui_story_5070_50701002_29_dialog_content = "Binatang-binatang itu tidak besar, dan bahkan saat itu pun itu semua yang bisa saya tangani dengan cukup yakin.",
  ui_story_5070_50701002_30_dialog_content = "Jadi, meskipun Anda memperkuat Shadowind dengan setiap bahan terakhir yang dapat Anda kumpulkan...",
  ui_story_5070_50701002_31_dialog_content = "Ini tidak akan mampu menghadapi Api Zhuyin dengan kekuatan penuh.",
  ui_story_5070_50701002_32_dialog_content = "Apakah Xuan Ji benar-benar tidak bisa menyelesaikannya juga?",
  ui_story_5070_50701002_33_dialog_content = "Itu tidak sepenuhnya benar.",
  ui_story_5070_50701002_34_dialog_content = "Tapi sebelum itu, aku punya permintaan, PlayerName.",
  ui_story_5070_50701002_35_dialog_content = "Tolong jaga rahasia tentang percobaan yang gagal dan seseorang yang mengincar Api tersebut.",
  ui_story_5070_50701002_36_dialog_content = "Mungkin... Tapi sekarang kita harus bagaimana?",
  ui_story_5070_50701002_37_dialog_content = "Tunggu saja.",
  ui_story_5070_50701002_38_dialog_content = "<color=#e8d9bb>Keesokan harinya...</color>",
  ui_story_5070_50701002_39_dialog_content = "Semuanya, mari ambil salinan cetak biru. Ikuti tanda-tandanya, dan mulailah bekerja di tempat yang sudah ditugaskan untuk kalian.",
  ui_story_5070_50701002_40_dialog_content = "Cetak biru jenis apa ini?",
  ui_story_5070_50701002_41_dialog_content = "Eh... cetak biru ini...",
  ui_story_5070_50701002_42_dialog_content = "Saya telah bergelut dengan kapal sepanjang hidup saya, dan belum pernah melihat sesuatu seperti ini di atas kapal...",
  ui_story_5070_50701002_43_dialog_content = "Mengabaikan lubang besar di geladak adalah satu hal, tapi sengaja membuatnya lebih besar?",
  ui_story_5070_50701002_44_dialog_content = "Hampir saja terungkap inti dari Shadowind. Itu terlalu aneh... Sun, apa pendapatmu tentang ini?",
  ui_story_5070_50701002_45_dialog_content = "Aku... aku juga tak paham...",
  ui_story_5070_50701002_46_dialog_content = "Kenapa repot-repot dengan semua itu? Lady Xuan Ji jauh lebih terampil daripada kita, bukan?",
  ui_story_5070_50701002_47_dialog_content = "Ayo mulai bekerja sekarang; setelah selesai, kita bisa keluar dari sini.",
  ui_story_5070_50701002_48_dialog_content = "<color=#e8d9bb>Hari Ketiga</color>",
  ui_story_5070_50701002_49_dialog_content = "Teman-teman, yuk ikut aku memancing.",
  ui_story_5070_50701002_50_dialog_content = "Ugh, sudah berapa hari kita bertahan hanya dengan makan ikan? Dan sekarang, bahkan bumbunya pun mulai habis. Rasanya... Tidak bisa diungkapkan dengan kata-kata.",
  ui_story_5070_50701002_51_dialog_content = "Tahan saja beberapa hari. Semuanya akan lebih baik setelah perombakan kapal selesai.",
  ui_story_5070_50701002_52_dialog_content = "<color=#e8d9bb>Hari Kelima</color>",
  ui_story_5070_50701002_53_dialog_content = "Kabut di tempat memancing kami semakin tebal; kami hampir tidak bisa menangkap ikan sekarang.",
  ui_story_5070_50701002_54_dialog_content = "Bukankah kita sudah menyelesaikan renovasi Shadowind? Mengapa Lady Xuan Ji belum memberi kita instruksi lebih lanjut...",
  ui_story_5070_50701002_55_dialog_content = "Li, jangan beritahu siapa pun, tapi aku dengar dari Sun yang Ahli bahwa usaha kita dalam renovasi ini sia-sia.",
  ui_story_5070_50701002_56_dialog_content = "Belumkah kamu menyadari bahwa Lady Xuan Ji pergi dengan perahu kecil setiap hari? Dia bilang itu untuk eksplorasi, tapi sepertinya dia mencoba menyembunyikan betapa bingungnya dia!",
  ui_story_5070_50701002_57_dialog_content = "Omong kosong apa yang kalian bicarakan? Dan kamu, Sun, jangan sampai Kapten Yuebai menangkapmu menyebarkan rumor tak berdasar...",
  ui_story_5070_50701002_58_dialog_content = "Hai! PlayerName! PlayerName!",
  ui_story_5070_50701002_59_dialog_content = "Anda telah pergi bersama Lady Xuan Ji beberapa hari terakhir ini. Apakah Anda mendengar sesuatu tentang bagaimana kita akan keluar dari sini?",
  ui_story_5070_50701002_60_dialog_content = "Nah, yang bisa saya katakan adalah ada cara... A-aku harus memberikan sesuatu kepada Xuan Ji, jadi aku pergi!",
  ui_story_5070_50701002_61_dialog_content = "Fyuh...",
  ui_story_5070_50701002_62_dialog_content = "Cepatlah, PlayerName. Saya membuat modifikasi struktural yang serupa berdasarkan deskripsi Colossus yang kamu berikan.",
  ui_story_5070_50701002_63_dialog_content = "Apa? Kau terlihat seperti baru saja bertarung lagi dengan kru.",
  ui_story_5070_50701002_64_dialog_content = "Haha... Lagipula, kita sudah di sini beberapa hari. Semua orang sedikit tegang dan ingin segera keluar dari sini.",
  ui_story_5070_50701002_65_dialog_content = "Model ini, jika dibandingkan dengan Colossus, lebih mirip seperti Shadowind dengan sayap. Biar aku lihat...",
  ui_story_5070_50701002_66_dialog_content = "Apakah kamu tidak punya pertanyaan untuk saya, PlayerName?",
  ui_story_5070_50701002_67_dialog_content = "Apa?",
  ui_story_5070_50701002_68_dialog_content = "Aku memintamu untuk merahasiakan sesuatu tanpa memberimu penjelasan yang jelas.",
  ui_story_5070_50701002_69_dialog_content = "Kemudian, saya memerintahkan orang lain untuk membuat banyak modifikasi, hanya untuk tetap berada di perahu kecil sepanjang hari dan menghindari semua pertanyaan.",
  ui_story_5070_50701002_70_dialog_content = "Bahkan aku sendiri mencurigai bahwa aku sedang melakukan sesuatu yang tidak baik.",
  ui_story_5070_50701002_71_dialog_content = "Kenapa kamu percaya padaku, PlayerName?",
  ui_story_5070_50701002_72_dialog_content = "Aku nggak begitu percaya padamu.",
  ui_story_5070_50701002_73_dialog_content = "Kupikir begitu...",
  ui_story_5070_50701002_74_dialog_content = "Tapi, saya memang percaya pada mesin.",
  ui_story_5070_50701002_75_dialog_content = "Hah?",
  ui_story_5070_50701002_76_dialog_content = "Tentu saja, tidak begitu santai menghadapi Binatang Jam yang muncul tiba-tiba dari mana-mana.",
  ui_story_5070_50701002_77_dialog_content = "Tapi saat pertama kali kita bertemu, seekor capung membantu saya mengambil surat itu.",
  ui_story_5070_50701002_78_dialog_content = "Kepiting api untuk menggerakkan mesin, naga air untuk memadamkan api...",
  ui_story_5070_50701002_79_dialog_content = "Aku telah dibantu oleh makhluk mekanik berulang kali.",
  ui_story_5070_50701002_80_dialog_content = "Anda sendiri yang mengatakannya, Xuan Ji: Mesin bukanlah teknologi yang selalu berubah dan memiliki kekuatan segalanya.",
  ui_story_5070_50701002_81_dialog_content = "Saya percaya pada mesin, yang mana Anda tidak akan pernah berbohong tentangnya.",
  ui_story_5070_50701002_82_dialog_content = "Jadi, saya juga percaya bahwa Anda akan menemukan cara untuk membawa kita dengan aman ke Longzhou.",
  ui_story_5070_50701002_83_dialog_content = "Dia.",
  ui_story_5070_50701002_84_dialog_content = "Yah, aku sama sekali tidak bisa membantah itu.",
  ui_story_5070_50701002_85_dialog_content = "Mengingat apa yang Anda katakan, PlayerName...",
  ui_story_5070_50701002_86_dialog_content = "Saya akan lalai sebagai pengrajin jika tidak menunjukkan potensi dari perdagangan saya.",
  ui_story_5070_50701002_87_dialog_content = "Aku menantikannya. Tapi aku berbohong jika aku bilang aku tidak penasaran.",
  ui_story_5070_50701002_88_dialog_content = "Apa sebenarnya yang kamu tunggu, Xuan Ji?",
  ui_story_5070_50701002_89_dialog_content = "Yah, sebenarnya…",
  ui_story_5070_50701002_90_dialog_content = "<color=#e8d9bb>Tiupan peluit</color>",
  ui_story_5070_50701002_91_dialog_content = "Apa suara itu dari Shadowind? Kenapa terompetnya ditiup?",
  ui_story_5070_50701002_92_dialog_content = "Itu sinyal untuk komunikasi antar kapal di laut.",
  ui_story_5070_50701002_93_dialog_content = "Mungkinkah ada kapal lain?!",
  ui_story_5070_50701002_94_dialog_content = "<color=#e8d9bb>Beberapa saat lalu</color>",
  ui_story_5070_50701002_95_dialog_content = "Jiu, Yuebai, ayo lihat ini.",
  ui_story_5070_50701002_96_dialog_content = "Apakah itu kapal di sana?",
  ui_story_5070_50701002_97_dialog_content = "Yang Mulia, silakan mundur dari sisi kapal.",
  ui_story_5070_50701002_98_dialog_content = "Itu bukan yang harus kamu khawatirkan, Jiu.",
  ui_story_5070_50701002_99_dialog_content = "Keselamatan Anda sangat penting, jadi kita harus berhati-hati dalam menjaganya.",
  ui_story_5070_50701002_100_dialog_content = "Saya tidak bisa melihat apa yang terjadi di kapal, tetapi beberapa kapal dagang sedang menuju ke arah kami.",
  ui_story_5070_50701002_101_dialog_content = "Saya tidak pernah berpikir kita akan bertemu kapal lain di perairan ini.",
  ui_story_5070_50701002_102_dialog_content = "Haruskah kita menghubungi mereka? Saya penasaran apakah mereka memiliki banyak persediaan. Kalau tidak...",
  ui_story_5070_50701002_103_dialog_content = "Sekarang mungkin sudah terlambat untuk menghindari mereka, 'kan?",
  ui_story_5070_50701002_104_dialog_content = "Bunyikan klakson dan lihat bagaimana reaksi mereka.",
  ui_story_5070_50701002_105_dialog_content = "<color=#e8d9bb>Tiupan peluit</color>",
  ui_story_5070_50701002_106_dialog_content = "<color=#e8d9bb>Tiupan peluit</color>",
  ui_story_5070_50701002_107_dialog_content = "Respons diterima!",
  ui_story_5070_50701002_108_dialog_content = "Apakah itu kapal yang juga terjebak di sini? Sempurna, kita bisa memikirkan cara keluar bersama-sama.",
  ui_story_5070_50701002_109_dialog_content = "Mungkin kita bisa barter makanan dan air dengan mereka juga.",
  ui_story_5070_50701002_110_dialog_content = "Kalau begitu, mari kita kembali ke kapal dan mencari tahu.",
  ui_story_5070_50701002_111_dialog_content = "Aku melihat mereka. Mereka jelas mendekati Shadowind.",
  ui_story_5070_50701002_112_dialog_content = "Eh... Mereka tidak terlalu cepat, ya?",
  ui_story_5070_50701002_113_dialog_content = "Mereka tidak hanya gagal melambat, tapi malah semakin mempercepat?!",
  ui_story_5070_50701002_114_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5070_50701002_115_dialog_content = "Bagaimana... Bagaimana bisa kapal itu menabrak Shadowind begitu saja?!",
  ui_story_5070_50701002_116_dialog_content = "Oh, tidak...",
  ui_story_5070_50701002_117_dialog_content = "Ini kapal bajak laut!",
  ui_story_5070_50701002_118_dialog_content = "Cepat, PlayerName, Shadowind dalam masalah!",
  ui_story_5070_50701101_1_dialog_content = "Kenapa kalian bajingan kurang ajar! Beraninya kalian melakukan ini pada Jiu...",
  ui_story_5070_50701101_2_dialog_content = "Tunggu!",
  ui_story_5070_50701101_3_dialog_content = "<color=#e8d9bb>Swus—</color>",
  ui_story_5070_50701101_4_dialog_content = "<color=#e8d9bb>Paluban di kaki Dantang terkena, membakar lubang besar.</color>",
  ui_story_5070_50701101_5_dialog_content = "...",
  ui_story_5070_50701101_6_dialog_content = "Yang Mulia, saya tahu ini bukan tempat saya untuk mengatakannya; saya berani mengingatkan Anda...",
  ui_story_5070_50701101_7_dialog_content = "Mungkin terasa menyenangkan memenangkan pertengkaran, tetapi di laut, lebih baik aman daripada menyesal.",
  ui_story_5070_50701101_8_dialog_content = "Sepertinya Dantang sedang diserang! Ayo naik ke sana dengan cepat—",
  ui_story_5070_50701101_9_dialog_content = "Tunggu, mereka tahu siapa kita, jadi aku tidak pikir ada yang buruk akan terjadi pada putri dan Jiu.",
  ui_story_5070_50701101_10_dialog_content = "Tapi kita belum tahu apa yang mereka lakukan, jadi kita hanya akan tertangkap jika kita naik sekarang.",
  ui_story_5070_50701101_11_dialog_content = "Tetap tersembunyi dan pahami situasinya sebelum melakukan langkah.",
  ui_story_5070_50701101_12_dialog_content = "Hmm... Suara orang yang baru saja berbicara dengan Dantang sepertinya agak familiar, ya?",
  ui_story_5070_50701101_13_dialog_content = "Itu Sun yang Cakap.",
  ui_story_5070_50701101_14_dialog_content = "Dia?!",
  ui_story_5070_50701101_15_dialog_content = "Ssst.",
  ui_story_5070_50701101_16_dialog_content = "Terus mendengarkan.",
  ui_story_5070_50701101_17_dialog_content = "Kamu bukan Sun the Skillful yang asli, kan?",
  ui_story_5070_50701101_18_dialog_content = "Heh, Sun yang Cakap itu hanyalah bagian luarnya saja.",
  ui_story_5070_50701101_19_dialog_content = "Tapi untuk orang-orang rendahan seperti kamu, kalian hanya mengenal saya sebagai Sun yang Cakap.",
  ui_story_5070_50701101_20_dialog_content = "Kamu... Tidak bisa percaya kamu benar-benar berkolusi dengan bajak laut!",
  ui_story_5070_50701101_21_dialog_content = "Apakah kamu lupa akan kebaikan keluarga Lin kepada kita? Kau pengkhianat yang keji...",
  ui_story_5070_50701101_22_dialog_content = "Diamlah!",
  ui_story_5070_50701101_23_dialog_content = "Jangan berisik jika kamu tidak ingin tenggelam di sana bersama Nona Jiu.",
  ui_story_5070_50701101_24_dialog_content = "Ingatlah: prajurit paling terampil di kapal ini sudah menemui ajalnya.",
  ui_story_5070_50701101_25_dialog_content = "Kurasa tidak banyak ruang untuk perjuangan di pihakmu.",
  ui_story_5070_50701101_26_dialog_content = "Itu karena Anda menggunakan taktik yang tercela!",
  ui_story_5070_50701101_27_dialog_content = "Jiu tidak akan dirugikan tanpa sinar aneh itu!",
  ui_story_5070_50701101_28_dialog_content = "Menggunakan kata-kata hinaan, ya? Tuan Putri, saya benar-benar menyarankan Anda untuk jaga bicaramu.",
  ui_story_5070_50701101_29_dialog_content = "Itu adalah ciptaan mekanik yang luar biasa setara dengan... Tidak, itu benar-benar lebih menonjol dari Shadowind!",
  ui_story_5070_50701101_30_dialog_content = "Siapa saja bisa menyombongkan diri.",
  ui_story_5070_50701101_31_dialog_content = "Seberapa terhormatkah kamu jika bersembunyi di perahu dan hanya menyerang dari jauh?",
  ui_story_5070_50701101_32_dialog_content = "(Benar, Putri Dantang. Terus jengkelkan dia dengan sengaja.)",
  ui_story_5070_50701101_33_dialog_content = "(Kita perlu mengumpulkan informasi sebanyak mungkin sebelum Jiu dan yang lainnya kembali.)",
  ui_story_5070_50701101_34_dialog_content = "Selain melancarkan serangan diam-diam, semua yang dilakukan pasukan Anda setelah naik ke kapal kami adalah menangkap Zhong Xu dan Liqing.",
  ui_story_5070_50701101_35_dialog_content = "Kalian adalah sekelompok pengecut yang hanya berani menargetkan seorang pria cacat dan seorang anak kecil.",
  ui_story_5070_50701101_36_dialog_content = "Ayo berpencar.",
  ui_story_5070_50701101_37_dialog_content = "Penciptaan itu jelas memiliki daya keluaran yang kuat untuk memproyeksikan sinar mematikan.",
  ui_story_5070_50701101_38_dialog_content = "Aku harus melihat lebih dekat.",
  ui_story_5070_50701101_39_dialog_content = "Aku?",
  ui_story_5070_50701101_40_dialog_content = "Tetap di perahu dan awasi Shadowind.",
  ui_story_5070_50701101_41_dialog_content = "Pastikan kamu sembunyi dengan baik. Aku harus pergi—",
  ui_story_5070_50701101_42_dialog_content = "Ini bukan disebut pembagian kerja.",
  ui_story_5070_50701101_43_dialog_content = "?",
  ui_story_5070_50701101_44_dialog_content = "Ini hanya meninggalkan aku di tempat yang aman, sementara kamu yang menanggung risikonya.",
  ui_story_5070_50701101_45_dialog_content = "Entah kenapa...",
  ui_story_5070_50701101_46_dialog_content = "Tapi waktu itu berharga.",
  ui_story_5070_50701101_47_dialog_content = "Aku ingin kembali ke Shadowind. Meskipun aku tidak bisa bertarung seperti kamu...",
  ui_story_5070_50701101_48_dialog_content = "Pasti ada sesuatu yang bisa kulakukan di atas sana.",
  ui_story_5070_50701101_49_dialog_content = "Bahkan jika kamu ketahuan, mungkin aku bisa mengulur waktu untukmu.",
  ui_story_5070_50701101_50_dialog_content = "Ini namanya pembagian kerja.",
  ui_story_5070_50701101_51_dialog_content = "Bagaimana jika saya menolak gagasan itu?",
  ui_story_5070_50701101_52_dialog_content = "Jadi, aku akan menunggu kamu pergi, lalu menyelinap ke kapal.",
  ui_story_5070_50701101_53_dialog_content = "Jangan bilang nekat menghadapi bahaya adalah sifat khas Caelestite.",
  ui_story_5070_50701101_54_dialog_content = "Apakah keinginan melindungi semua orang di belakang mereka dan melakukan segalanya sendiri merupakan hal khas pengrajin?",
  ui_story_5070_50701101_55_dialog_content = "Kurasa itu membuat kita sama.",
  ui_story_5070_50701101_56_dialog_content = "Kamu percaya padaku, PlayerName...",
  ui_story_5070_50701101_57_dialog_content = "Jadi jika saya tidak mempercayai Anda sebagai balasannya, PlayerName, itu cukup tidak adil.",
  ui_story_5070_50701101_58_dialog_content = "Kalau begitu, semoga berhasil.",
  ui_story_5070_50701102_1_dialog_content = "Peningkatan Kekuatan! Terpikirkan sesuatu yang terlupakan—",
  ui_story_5070_50701102_2_dialog_content = "Hei! Apakah bos lupa tentang hadiahku? Harus mengingatkannya nih...",
  ui_story_5070_50701102_3_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_5070_50701102_4_dialog_content = "(Hebat, para bajak laut Longzhou ini tidak memiliki pengetahuan atau pengalaman tentang kemampuan telepati Caelestite.)",
  ui_story_5070_50701102_5_dialog_content = "(Jadi, aku bisa mendorong dengan tenang seperti ini, menyarankan bahwa mereka yang khawatir bisa keluar dari sana sebentar...)",
  ui_story_5070_50701102_6_dialog_content = "Kenapa orang di pintu itu pergi? Apakah kita masih berpatroli atau bagaimana?",
  ui_story_5070_50701102_7_dialog_content = "Tidak apa-apa. Ini tidak akan mengacaukan tugas kita, kok.",
  ui_story_5070_50701102_8_dialog_content = "Kita hanya mengawasi seorang cacat dan seorang anak, keduanya di dalam kandang. Apakah kamu benar-benar harus begitu tegang?",
  ui_story_5070_50701102_9_dialog_content = "(Banyak sekali perompak! Dan di dalam sangkar mekanik... Zhong Xu dan Liqing?!)",
  ui_story_5070_50701102_10_dialog_content = "(Eh? Apa yang sedang dilakukan Liqing?)",
  ui_story_5070_50701102_11_dialog_content = "*Endus...*",
  ui_story_5070_50701102_12_dialog_content = "(Ini tercium seperti... PlayerName!)",
  ui_story_5070_50701102_13_dialog_content = "(Di sini! Lihat ke sini—! Pandangan kita bertemu!)",
  ui_story_5070_50701102_14_dialog_content = "Meong...",
  ui_story_5070_50701102_15_dialog_content = "Apa yang sedang kamu lakukan? Mencoba mengeong seperti kucing?",
  ui_story_5070_50701102_16_dialog_content = "Aku bosan. Kamu nggak bisa membiarkanku keluar jalan-jalan sekarang, kan?",
  ui_story_5070_50701102_17_dialog_content = "(Apa arti Liqing?)",
  ui_story_5070_50701102_18_dialog_content = "Meong...",
  ui_story_5070_50701102_19_dialog_content = "(Tinytail! Dan di sebelah Zhong Xu... Itu Yixin, Yimeng, dan Yinuo, kan?)",
  ui_story_5070_50701102_20_dialog_content = "(Dari mana mereka berasal?)",
  ui_story_5070_50701102_21_dialog_content = "Kamu dengar itu?! Apa ada sesuatu yang terjadi di pintu?",
  ui_story_5070_50701102_22_dialog_content = "Nah, kamu mungkin salah dengar.",
  ui_story_5070_50701102_23_dialog_content = "Pertama, kamu bilang orang cacat berambut merah itu terlihat familiar, dan sekarang kamu bilang ada sesuatu yang terjadi di pintu. Ayo, bisakah kamu berhenti sejenak?",
  ui_story_5070_50701102_24_dialog_content = "Akan kuperiksa.",
  ui_story_5070_50701102_25_dialog_content = "(!!!)",
  ui_story_5070_50701102_26_dialog_content = "(Tak ada waktu untuk sembunyi. Aku hanya punya satu kesempatan untuk ini!)",
  ui_story_5070_50701102_27_dialog_content = "Tolong, bantu aku mengulur waktu!",
  ui_story_5070_50701102_28_dialog_content = "Meong!",
  ui_story_5070_50701102_29_dialog_content = "Apa itu?!",
  ui_story_5070_50701102_30_dialog_content = "Dari mana kucing liar ini datang? Hilang! Sst... dan ternyata dia menggigit!",
  ui_story_5070_50701102_31_dialog_content = "(Sekarang saatnya, untuk semua orang di ruangan ini...)",
  ui_story_5070_50701102_32_dialog_content = "Provokasi mereka dengan Angkatan Meningkatkan!",
  ui_story_5070_50701102_33_dialog_content = "Ah—kenapa tiba-tiba kepalaku berdenyut sakit?!",
  ui_story_5070_50701102_34_dialog_content = "Kucing—! Kucing ini mencakar wajahku!",
  ui_story_5070_50701102_35_dialog_content = "PlayerName! Selamatkan Zhong Xu dulu!",
  ui_story_5070_50701102_36_dialog_content = "Meong...",
  ui_story_5070_50701102_37_dialog_content = "Anda membawa kuncinya? Terima kasih, Tinytail.",
  ui_story_5070_50701102_38_dialog_content = "Tunggu sebentar, Zhong Xu. Saya sedang membukanya sekarang.",
  ui_story_5070_50701102_39_dialog_content = "Terima kasih, tapi kamu tidak perlu terburu-buru karena aku baik-baik saja.",
  ui_story_5070_50701102_40_dialog_content = "Mungkin kamu tidak khawatir, tapi aku khawatir! Kamu terlalu lambat, PlayerName! Aku akan melakukannya!",
  ui_story_5070_50701102_41_dialog_content = "Liqing?! Bagaimana kamu bisa keluar?",
  ui_story_5070_50701102_42_dialog_content = "Celahan di kandang ini sangat besar! Apakah kamu tidak bisa menyelipkan diri dari samping saja?!",
  ui_story_5070_50701102_43_dialog_content = "Apakah itu sesuatu yang bisa dilakukan oleh Aurorian biasa...?",
  ui_story_5070_50701102_44_dialog_content = "Aurorian biasa tidak bisa, tapi aku bukan Aurorian biasa.",
  ui_story_5070_50701102_45_dialog_content = "Tidak biasa?!",
  ui_story_5070_50701102_46_dialog_content = "Bukankah sudah kubilang?",
  ui_story_5070_50701102_47_dialog_content = "Aku kucing.",
  ui_story_5070_50701102_48_dialog_content = "?!",
  ui_story_5070_50701102_49_dialog_content = "Tepatnya, saya adalah Fiendling kucing. Tinytail di sana adalah saudara kandung yang lebih tua saya.",
  ui_story_5070_50701102_50_dialog_content = "K-Kakak...",
  ui_story_5070_50701102_51_dialog_content = "PlayerName? Ada apa?",
  ui_story_5070_50701102_52_dialog_content = "Tidak ada Fiendlings di Astra, jadi saya bisa mengerti mengapa kamu begitu terkejut.",
  ui_story_5070_50701102_53_dialog_content = "Zhongxu...",
  ui_story_5070_50701102_54_dialog_content = "Ada apa?",
  ui_story_5070_50701102_55_dialog_content = "Ada tiga kucing di sekitarmu, tapi... kamu bukan Fiendling, kan?",
  ui_story_5070_50701102_56_dialog_content = "Kamu nggak tiba-tiba akan berubah jadi kucing juga, kan?",
  ui_story_5070_50701102_57_dialog_content = "Ha ha ha! Aku memang hanya orang biasa, jadi aku khawatir kamu akan kecewa.",
  ui_story_5070_50701102_58_dialog_content = "Tidak, tidak! Lebih baik mengatakan ini hebat... Dan ini masih tetap biasa, dapat diandalkan Zhong Xu.",
  ui_story_5070_50701102_59_dialog_content = "Aduh... kamu, kalian semua...",
  ui_story_5070_50701102_60_dialog_content = "PlayerName, bajingan-bajingan ini kembali sadar.",
  ui_story_5070_50701102_61_dialog_content = "Dan bukan hanya mereka. Ada sekelompok orang yang mendekati pintu masuk. Mereka seharusnya datang dari geladak.",
  ui_story_5070_50701102_62_dialog_content = "Kepung mereka!",
  ui_story_5070_50701102_63_dialog_content = "Satu-satunya petarung yang mampu di sini adalah orang cacat, tetapi dia hanya terampil dalam Seni Flame Force.",
  ui_story_5070_50701102_64_dialog_content = "Selama kita tumpulkan nyala apinya, dia tidak berguna.",
  ui_story_5070_50701102_65_dialog_content = "Orang-orang ini!",
  ui_story_5070_50701102_66_dialog_content = "Tunggu, Zhong Xu. Pastikan kamu aman dulu, sementara Liqing dan saya menyusun rencana.",
  ui_story_5070_50701102_67_dialog_content = "Hah? PlayerName, kamu tidak tahu? Sebenarnya...",
  ui_story_5070_50701102_68_dialog_content = "Saya menghargai niat baik Anda.",
  ui_story_5070_50701102_69_dialog_content = "Lin Guildmaster... Dia lemah dan rapuh, tetapi dia selalu melindungi saya seperti ini.",
  ui_story_5070_50701102_70_dialog_content = "Sudah bertahun-tahun aku berurusan dengan orang-orang ini, jadi mungkin ini takdir bahwa aku tertangkap di sini.",
  ui_story_5070_50701102_71_dialog_content = "Mungkin bahkan langit pun percaya saatnya bagi saya untuk menyelesaikan masalah dengan para bajak laut ini sekali untuk selamanya.",
  ui_story_5070_50701102_72_dialog_content = "Jadi, bisakah kamu menunggu sebentar dan serahkan musuh-musuh ini padaku?",
  ui_story_5070_50701102_73_dialog_content = "Oke. Aku akan berusaha sebaik mungkin untuk mendukung—",
  ui_story_5070_50701102_74_dialog_content = "Itu tidak perlu. Kekuatan anehmu mungkin lebih membantu untuk Tuan Putri Dantang dan Menteri Armilla.",
  ui_story_5070_50701102_75_dialog_content = "Bagi saya, saya hanya tahu satu cara untuk bertarung, dan saya hanya membutuhkan satu cara ini untuk bertarung.",
  ui_story_5070_50701102_76_dialog_content = "Jika kamu benar-benar ingin membantuku, berikanlah pedangku yang diambil tadi.",
  ui_story_5070_50701102_77_dialog_content = "Baiklah, ini yang ini, bukan...? Wah, berat!",
  ui_story_5070_50701102_78_dialog_content = "Terima kasih.",
  ui_story_5070_50701102_79_dialog_content = "(Saat dia mengambil pedang, mata Zhong Xu tampak berubah.)",
  ui_story_5070_50701102_80_dialog_content = "Hah, apa yang diomongin orang cacat ini? Dia benar-benar berpikir dia bisa menghadapi kita semua sendirian!?",
  ui_story_5070_50701102_81_dialog_content = "Dia benar-benar kewalahan—",
  ui_story_5070_50701102_82_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5070_50701102_83_dialog_content = "Ugh...",
  ui_story_5070_50701102_84_dialog_content = "<color=#e8d9bb>Senyum sombong belum hilang dari wajahnya, namun tubuh perompak itu sudah jatuh ke tanah.</color>",
  ui_story_5070_50701102_85_dialog_content = "Apa... apa yang baru saja dia lakukan?",
  ui_story_5070_50701102_86_dialog_content = "Jangan panik! Dia hanya cepat dengan pedangnya! Ada begitu banyak dari kita—Ah!",
  ui_story_5070_50701102_87_dialog_content = "Alih-alih memberi saya pujian yang tidak pantas ini, lebih baik kamu jatuh saja.",
  ui_story_5070_50701102_88_dialog_content = "Hei! Siapa yang bilang semuanya akan baik-baik saja asalkan kita menjaga apinya tetap terkendali?",
  ui_story_5070_50701102_89_dialog_content = "Orang ini... Dia sama sekali tidak menggunakan apinya!",
  ui_story_5070_50701102_90_dialog_content = "Momentum para bajak laut berhasil ditekan oleh Zhong Xu sendirian.",
  ui_story_5070_50701102_91_dialog_content = "Tentu saja, kita sedang membahas tentang Zhong Xu di sini!",
  ui_story_5070_50701102_92_dialog_content = "Pergi... PERGI KE NERAKA!",
  ui_story_5070_50701102_93_dialog_content = "Zhong Xu! Di belakangmu!",
  ui_story_5070_50701102_94_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5070_50701102_95_dialog_content = "Ahhh!",
  ui_story_5070_50701102_96_dialog_content = "Kekhawatiranku sia-sia, karena Zhong Xu menghunus pedangnya lebih cepat daripada aku bisa berteriak.",
  ui_story_5070_50701102_97_dialog_content = "Lihat? Bahkan dalam kursi roda, kumpulan orang ini tidak ada apa-apanya untuk Zhong Xu.",
  ui_story_5070_50701102_98_dialog_content = "Kapal karam itu merenggut kaki saya.",
  ui_story_5070_50701102_99_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5070_50701102_100_dialog_content = "Dan kamu juga bisa mencoba menekan nyala api yang menyala-nyala ini.",
  ui_story_5070_50701102_101_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5070_50701102_102_dialog_content = "Tapi selama aku masih memiliki satu tangan dan pedang.",
  ui_story_5070_50701102_103_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5070_50701102_104_dialog_content = "Aku akan terus mengayunkan pedangku dan membunuh musuh-musuh.",
  ui_story_5070_50701102_105_dialog_content = "Ini adalah satu-satunya cara bertarung yang aku tahu.",
  ui_story_5070_50701102_106_dialog_content = "Monster... Monster yang mengerikan—!",
  ui_story_5070_50701102_107_dialog_content = "Orang-orang sering memanggilku seperti itu beberapa tahun lalu.",
  ui_story_5070_50701102_108_dialog_content = "Kamu... Tunggu, jangan bilang...",
  ui_story_5070_50701102_109_dialog_content = "Aku ingat sekarang!",
  ui_story_5070_50701102_110_dialog_content = "Rambut merah dan jubah panjang.",
  ui_story_5070_50701102_111_dialog_content = "Hanya dengan pedang, dia bisa membersihkan kapal yang penuh dengan perompak seorang diri.",
  ui_story_5070_50701102_112_dialog_content = "Jenderal yang membasmi kelompok bajak laut terakhir yang menguasai perairan di sekitar Kerajaan Ji... itu kamu!",
  ui_story_5070_50701102_113_dialog_content = "Jenderal Agung yang secara pribadi dihormati oleh Kaisar!",
  ui_story_5070_50701102_114_dialog_content = "Itu semua sudah di masa lalu sekarang.",
  ui_story_5070_50701102_115_dialog_content = "<color=#e8d9bb>Wush—</color>",
  ui_story_5070_50701102_116_dialog_content = "<color=#e8d9bb>Musuh terakhir roboh ke tanah.</color>",
  ui_story_5070_50701102_117_dialog_content = "Sekarang aku hanya seorang pengembara...",
  ui_story_5070_50701102_118_dialog_content = "Atau pria paruh baya yang bisa memberikan bantuan kepada anak-anak muda.",
  ui_story_5070_50701201_1_dialog_content = "<color=#e8d9bb>Sementara itu, di kapal musuh</color>",
  ui_story_5070_50701201_2_dialog_content = "(Kapal ini dibangun seperti Shadowind?!)",
  ui_story_5070_50701201_3_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5070_50701201_4_dialog_content = "!",
  ui_story_5070_50701201_5_dialog_content = "Saya seharusnya merasa terhormat karena disambut dengan cara seperti ini.",
  ui_story_5070_50701201_6_dialog_content = "Ini jelas sengat kalajengking, tapi kok tidak menyemprotkan racun...",
  ui_story_5070_50701201_7_dialog_content = "Tapi sinar Lumina dari orang Astra?",
  ui_story_5070_50701201_8_dialog_content = "Graagh!",
  ui_story_5070_50701201_9_dialog_content = "Ekor berbentuk tombak, penjepit seperti pisau, dengan cangkang tebal dari logam...",
  ui_story_5070_50701201_10_dialog_content = "Aktivasi penuh!",
  ui_story_5070_50701201_11_dialog_content = "<color=#e8d9bb>ding—</color>",
  ui_story_5070_50701201_12_dialog_content = "Terkesan seperti batu namun ringan seperti giok.",
  ui_story_5070_50701201_13_dialog_content = "Tak ada tanda kerusakan dari hujan peluru. Sepertinya terbuat dari bahan langka.",
  ui_story_5070_50701201_14_dialog_content = "Kamu tahu...",
  ui_story_5070_50701201_15_dialog_content = "Klik-klak...",
  ui_story_5070_50701201_16_dialog_content = "Benda ini pasti mengkonsumsi banyak sekali tenaga.",
  ui_story_5070_50701201_17_dialog_content = "Tapi ternyata tidak melemah, bahkan semakin kuat setelah semua pertempuran ini.",
  ui_story_5070_50701201_18_dialog_content = "Betapa menakjubkannya inti itu... Pasti tidak lebih dari beberapa di dunia.",
  ui_story_5070_50701201_19_dialog_content = "Kebetulan sekali, ada satu lagi di Shadowind.",
  ui_story_5070_50701201_20_dialog_content = "Jika aku membongkar monster ini, apakah aku akan menemukan sumber kekuatannya...",
  ui_story_5070_50701201_21_dialog_content = "Untuk menjadi Zhuyin Flame yang lain?",
  ui_story_5070_50701201_22_dialog_content = "Kamu mungkin bahkan tak bisa memecahkannya.",
  ui_story_5070_50701201_23_dialog_content = "Ah, akhirnya menunjukkan dirimu.",
  ui_story_5070_50701201_24_dialog_content = "Pertama, kamu menyamar sebagai Sun, lalu kamu mengirimkan orang bodoh besar dan jelek ini padaku.",
  ui_story_5070_50701201_25_dialog_content = "Aku mulai berpikir bahwa kamu hanya melakukan sesuatu saat ada sesuatu yang ingin kamu sembunyikan di belakangnya.",
  ui_story_5070_50701201_26_dialog_content = "Heh, aku tidak akan repot-repot berbickering denganmu.",
  ui_story_5070_50701201_27_dialog_content = "Ternyata, kata-kata tajam si pecundang hanya menunjukkan ketidakberdayaan.",
  ui_story_5070_50701201_28_dialog_content = "Pecundang? Justru sebaliknya.",
  ui_story_5070_50701201_29_dialog_content = "Alasannya adalah karena kamu yakin akan ketidakmampuanmu dan meyakinkan diri bahwa kamu adalah orang yang kalah.",
  ui_story_5070_50701201_30_dialog_content = "Kamu merencanakan dan membuat skema untuk mendapatkan apa yang menjadi milik orang lain.",
  ui_story_5070_50701201_31_dialog_content = "Kamu yang pertama mencuri rancangan untuk Kepiting Api.",
  ui_story_5070_50701201_32_dialog_content = "Kemudian beralih ke penyelundupan bagian dan memimpin para bajak laut untuk menjarah pedagang Lin.",
  ui_story_5070_50701201_33_dialog_content = "Sekarang Anda menggunakan trik yang sama untuk mencuri Api Zhuyin untuk karya kolase mengerikan Anda.",
  ui_story_5070_50701201_34_dialog_content = "Tapi, aku punya pertanyaan nih.",
  ui_story_5070_50701201_35_dialog_content = "Baiklah, akan kudengarkan.",
  ui_story_5070_50701201_36_dialog_content = "Qianyun selalu bangga karena memiliki integritas dan reputasi yang baik.",
  ui_story_5070_50701201_37_dialog_content = "Jadi kapan hal ini mulai mempromosikan pencurian dan taktik curang seperti ini?",
  ui_story_5070_50701201_38_dialog_content = "Ha…",
  ui_story_5070_50701201_39_dialog_content = "Oh, ternyata kamu mengenaliku.",
  ui_story_5070_50701201_40_dialog_content = "Tapi yang selalu kamu pedulikan hanyalah mekanik. Aku jadi bertanya-tanya apakah wajahku masih dikenal.",
  ui_story_5070_50701201_41_dialog_content = "Sudah lama, Xuan Ji... adik perempuanku yang lebih muda.",
  ui_story_5070_50701201_42_dialog_content = "Zhui Hu.",
  ui_story_5070_50701201_43_dialog_content = "Tak bisa memanggilku \"kakak senior,\" ya? Menteri terkenal Armilla memang berbeda dari masa lalu.",
  ui_story_5070_50701201_44_dialog_content = "Kau sudah lama diusir dan tak pantas menyebut dirimu apa pun.",
  ui_story_5070_50701201_45_dialog_content = "Heh, kata-kata tajam lagi... Tahu apa? Aku akan membiarkannya kali ini.",
  ui_story_5070_50701201_46_dialog_content = "Bagaimanapun, sejak kecil Anda dianggap sebagai seorang jenius oleh sekte, selalu mendapatkan apa yang Anda inginkan. Tetapi sekarang, Anda tidak memiliki cara untuk menangani karya dari seorang murid yang ditinggalkan...",
  ui_story_5070_50701201_47_dialog_content = "Pasti sedikit terasa pedih.",
  ui_story_5070_50701201_48_dialog_content = "Tapi tak apa. Meskipun kamu mungkin tidak peduli tentang masa lalu kita, aku peduli.",
  ui_story_5070_50701201_49_dialog_content = "Jadi, mengingat masa lalu kita bersama tumbuh besar di sekte ini, jika kamu jujur mengakui kekalahan, saya bersedia untuk membiarkanmu pergi.",
  ui_story_5070_50701201_50_dialog_content = "Adik, mungkin kamu belum tahu... tapi era para ahli strategi akan segera menyingsing!",
  ui_story_5070_50701201_51_dialog_content = "Dalam lanskap politik yang selalu berubah dari delapan kerajaan vasal di masa depan, bakat seperti kamu akan selalu menemukan pijakan.",
  ui_story_5070_50701201_52_dialog_content = "Kapal ini di bawah kakimu. Anggap saja ini sebagai hadiah perpisahan dariku untukmu. Bagaimana itu?",
  ui_story_5070_50701201_53_dialog_content = "Tentu saja.",
  ui_story_5070_50701201_54_dialog_content = "Kamu tidak hanya mengejar Api Zhuyin tetapi juga Shadowind.",
  ui_story_5070_50701201_55_dialog_content = "Tapi aku tidak menyangka kamu akan meninggalkanku terdampar di laut untuk mati.",
  ui_story_5070_50701201_56_dialog_content = "Sejujurnya, aku tidak bisa menyembunyikan apapun dari mata tajammu.",
  ui_story_5070_50701201_57_dialog_content = "Karena kapal ini merupakan tiruan dari Shadowind, meskipun hanya dalam penampilan dan tidak bisa dibandingkan.",
  ui_story_5070_50701201_58_dialog_content = "Setelah semua, inti dari Shadowind diciptakan melalui usaha gabungan dari banyak ahli. Sulit bagi saya untuk menirunya sendiri.",
  ui_story_5070_50701201_59_dialog_content = "Sebenarnya, misi awal saya hanyalah untuk mendapatkan cetak biru dari Shadowind.",
  ui_story_5070_50701201_60_dialog_content = "Tapi karena ada kesempatan untuk mengambil seluruh kapal, kenapa tidak?",
  ui_story_5070_50701201_61_dialog_content = "Meskipun Shadowind saat ini kacau karena perubahan yang Anda lakukan secara sembrono...",
  ui_story_5070_50701201_62_dialog_content = "Tapi, aku tidak keberatan menghadapi kekacauan ini.",
  ui_story_5070_50701201_63_dialog_content = "(Misi, katamu...)",
  ui_story_5070_50701201_64_dialog_content = "Dibandingkan dengan mengobrol dengan anak-anak muda lokal yang keras kepala di penjara bawah tanah, cara melakukan hal ini jauh lebih memuaskan.",
  ui_story_5070_50701201_65_dialog_content = "Jadi kamu juga dalang di balik perampokan kapal Lin?",
  ui_story_5070_50701201_66_dialog_content = "Cepat tanggap, ya?",
  ui_story_5070_50701201_67_dialog_content = "Dengan teknik menyamar dan meniru yang mudah ini...",
  ui_story_5070_50701201_68_dialog_content = "Dulu sangat mudah untuk berpura-pura menjadi penumpang atau pekerja kapal dan merusak pertahanan kapal dari dalam.",
  ui_story_5070_50701201_69_dialog_content = "Saya telah membuat persiapan yang teliti di Twin Pavilions Bay, dengan harapan untuk mengulang kembali apa yang terjadi di Shadowind...",
  ui_story_5070_50701201_70_dialog_content = "Hingga aku menemukan bahwa ada sesuatu yang istimewa tersembunyi di kabin itu.",
  ui_story_5070_50701201_71_dialog_content = "Saya tidak pernah menyangka bahwa kamu, adik junior terkasih, bisa benar-benar menemukan Api Zhuyin legendaris.",
  ui_story_5070_50701201_72_dialog_content = "Dan karena aku menciptakan makhluk mekanik ini, sebuah puncak penciptaan yang menggabungkan kekuatan dari semua aliran, aku belum bisa menemukan sumber tenaga yang cocok.",
  ui_story_5070_50701201_73_dialog_content = "Mungkin terlihat seperti kebetulan, tetapi menurutku, ini adalah anugerah takdir!",
  ui_story_5070_50701201_74_dialog_content = "Huh...",
  ui_story_5070_50701201_75_dialog_content = "... Apa maksudmu dengan itu?",
  ui_story_5070_50701201_76_dialog_content = "Kamu tidak pernah berubah.",
  ui_story_5070_50701201_77_dialog_content = "Sampai saat ini, mengapa kamu masih berusaha bertingkah seperti jenius dari sekte kita dan ahli mesin?",
  ui_story_5070_50701201_78_dialog_content = "Belum bisa menerima kenyataan juga, adik?",
  ui_story_5070_50701201_79_dialog_content = "Bahkan kamu pun tidak bisa meninggalkan goresan pada binatang jam buatan saya, ciptaan terhebat saya!",
  ui_story_5070_50701201_80_dialog_content = "Binatang mekanik \"milikmu\"?",
  ui_story_5070_50701201_81_dialog_content = "Kamu hanya meniru desain, mencuri inti, dan menggabungkan bagian-bagian yang kuat.",
  ui_story_5070_50701201_82_dialog_content = "Apakah ada sesuatu yang orisinal dalam karya \"milikmu\" itu?",
  ui_story_5070_50701201_83_dialog_content = "Mengapa suaramu terdengar seperti orang-orang tua kaku dari sekte itu?",
  ui_story_5070_50701201_84_dialog_content = "Seni mesin hanyalah keterampilan teknis; selama ciptaannya cukup kuat, tak perlu khawatir tentang hal lain.",
  ui_story_5070_50701201_85_dialog_content = "Bahkan jika itu mereka, di hadapan Stinger yang telah sempurna ini, mereka tidak akan punya pilihan selain tunduk dalam kekalahan!",
  ui_story_5070_50701201_86_dialog_content = "Itulah mengapa para guru kami mengatakan bahwa Anda tidak pernah memahami makna dari gadget.",
  ui_story_5070_50701201_87_dialog_content = "Jika mereka melihat Anda sekarang, mereka mungkin akan menyesal karena tidak bisa mengusir Anda untuk kedua kalinya.",
  ui_story_5070_50701201_88_dialog_content = "...Seharusnya aku tidak membuang banyak waktu untuk mencoba berbicara masuk akal denganmu.",
  ui_story_5070_50701201_89_dialog_content = "Hancurkan dia, Stinger. Tunjukkan padanya kekuatan sejati yang seharusnya dimiliki oleh Clockwork Beast!",
  ui_story_5070_50701201_90_dialog_content = "Para bajak laut di Shadowind akhirnya telah ditangani. Apakah semua orang baik-baik saja?",
  ui_story_5070_50701201_91_dialog_content = "Kita pada dasarnya baik-baik saja, tetapi beberapa tukang kapal kita terluka dan beberapa penumpang kita hilang.",
  ui_story_5070_50701201_92_dialog_content = "Jiu terjatuh ke laut karena lukanya dan belum ada tanda-tanda darinya...",
  ui_story_5070_50701201_93_dialog_content = "Yang Mulia! Apakah Anda baik-baik saja?",
  ui_story_5070_50701201_94_dialog_content = "Jiu! Kenapa kamu khawatir tentang aku? Seberapa parah lukamu?",
  ui_story_5070_50701201_95_dialog_content = "Aku baru saja tidak sengaja menelan beberapa tegukan air.",
  ui_story_5070_50701201_96_dialog_content = "Tapi aku gagal dalam tugas sebagai pengawalmu dengan meninggalkan sisi Anda saat ini. Tolong hukum aku.",
  ui_story_5070_50701201_97_dialog_content = "Berhenti. Kamu bisa menghindari sinar itu jika bukan karena melindungi aku...",
  ui_story_5070_50701201_98_dialog_content = "Bagaimana aku bisa memarahi kamu? Ayo periksa Jiu, Liqing...",
  ui_story_5070_50701201_99_dialog_content = "Terima kasih.",
  ui_story_5070_50701201_100_dialog_content = "Dengan Jiu kembali, hanya tersisa Menteri Armilla...",
  ui_story_5070_50701201_101_dialog_content = "Xuan Ji mungkin ada di kapal yang berseberangan itu.",
  ui_story_5070_50701201_102_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50701201_103_dialog_content = "Cahaya aneh itu lagi...",
  ui_story_5070_50701201_104_dialog_content = "Baiklah, mari kita lihat.",
  ui_story_5070_50701201_105_dialog_content = "Apa yang dia lawan?! Kenapa dia hanya menghindar tanpa melakukan serangan balik?!",
  ui_story_5070_50701201_106_dialog_content = "Aku tak tahan lagi! Zhong Xu, ayo kita bantu dia.",
  ui_story_5070_50701201_107_dialog_content = "Jika aku menyelamatkannya tepat waktu, dia pasti akan malu untuk memanggilku mungil lagi!",
  ui_story_5070_50701201_108_dialog_content = "Mungkin tak perlu.",
  ui_story_5070_50701201_109_dialog_content = "Tidak mungkin... Apakah dia juga menyinggungmu? Kau benar-benar berencana membiarkan dia mati?",
  ui_story_5070_50701201_110_dialog_content = "Yang aku katakan adalah Menteri Armilla tidak membutuhkan bantuan kita.",
  ui_story_5070_50701201_111_dialog_content = "Yep. Sepertinya dia tidak berlarian ke mana-mana hanya untuk bersembunyi.",
  ui_story_5070_50701201_112_dialog_content = "Saya rasa dia sengaja menggunakan serangan dari sisi yang berlawanan untuk menghancurkan sekitarnya.",
  ui_story_5070_50701201_113_dialog_content = "Aku ingin menghancurkan tempat perlindungan Clockwork Beast itu!",
  ui_story_5070_50701201_114_dialog_content = "Tapi kenapa dia melakukan itu?",
  ui_story_5070_50701201_115_dialog_content = "Entahlah... Sebenarnya, mungkin aku tahu.",
  ui_story_5070_50701201_116_dialog_content = "Jadi, meskipun Anda memperkuat Shadowind dengan setiap bahan terakhir yang dapat Anda kumpulkan...",
  ui_story_5070_50701201_117_dialog_content = "Ini tidak akan mampu menghadapi Api Zhuyin dengan kekuatan penuh.",
  ui_story_5070_50701201_118_dialog_content = "Mengabaikan lubang besar di geladak adalah satu hal, tapi sengaja membuatnya lebih besar?",
  ui_story_5070_50701201_119_dialog_content = "Hampir saja terungkap inti dari Shadowind. Itu terlalu aneh... Sun, apa pendapatmu tentang ini?",
  ui_story_5070_50701201_120_dialog_content = "Tolong jaga rahasia tentang percobaan yang gagal dan seseorang yang mengincar Api itu.",
  ui_story_5070_50701201_121_dialog_content = "Mungkin... Tapi sekarang kita harus bagaimana?",
  ui_story_5070_50701201_122_dialog_content = "Tunggu saja.",
  ui_story_5070_50701201_123_dialog_content = "(...Tidak mungkin.)",
  ui_story_5070_50701201_124_dialog_content = "(Jika itu yang aku pikirkan, Xuan Ji, kamu tidak punya hak untuk menyebutku nekat lagi.)",
  ui_story_5070_50701201_125_dialog_content = "(Kamu akan menjadi pemberani terbesar di kapal ini!)",
  ui_story_5070_50701201_126_dialog_content = "Apa yang sedang kamu lihat, PlayerName? Apakah ada sesuatu di dalam lubang besar itu di atas geladak?",
  ui_story_5070_50701201_127_dialog_content = "Tidak sekarang.",
  ui_story_5070_50701201_128_dialog_content = "Tapi akan segera ada.",
  ui_story_5070_50701201_129_dialog_content = "Semuanya! Tolong bantu saya!",
  ui_story_5070_50701201_130_dialog_content = "Kita perlu memancing Binatang Jam mekanik itu ke Shadowind!",
  ui_story_5070_50701201_131_dialog_content = "Kilat Flash—",
  ui_story_5070_50701201_132_dialog_content = "Kan sudah kubilang tak ada gunanya, bukan?",
  ui_story_5070_50701201_133_dialog_content = "Setiap bagian dari Stinger dibuat dengan desain terbaik yang saya temukan di seluruh dunia.",
  ui_story_5070_50701201_134_dialog_content = "Semua seranganmu sia-sia!",
  ui_story_5070_50701201_135_dialog_content = "Aku tak yakin.",
  ui_story_5070_50701201_136_dialog_content = "?!",
  ui_story_5070_50701201_137_dialog_content = "PlayerName? Jika kamu bisa terhubung pikiran denganku, kamu pasti sudah berhasil di ujungmu.",
  ui_story_5070_50701201_138_dialog_content = "Haha... Terima kasih, Zhong Xu. Tapi kita bisa bicarakan ini nanti saja.",
  ui_story_5070_50701201_139_dialog_content = "Aku mendengar apa yang kamu katakan tadi. Ternyata ledakan hari itu disebabkan oleh Sun the Skillful yang palsu ini.",
  ui_story_5070_50701201_140_dialog_content = "Disambar petir karena mencuri. Orang-orang dari Longzhou akan menyebutnya sebagai pembalasan ilahi.",
  ui_story_5070_50701201_141_dialog_content = "Dia benar-benar mengira itu takdir? Aku tidak ingin mengalami hal seperti sambaran petir itu.",
  ui_story_5070_50701201_142_dialog_content = "Aku juga tidak!",
  ui_story_5070_50701201_143_dialog_content = "Selain itu, binatang mekanik miliknya terlalu jelek. Semua gerakan berputarnya itu sangat menjijikkan!",
  ui_story_5070_50701201_144_dialog_content = "Aku memang bilang itu satu kekacauan besar yang buruk.",
  ui_story_5070_50701201_145_dialog_content = "... Aku tak pernah menyangka bahwa Shadowind akan dibandingkan dengan sesuatu seperti itu.",
  ui_story_5070_50701201_146_dialog_content = "... Cukup sudah!",
  ui_story_5070_50701201_147_dialog_content = "Stinger! Menuju ke Shadowind dan singkirkan semua orang bodoh yang tidak tahu ini!",
  ui_story_5070_50701202_1_dialog_content = "Hewan mesin penggerakku yang... paling kuat... Bagaimana ini bisa terjadi...",
  ui_story_5070_50701202_2_dialog_content = "Kenapa kamu...!",
  ui_story_5070_50701202_3_dialog_content = "Akan terus seperti ini? Aku tidak ingat kamu menjadi petarung yang baik.",
  ui_story_5070_50701202_4_dialog_content = "Ha... Haha, hahaha!",
  ui_story_5070_50701202_5_dialog_content = "Jangan terlalu bersemangat dulu! Kakak senior, kau seharusnya tidak lupa akan kekuatan Stinger-ku, kan?",
  ui_story_5070_50701202_6_dialog_content = "Api Zhuyin! Inilah seni keterampilan sejati yang menyediakan energi tak terbatas untuk ciptaan mekanik!",
  ui_story_5070_50701202_7_dialog_content = "Bangun, Stinger! Pertempurannya belum berakhir!",
  ui_story_5070_50701202_8_dialog_content = "Semuanya, awas! Orang besar itu bergerak lagi!",
  ui_story_5070_50701202_9_dialog_content = "Jadi, semuanya belum berakhir. Yang Mulia, silakan mundur.",
  ui_story_5070_50701202_10_dialog_content = "Kamu yang merayakan terlalu dini.",
  ui_story_5070_50701202_11_dialog_content = "Tatapan itu lagi... Jangan pernah memberiku tatapan angkuh seperti itu! Aku—",
  ui_story_5070_50701202_12_dialog_content = "PlayerName, coba tahan dia! Aku hanya butuh sedikit waktu!",
  ui_story_5070_50701202_13_dialog_content = "Force Boost!",
  ui_story_5070_50701202_14_dialog_content = "Ugh—!",
  ui_story_5070_50701202_15_dialog_content = "Aku akan membuatnya pusing sebentar, dan kalian dorong binatang itu masuk sekarang!",
  ui_story_5070_50701202_16_dialog_content = "Dorong itu? Dorong kemana? Lubang di geladak?!",
  ui_story_5070_50701202_17_dialog_content = "Itu bukan hanya lubang biasa.",
  ui_story_5070_50701202_18_dialog_content = "Saya membuat itu khusus untuknya.",
  ui_story_5070_50701202_19_dialog_content = "Satu... Dua... Tiga!",
  ui_story_5070_50701202_20_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5070_50701202_21_dialog_content = "Kita berhasil! Orang itu benar-benar berat.",
  ui_story_5070_50701202_22_dialog_content = "Aku akan mengambil alih dari sini.",
  ui_story_5070_50701202_23_dialog_content = "Dengan beberapa modifikasi, kita bisa menghubungkannya ke Shadowind.",
  ui_story_5070_50701202_24_dialog_content = "Aduh... A-apa yang akan kamu lakukan...!",
  ui_story_5070_50701202_25_dialog_content = "Saya yakin Anda melihat draf perubahan untuk Shadowind dalam penyamaran Sun Anda, bukan?",
  ui_story_5070_50701202_26_dialog_content = "Jangan bercanda... Itu bahkan tidak mungkin...",
  ui_story_5070_50701202_27_dialog_content = "Untuk mendukung kapal sebesar Shadowind dengan struktur seperti itu...",
  ui_story_5070_50701202_28_dialog_content = "Dibutuhkan inti dengan tingkat kekuatan yang sama dengan Api Zhuyin dalam kecepatan penuh.",
  ui_story_5070_50701202_29_dialog_content = "Dengan material Shadowind saja, itu bahkan tidak bisa menahan dampak...",
  ui_story_5070_50701202_30_dialog_content = "Kamu benar, itu hanya angan-angan jika hanya itu saja.",
  ui_story_5070_50701202_31_dialog_content = "Tapi untuk menciptakan makhluk jam mekanik yang paling kuat...",
  ui_story_5070_50701202_32_dialog_content = "Apakah kamu tidak menggunakan bahan yang dapat menahan Api Zhuyin dengan kekuatan penuh?",
  ui_story_5070_50701202_33_dialog_content = "Tunggu, maksud kamu... Kau gila?! Ini benar-benar...",
  ui_story_5070_50701202_34_dialog_content = "Makanya kukatakan kamu terlalu sibuk dengan desain sampai-sampai tidak mengerti tentang perangkat.",
  ui_story_5070_50701202_35_dialog_content = "Selama bahan tersedia, perangkat gadget tidak terbatas dalam apa yang dapat diciptakan.",
  ui_story_5070_50701202_36_dialog_content = "Apa maksudmu?",
  ui_story_5070_50701202_37_dialog_content = "Tetap di sini, Nak. Sebentar lagi kau akan tahu.",
  ui_story_5070_50701202_38_dialog_content = "Benamkan diri Anda dengan semua indera dalam pengalaman sekali seumur hidup ini.",
  ui_story_5070_50701202_39_dialog_content = "Saya akan menggunakan binatang itu sebagai sumber tenaga untuk mengatur keluaran Api Zhuyin.",
  ui_story_5070_50701202_X39_dialog_content = "Dan buatlah Shadowind...",
  ui_story_5070_50701202_40_dialog_content = "Terbang sebentar saja!",
  ui_story_5070_50701202_41_dialog_content = "<color=#e8d9bb>Tiupan peluit</color>",
  ui_story_5070_50701202_42_dialog_content = "<color=#e8d9bb>Di bawah perintah Xuan Ji, mereka yang masih bisa bergerak sementara waktu mengambil alih tugas para tukang kapal.</color>",
  ui_story_5070_50701202_43_dialog_content = "<color=#e8d9bb>Dengan suara peluit, semua mekanisme modifikasi pada Shadowind langsung bergerak sekaligus.</color>",
  ui_story_5070_50701202_44_dialog_content = "<color=#e8d9bb>Kapal bergetar, roda gigi di dalamnya saling bertabrakan dan memanjang... Sinar Lumina terhampar di kedua sisi kapal seperti banyak sayap!</color>",
  ui_story_5070_50701202_45_dialog_content = "Maukah Anda melakukannya, PlayerName?",
  ui_story_5070_50701202_46_dialog_content = "Force Boost!",
  ui_story_5070_50701202_47_dialog_content = "(Rasakan Nyala Zhuyin dan rangsang kekuatannya hingga maksimal! Lalu...)",
  ui_story_5070_50701202_48_dialog_content = "(Shadowind, bergerak!)",
  ui_story_5070_50701202_49_dialog_content = "Tidak mungkin... Tidak mungkin banget!",
  ui_story_5070_50701202_50_dialog_content = "Sial... ini hanya keberuntungan sesaat! Kita... ini belum berakhir!",
  ui_story_5070_50701202_51_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5070_50701202_52_dialog_content = "Dia melompat ke laut!",
  ui_story_5070_50701202_53_dialog_content = "Jangan hiraukan dia.",
  ui_story_5070_50701202_54_dialog_content = "Sayap hanya bisa menopang kapal dalam waktu terbatas. Kita harus memanfaatkan kesempatan ini dan keluar dari sini.",
  ui_story_5070_50701202_55_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5070_50701202_56_dialog_content = "(Shadowind hanya berada di udara sebentar, dan saya sudah bisa mendengar suara mesin yang kelebihan beban.)",
  ui_story_5070_50701202_57_dialog_content = "(Dengan dorongan terakhir, cahaya yang tebal mulai menghilang di udara.)",
  ui_story_5070_50701202_58_dialog_content = "(Itu cukup.)",
  ui_story_5070_50701202_59_dialog_content = "Matahari, angin sepoi-sepoi, dan ombak tenang... Kita berhasil keluar!",
  ui_story_5070_50701202_60_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5070_50701202_61_dialog_content = "<color=#e8d9bb>Shadowind jatuh keras kembali ke laut.</color>",
  ui_story_5070_50701202_62_dialog_content = "<color=#e8d9bb>Tapi kali ini, sekitarnya tenang, tanpa ada pusaran air atau arus tersembunyi lagi.</color>",
  ui_story_5070_50701202_63_dialog_content = "Kita berhasil!",
  ui_story_5070_50701202_64_dialog_content = "Kamu luar biasa, Xuan Ji!",
  ui_story_5070_50701202_65_dialog_content = "Ini gadget yang hebat.",
  ui_story_5070_50701202_66_dialog_content = "Tapi kali ini, aku akan menahan rasa rendah hati dan menerima pujianmu.",
  ui_story_5070_50701202_67_dialog_content = "Ngomong-ngomong, meskipun tidak berlangsung lama, Shadowind memang sempat melintasi langit.",
  ui_story_5070_50701202_68_dialog_content = "Dan kali ini, Xuan Ji telah secara sah menjadi navigator dari Shadowind.",
  ui_story_5070_50701202_69_dialog_content = "Saya melakukan itu, bukan?",
  ui_story_5070_50701202_70_dialog_content = "Aku tidak akan pernah melupakan perasaan itu.",
  ui_story_5070_50701202_71_dialog_content = "(Setelah menyeberangi samudra, Xuan Ji dengan cepat menggunakan astrolab dan peralatan lainnya untuk membantu Shadowind kembali ke jalur yang benar.)",
  ui_story_5070_50701202_72_dialog_content = "(Keesokan harinya, kami menemukan reruntuhan kapal Zhui Hu tidak jauh dari sana.)",
  ui_story_5070_50701202_73_dialog_content = "Kapal itu tenggelam di laut seperti kapal Lin Guild yang tenggelam karena skema yang dia buat. Hukum sebab-akibat berlaku di sini.",
  ui_story_5070_50701202_74_dialog_content = "Tapi orang-orang seperti Zhui Hu dan para pendukungnya tidak akan mati begitu saja. Mereka juga tidak akan menyerah begitu saja.",
  ui_story_5070_50701202_75_dialog_content = "Tak ada yang tahu rencana apa lagi yang akan mereka tetaskan.",
  ui_story_5070_50701202_76_dialog_content = "Pokoknya, kita akan menemukan cara untuk mengatasinya. Selalu ada cara untuk menghadapi segala jenis musuh.",
  ui_story_5070_50701202_77_dialog_content = "Bahkan jika tidak, kita bisa berimprovisasi di tempat.",
  ui_story_5070_50701202_78_dialog_content = "Bukankah Zhui Hu pernah menjadi guru Anda, Xuan Ji?",
  ui_story_5070_50701202_79_dialog_content = "Meskipun ia diusir, setidaknya ia pernah menjadi murid dari sekte besar.",
  ui_story_5070_50701202_80_dialog_content = "Dia harus jauh lebih kuat daripada orang biasa untuk bisa menciptakan sesuatu seperti itu.",
  ui_story_5070_50701202_81_dialog_content = "Bagaimana dia bisa dipekerjakan untuk berperan sebagai bajak laut atau penyelundup?",
  ui_story_5070_50701202_82_dialog_content = "Aku punya petunjuk.",
  ui_story_5070_50701202_83_dialog_content = "Tapi aku tidak tahu apakah baik atau buruk untuk mengikuti pemikiran seperti itu.",
  ui_story_5070_50701202_84_dialog_content = "Zhui Hu mempelajari banyak teknik tetapi tidak pernah menyadari apa sebenarnya gadget itu.",
  ui_story_5070_50701202_85_dialog_content = "Kita membahas hasil dari berabad-abad latihan dan tekad.",
  ui_story_5070_50701202_86_dialog_content = "Hal itu tidak bisa dipahami melalui tipu muslihat dan pencurian.",
  ui_story_5070_50701202_87_dialog_content = "Saya membawa semua yang Anda minta, Xuan Ji.",
  ui_story_5070_50701202_88_dialog_content = "Tetapi kami hanya memiliki beberapa amplop ini untuk berkomunikasi dengan paman besar saya yang tersisa di kapal ini.",
  ui_story_5070_50701202_89_dialog_content = "Untuk tujuan apa kamu membutuhkan mereka?",
  ui_story_5070_50701202_90_dialog_content = "Yah, aku akan tahu saat aku melihat mereka.",
  ui_story_5070_50701202_91_dialog_content = "Oh, bagaimana keadaan Jiu sekarang?",
  ui_story_5070_50701202_92_dialog_content = "Aku lihat kamu masih peduli.",
  ui_story_5070_50701202_93_dialog_content = "Liqing memeriksanya dan dia akan pulih sepenuhnya dalam beberapa hari.",
  ui_story_5070_50701202_94_dialog_content = "(Nada percakapan kembali menjadi ringan dan hidup seperti biasanya.)",
  ui_story_5070_50701202_95_dialog_content = "(Aku melihat Xuan Ji dengan hati-hati menyimpan surat-surat itu...)",
  ui_story_5070_50701202_X95_dialog_content = "(Meskipun dia tidak pernah menjawab pertanyaan, \"Apa gunanya?\".)",
  ui_story_5070_50701301_1_dialog_content = "(Dua hari terakhir di kapal berlalu begitu cepat.)",
  ui_story_5070_50701301_2_dialog_content = "(Semua orang lelah secara fisik dan mental akibat semua krisis dan pertempuran.)",
  ui_story_5070_50701301_3_dialog_content = "(Beruntung, tepat saat perbaikan selesai—Longzhou pun terlihat.)",
  ui_story_5070_50701301_4_dialog_content = "Perjalanan ini penuh dengan banyak liku-liku, tetapi semuanya berakhir dengan baik.",
  ui_story_5070_50701301_5_dialog_content = "Shadowind telah kembali. Perjalanan ini resmi berakhir.",
  ui_story_5070_50701301_6_dialog_content = "Atas nama Shadowind, saya ingin berterima kasih kepada semua orang yang telah membantu kami sepanjang perjalanan ini.",
  ui_story_5070_50701301_7_dialog_content = "Jangan abaikan kelebihan diri Anda dalam hal ini.",
  ui_story_5070_50701301_8_dialog_content = "Kami tiba dengan selamat dan membuka kembali rute tersebut. Kami dan Shadowind telah menyelesaikan misi kami.",
  ui_story_5070_50701301_9_dialog_content = "Putri Dantang, seseorang baru saja mengirim pesan bahwa utusan Kerajaan Ji sedang menunggu di pelabuhan untuk mengantar Anda kembali ke istana.",
  ui_story_5070_50701301_10_dialog_content = "Aku memiliki semua informasi, jadi aku harus segera melaporkannya.",
  ui_story_5070_50701301_11_dialog_content = "Saya melihat banyak pertemuan dan jamuan makan di masa depan yang tidak terlalu jauh.",
  ui_story_5070_50701301_12_dialog_content = "Kamu juga harus siap, PlayerName.",
  ui_story_5070_50701301_13_dialog_content = "Hah? Aku?",
  ui_story_5070_50701301_14_dialog_content = "Oh ya! Saya benar-benar lupa bahwa saya datang ke Longzhou sebagai utusan Astra!",
  ui_story_5070_50701301_15_dialog_content = "A-Apa yang harus kulakukan? Tiba-tiba saja aku merasa gugup.",
  ui_story_5070_50701301_16_dialog_content = "Jangan khawatir, anggap saja ini sebagai melihat sisi lain dari Longzhou.",
  ui_story_5070_50701301_17_dialog_content = "Akhirnya aku kembali. Untuk sesaat tadi, aku pikir aku akan menghabiskan hidupku di Astra...",
  ui_story_5070_50701301_18_dialog_content = "Sekarang setelah kupikirkan, rasanya semuanya telah berubah meskipun baru setengah tahun sejak aku pergi dari Longzhou.",
  ui_story_5070_50701301_19_dialog_content = "Cukup. Sekarang, cari tahu apa yang akan kita lakukan selanjutnya!",
  ui_story_5070_50701301_20_dialog_content = "Mau makan makanan enak? Atau tidur nyenyak malam ini?",
  ui_story_5070_50701301_21_dialog_content = "Kembali ke Lin Guild.",
  ui_story_5070_50701301_22_dialog_content = "Dengan bantuan Putri Dantang dan yang lainnya, dapat dibuktikan bahwa Lin Guild dihukum secara tidak adil atas tuduhan penyelundupan.",
  ui_story_5070_50701301_23_dialog_content = "Setelah semua yang terjadi, pasti ada banyak masalah yang memerlukan penanganan segera.",
  ui_story_5070_50701301_24_dialog_content = "Guildmaster... Guildmaster pasti masih menunggu untukku!",
  ui_story_5070_50701301_25_dialog_content = "Hei! Tunggu!",
  ui_story_5070_50701301_26_dialog_content = "Jangan khawatir.",
  ui_story_5070_50701301_27_dialog_content = "Saya telah melaporkan semuanya saat kita mendarat dan mengirim pelayan untuk mengambil bukti dan uang ke Kantor Perdagangan Maritim...",
  ui_story_5070_50701301_28_dialog_content = "Guildmaster seharusnya sudah dibebaskan. Sekarang saatnya untuk reuni Anda.",
  ui_story_5070_50701301_29_dialog_content = "Lihat ke sana.",
  ui_story_5070_50701301_30_dialog_content = "... Semua ini salah Xuan Ji. Dia membuat kursi roda Zhong Xu terlalu cepat.",
  ui_story_5070_50701301_31_dialog_content = "Kakak Zhong!",
  ui_story_5070_50701301_32_dialog_content = "Lin?",
  ui_story_5070_50701301_33_dialog_content = "Saya tidak pernah menyangka bahwa Anda masih mau keluar menyambut saya sekarang setelah saya kehilangan kakiku.",
  ui_story_5070_50701301_34_dialog_content = "Kata-katamu... Aku tidak tahu bagaimana harus menanggapinya...",
  ui_story_5070_50701301_35_dialog_content = "Saya bahkan tidak tahu apakah saya harus mengungkapkan rasa terima kasih dulu atau meminta maaf kepada kamu.",
  ui_story_5070_50701301_36_dialog_content = "Tidak perlu kata-kata seperti itu di antara kita.",
  ui_story_5070_50701301_37_dialog_content = "Jika kamu benar-benar ingin melakukan sesuatu, selamat datang Liqing dan Kapten Yuebai terlebih dahulu.",
  ui_story_5070_50701301_38_dialog_content = "Aku... Sudah cukup bagiku melihat kamu baik-baik saja!",
  ui_story_5070_50701301_39_dialog_content = "Oh, Jiu, tolong kirimkan surat untukku.",
  ui_story_5070_50701301_40_dialog_content = "Aku harus memberi tahu keluargaku tentang misi yang telah selesai dan kepulanganku yang selamat.",
  ui_story_5070_50701301_41_dialog_content = "Ya. Semua orang akan bahagia untuk Anda, Yang Mulia.",
  ui_story_5070_50701301_42_dialog_content = "Ada yang salah, PlayerName?",
  ui_story_5070_50701301_43_dialog_content = "Banyak orang turun: Dantang, Jiu, Zhong Xu, Liqing, Xuan Ji, dan saya...",
  ui_story_5070_50701301_44_dialog_content = "Tapi, kenapa aku selalu merasa seperti melupakan sesuatu?",
  ui_story_5070_50701301_45_dialog_content = "Eh, lupakan saja. Mungkin tidak penting. Ayo pergi!",
  ui_story_5070_50701301_46_dialog_content = "Lady Xuan Ji, apakah boleh untuk menurunkan lembu kayu ini di sini?",
  ui_story_5070_50701301_47_dialog_content = "Tentu, terima kasih.",
  ui_story_5070_50701301_48_dialog_content = "Tidak masalah. Kami berutang keselamatan kami pada Anda, Lady Xuan Ji, dan kami telah belajar banyak dalam perjalanan ini.",
  ui_story_5070_50701301_49_dialog_content = "Sungguh luar biasa jika kita bisa berlayar bersama lagi lain kali.",
  ui_story_5070_50701301_50_dialog_content = "Ya, semoga kita bertemu lagi.",
  ui_story_5070_50701301_X50_dialog_content = "Hmm? Ia...",
  ui_story_5070_50701301_X51_dialog_content = "Saya sudah lama pergi hingga hampir lupa bagaimana setiap hari terasa seperti musim semi di sepanjang pantai selatan Kerajaan Ji.",
  ui_story_5070_50701301_X52_dialog_content = "Tak pernah kubayangkan aku benar-benar bisa kembali ke Longzhou dengan sesuatu yang sedang kucari...",
  ui_story_5070_50701301_51_dialog_content = "...",
  ui_story_5070_50701301_52_dialog_content = "Oke, kamu sudah melihat banyak.",
  ui_story_5070_50701301_53_dialog_content = "Jadi, tidak adakah hal yang lebih penting yang harus kamu lakukan sekarang?",
  ui_story_5070_50701301_54_dialog_content = "Tunggu, ada apa di dalam lembu kayu ini...?",
  ui_story_5070_50701301_55_dialog_content = "Argh!",
  ui_story_5070_50701301_56_dialog_content = "Terang di luar? Pagi.",
  ui_story_5070_50701301_57_dialog_content = "Apa yang kamu lakukan bersembunyi di sana?",
  ui_story_5070_50701301_58_dialog_content = "Karena... Ugh, bisakah kamu membantuku dan menarikku keluar dulu? Terima kasih.",
  ui_story_5070_50701301_59_dialog_content = "Aduh... Badanku pegal-pegal karena bersembunyi di sana.",
  ui_story_5070_50701301_60_dialog_content = "Siapa sangka bahwa selama perjalanan ini, kita tidak hanya akan menghadapi badai dan Eclipsite, bahkan kita diserang oleh perompak.",
  ui_story_5070_50701301_61_dialog_content = "Untungnya, saya meramal keberuntungan kami sebelum berlayar.",
  ui_story_5070_50701301_62_dialog_content = "Butuh beberapa hari penelitian untuk memahami ramalan Kuda Yin dan Lembu Yin. Mungkin ini sesuai dengan lembu kayu Anda.",
  ui_story_5070_50701301_63_dialog_content = "Begitulah cara saya menemukan tempat yang sempurna untuk bersembunyi. Jika tidak, perjalanan penuh bencana ini mungkin akan merenggut nyawaku.",
  ui_story_5070_50701301_64_dialog_content = "Argh…",
  ui_story_5070_50701301_65_dialog_content = "Itu mengingatkanku, aku berhutang padamu karena menggunakan tempat ini.",
  ui_story_5070_50701301_66_dialog_content = "Bagaimana dengan ramalan gratis?",
  ui_story_5070_50701301_67_dialog_content = "Tak apa.",
  ui_story_5070_50701301_68_dialog_content = "Kami pengrajin lebih menghargai karya ciptaan kami daripada takdir.",
  ui_story_5070_50701301_69_dialog_content = "Bahkan jika kamu meramalkan sesuatu yang mengerikan, itu tidak berarti saya tidak harus melakukan apa yang harus dilakukan!",
  ui_story_5070_50701301_70_dialog_content = "Baiklah. Semoga berhasil untukmu.",
  ui_story_5070_50701301_71_dialog_content = "Sampai jumpa.",
  ui_story_5070_50701301_72_dialog_content = "(Mari kita lihat... Saat aku berada di dalam lembu kayu tadi, aku menggambar...)",
  ui_story_5070_50701301_73_dialog_content = "(Harimau Yang dan Naga Yin? Menarik.)",
  ui_story_5070_50701301_74_dialog_content = "(Itu adalah seekor sapi mati dan kuda diam di kapal, jadi saya tetap bersembunyi dan hampir berhasil menghindari bahaya.)",
  ui_story_5070_50701301_X74_dialog_content = "(Tapi sekarang, itu tanda bahaya.)",
  ui_story_5070_50701301_75_dialog_content = "(Xuan Ji selalu mengingatkan semua orang untuk menjauhi bahaya, tapi dia malah masuk ke sarang harimau?)",
  ui_story_5070_50701301_76_dialog_content = "Kirim surat.",
  ui_story_5070_50701301_77_dialog_content = "Senang bertemu dengan Anda lagi. Dua surat, keduanya akan dikirim ke Kerajaan Ye, benar?",
  ui_story_5070_50701301_78_dialog_content = "Yakinlah. Mereka akan dikirim tepat waktu.",
  ui_story_5070_50701301_79_dialog_content = "<color=#e8d9bb>Tidak jauh dari Pos</color>",
  ui_story_5070_50701301_80_dialog_content = "Pergi melapor kepada tuan kita; Frost Blade berhasil mengawal putri kembali ke Longzhou dengan selamat.",
  ui_story_5070_50701301_81_dialog_content = "Jaga orang-orang di kantor pos; jangan biarkan ada masalah yang belum selesai untuk tuan kita."
}
return config
